common:
// Marrow animated wallpapers: the shared math every wallpaper may call.
// A GLSL ES 3.00 subset that ports to Skia SkSL as written: no textures, no derivatives, no preprocessor, no arrays
// built in the shader, constant loop bounds, no bit operations and no integer modulo. Every function is pure math.
//
// The host declares these uniforms and keeps them eased (so nothing ever cuts):
//   vec3  u_pal[6]   the colour pack: six OKLab colours, already mixed for the theme and crossfaded between packs
//   float u_dark     0 = light theme, 1 = dark theme
//   vec2  u_opt      the wallpaper's two options, each 0..1 (x = motion amount, y = the wallpaper's second option)
//   float u_px       the size of one device pixel in p units, for anti-aliased edges
//   vec2  u_tilt     perspective: the pointer's (or the window's) offset, each -1..1, eased; (0, 0) when Perspective is off
//                    or under Reduce Motion. A wallpaper with depth shifts each layer by tiltD(depth); a flat wallpaper
//                    ignores it (the host pans its whole picture a few pixels instead).
//   vec2  u_sun      dynamic (time of day): the offset to add to the wallpaper's own light position or light direction,
//                    in p units, eased; (0, 0) when Dynamic is off or the wallpaper declares no light
//   float u_focus    Focus, 0 sharp .. 1 dreamy, eased. The host blurs the picture; a wallpaper may also widen its own
//                    hard edges with edgePx().
// wall(p, t): p is the point with the window's height spanning -1..1 (x grows with the aspect), t is the loop clock in
// seconds, 0 <= t < T. All motion is built from a = TAU * t / T, so frame(t) == frame(t + T) exactly.

const float TAU = 6.28318530718;

float sat(float x) { return clamp(x, 0.0, 1.0); }
vec2 rot(vec2 p, float a) { float c = cos(a); float s = sin(a); return vec2(c * p.x - s * p.y, s * p.x + c * p.y); }
vec2 orbit(float a, float r) { return r * vec2(cos(a), sin(a)); }
float gauss(float x, float w) { return exp(-(x * x) / (w * w)); }
// parallax: add tiltD(d) to p before evaluating a layer; d runs from -1 (the farthest layer) to +1 (the nearest). At full
// tilt the nearest layer moves 0.010 p units (4 px at 800 px high), the farthest the other way, so a few pixels at most.
vec2 tiltD(float d) { return u_tilt * (0.010 * d); }
// the width of an anti-aliased edge: one pixel when sharp, wider as Focus rises (use in place of u_px on hard edges)
float edgePx() { return u_px * (1.0 + 14.0 * u_focus); }

// ---- colour: OKLab (Bjorn Ottosson's matrices) and sRGB
vec3 lab2lin(vec3 c) {
  float l = c.x + 0.3963377774 * c.y + 0.2158037573 * c.z;
  float m = c.x - 0.1055613458 * c.y - 0.0638541728 * c.z;
  float s = c.x - 0.0894841775 * c.y - 1.2914855480 * c.z;
  l = l * l * l; m = m * m * m; s = s * s * s;
  return vec3(4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
             -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
             -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s);
}
vec3 lin2lab(vec3 c) {
  c = max(c, vec3(0.0));
  float l = pow(0.4122214708 * c.r + 0.5363325363 * c.g + 0.0514459929 * c.b + 1e-9, 0.3333333);
  float m = pow(0.2119034982 * c.r + 0.6806995451 * c.g + 0.1073969566 * c.b + 1e-9, 0.3333333);
  float s = pow(0.0883024619 * c.r + 0.2817188376 * c.g + 0.6299787005 * c.b + 1e-9, 0.3333333);
  return vec3(0.2104542553 * l + 0.7936177850 * m - 0.0040720468 * s,
              1.9779984951 * l - 2.4285922050 * m + 0.4505937099 * s,
              0.0259040371 * l + 0.7827717662 * m - 0.8086757660 * s);
}
vec3 lin2srgb(vec3 c) {
  c = clamp(c, 0.0, 1.0);
  return mix(c * 12.92, 1.055 * pow(c, vec3(1.0 / 2.4)) - 0.055, step(vec3(0.0031308), c));
}
vec3 outLab(vec3 lab) { return lin2srgb(lab2lin(lab)); }
vec3 lch(float L, float C, float h) { return vec3(L, C * cos(h), C * sin(h)); }
vec3 hueShift(vec3 lab, float a) { return vec3(lab.x, rot(lab.yz, a)); }
vec3 setL(vec3 lab, float L) { return vec3(L, lab.yz); }
// a soft shoulder for light added in linear space: below the knee nothing changes, above it the value rolls toward 1
// and the very brightest light whitens a little, the way film and the eye do
vec3 shoulder(vec3 c) {
  float m = max(c.r, max(c.g, c.b));
  float k = 0.72;
  if (m <= k) return c;
  float n = k + (1.0 - k) * (1.0 - exp(-(m - k) / (1.0 - k)));
  vec3 r = c * (n / m);
  return mix(r, vec3(n), sat((m - 1.0) * 0.18));
}

// ---- noise: gradient noise on a fract-based hash (no sine, so it matches on every GPU)
vec3 hash33(vec3 p) {
  p = fract(p * vec3(0.1031, 0.1030, 0.0973));
  p += dot(p, p.yxz + 33.33);
  return fract((p.xxy + p.yxx) * p.zyx) * 2.0 - 1.0;
}
float gnoise(vec3 p) {
  vec3 i = floor(p);
  vec3 f = p - i;
  vec3 u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
  float n000 = dot(hash33(i), f);
  float n100 = dot(hash33(i + vec3(1.0, 0.0, 0.0)), f - vec3(1.0, 0.0, 0.0));
  float n010 = dot(hash33(i + vec3(0.0, 1.0, 0.0)), f - vec3(0.0, 1.0, 0.0));
  float n110 = dot(hash33(i + vec3(1.0, 1.0, 0.0)), f - vec3(1.0, 1.0, 0.0));
  float n001 = dot(hash33(i + vec3(0.0, 0.0, 1.0)), f - vec3(0.0, 0.0, 1.0));
  float n101 = dot(hash33(i + vec3(1.0, 0.0, 1.0)), f - vec3(1.0, 0.0, 1.0));
  float n011 = dot(hash33(i + vec3(0.0, 1.0, 1.0)), f - vec3(0.0, 1.0, 1.0));
  float n111 = dot(hash33(i + vec3(1.0, 1.0, 1.0)), f - vec3(1.0, 1.0, 1.0));
  return 1.6 * mix(mix(mix(n000, n100, u.x), mix(n010, n110, u.x), u.y),
                   mix(mix(n001, n101, u.x), mix(n011, n111, u.x), u.y), u.z);
}
// a point that travels once round a closed loop in noise space as a goes 0..TAU: the loop is how noise animates and
// still repeats exactly
vec3 loop3(vec2 p, float a, float r) { return vec3(p.x + r * cos(a), p.y + r * sin(a), r * sin(a + 2.1)); }
float lnoise(vec2 p, float a, float r) { return gnoise(loop3(p, a, r)); }
float fbm3(vec3 p) {
  float s = 0.0; float w = 0.5;
  for (int i = 0; i < 3; i++) { s += w * gnoise(p); p = p * 2.03 + vec3(1.7, 9.2, 3.1); w *= 0.5; }
  return s;
}
float fbm4(vec3 p) {
  float s = 0.0; float w = 0.5;
  for (int i = 0; i < 4; i++) { s += w * gnoise(p); p = p * 2.03 + vec3(1.7, 9.2, 3.1); w *= 0.5; }
  return s;
}

wallpapers.glsl:
// Borealis: curtains of aurora over a night sky. Each curtain has a bright foot and a long upward fade, folds that
// travel along it, and vertical rays that shimmer. In light mode the curtains are washes of colour on a dawn sky.
// Palette: 0 zenith, 1 horizon, 2 curtain foot, 3 curtain body, 4 curtain crown, 5 horizon glow.
// Options: x = motion (how far the curtains fold and sway), y = glow.
const float T = 60.0;

float stars(vec2 p, float a) {
  float sc = 30.0;
  vec2 q = p * sc;
  vec2 id = floor(q);
  vec3 h = hash33(vec3(id, 3.7)) * 0.5 + 0.5;
  vec2 c = id + 0.5 + (h.xy - 0.5) * 0.7;
  float d = length(q - c) / sc;
  float r = 0.85 * u_px;
  float s = exp(-(d * d) / (r * r)) * step(0.84, h.z) * (h.z - 0.84) * 6.0;
  float tw = 0.7 + 0.3 * sin(a * 3.0 + h.x * TAU);
  float vis = sat((1.0 / sc) / u_px / 9.0 - 0.5);
  return s * tw * vis;
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.6, u_opt.x);
  float glow = mix(0.5, 1.5, u_opt.y);
  float g = sat(p.y * 0.5 + 0.5);
  vec3 sky = mix(u_pal[1], u_pal[0], smoothstep(0.0, 0.9, g));
  vec3 skyLin = lab2lin(sky);
  vec3 add = vec3(0.0);
  float wsum = 0.0;
  float wl = 0.0;
  for (int i = 0; i < 3; i++) {
    float f = float(i);
    float x = p.x * (0.85 + 0.12 * f) + f * 1.7;
    float base = -0.46 + 0.29 * f + 0.1 * p.x * (1.0 - f);
    float fold = 0.12 * sin(x * 1.2 + a + f * 2.0) + 0.05 * sin(x * 2.5 - 2.0 * a + f);
    fold += 0.15 * m * lnoise(vec2(x * 0.55, f * 4.0), a + f * 1.3, 0.55);
    float d = p.y - (base + fold);
    float h = 0.38 + 0.1 * f;
    float prof = d < 0.0 ? exp(-(d * d) / 0.0016) : exp(-d / h) * (0.4 + 0.6 * exp(-(d * d) / 0.02));
    float cov = smoothstep(-0.4, 0.45, lnoise(vec2(x * 0.4 + 3.0 * f, 7.0 + f), a, 0.45 + 0.3 * m));
    float rays = sat(0.55 + 0.6 * lnoise(vec2(x * 6.5 + fold * 8.0, 2.0 * f), 2.0 * a, 0.12 + 0.3 * m));
    rays = mix(1.0, rays * rays * 1.5, smoothstep(-0.02, 0.12, d) * 0.85);
    vec3 col = mix(u_pal[2], u_pal[3], smoothstep(0.0, 0.18, d));
    col = mix(col, u_pal[4], smoothstep(0.1, 0.5, d));
    float I = prof * cov * rays * (1.0 - 0.2 * f) * (1.0 + 0.6 * smoothstep(0.12, 0.5, d));
    add += lab2lin(col) * I;
    wsum += I;
    wl += I * (1.0 - 0.7 * smoothstep(0.05, 0.45, d)) * mix(1.0, 1.0 / max(rays, 0.4), 0.6);
  }
  vec3 hz = lab2lin(u_pal[5]) * exp(-(p.y + 1.0) * 2.6);
  vec3 dk = skyLin + add * glow * 0.85 + hz * 0.35 + vec3(stars(p, a)) * (1.0 - sat(wsum * 1.5)) * 0.9;
  vec3 avg = add / max(wsum, 1e-4);
  float al = 1.0 - exp(-wl * glow * 3.0);
  vec3 lt = mix(skyLin + hz * 0.15, avg, al * 0.9);
  return lin2srgb(shoulder(mix(lt, dk, u_dark)));
}

// Molten: drops of liquid chrome that drift, merge and part over a studio backdrop. Each drop is a smooth dome, and
// everything seen on it is the studio it mirrors: a bright sky above a crisp horizon, a dark floor below, a long soft
// box overhead and a strip light at the side whose sharp edges roll over the soft curves as the drops move. Toward the
// rim the reflection turns to the backdrop and brightens (Fresnel), with a thin bright lip. A pack can add a
// thin-film tint (anodised titanium): its hue turns with the angle of the surface.
// Palette: 0 backdrop, 1 sky, 2 coloured gel at the side, 3 floor, 4 thin film (its chroma is the film's strength; 0 is
// plain chrome), 5 soft-box light (its chroma tints the metal, as gold or rose gold).
// Options: x = motion (how far the drops travel), y = depth (flat discs to tall domes).
const float T = 40.0;

float field(vec2 p, float a, float m, out vec2 g) {
  float F = 0.0;
  g = vec2(0.0);
  for (int i = 0; i < 6; i++) {
    float f = float(i);
    float n = mod(f, 2.0) < 0.5 ? 1.0 : -1.0;
    vec2 c = vec2(-1.05 + 0.42 * f, 0.18 * sin(f * 2.3 + 0.7) - 0.04) + orbit(n * a + f * 1.9, (0.16 + 0.04 * mod(f, 3.0)) * m);
    c.y += 0.08 * m * sin(2.0 * a + f);
    float r = 0.27 + 0.11 * sin(f * 1.7 + 0.4) + 0.025 * m * sin(a + f * 2.2);
    vec2 d = p - c;
    float w = exp(-dot(d, d) / (r * r));
    F += w;
    g += w * (-2.0 * d / (r * r));
  }
  return F;
}

vec3 env(vec3 r, float a) {
  float up = r.y + 0.32 * r.z;
  float side = r.x;
  vec3 skyTop = setL(u_pal[1], u_pal[1].x * 0.86);
  vec3 sky = mix(u_pal[1], skyTop, smoothstep(0.05, 0.9, up));
  vec3 flo = mix(u_pal[3], setL(u_pal[3], u_pal[3].x * 0.55), smoothstep(-0.05, -0.8, up));
  vec3 c = mix(flo, sky, smoothstep(-0.035, 0.035, up));
  float gel = smoothstep(0.22, 0.52, side) * smoothstep(-0.5, -0.1, up) * smoothstep(0.95, 0.45, up);
  c = mix(c, mix(u_pal[2], setL(u_pal[2], u_pal[2].x * 1.12), smoothstep(0.3, 0.8, side)), gel * 0.9);
  vec3 lin = lab2lin(c);
  vec3 L5 = lab2lin(vec3(u_pal[5].x, 0.0, 0.0));
  float bx = smoothstep(0.26, 0.22, abs(side + 0.18 + 0.03 * sin(a))) * smoothstep(0.13, 0.09, abs(up - 0.62));
  float strip = smoothstep(0.08, 0.04, abs(side + 0.72)) * smoothstep(0.55, 0.35, abs(up - 0.15));
  lin += L5 * (bx * 1.6 + strip * 0.7);
  float back = smoothstep(-0.88, -0.995, r.z);
  lin = mix(lin, lab2lin(u_pal[0]) * 1.1 + 0.03, back * 0.55);
  return lin;
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.4, 1.5, u_opt.x);
  float depth = mix(0.35, 1.25, u_opt.y);
  float th = 0.5;
  vec2 g;
  float F = field(p, a, m, g);
  float e = max(F - th, 0.0);
  vec2 gh = g / (2.0 * sqrt(e + 0.0012)) * 0.55 * depth;
  vec3 n = normalize(vec3(-gh, 1.0));
  vec3 r = reflect(vec3(0.0, 0.0, -1.0), n);
  vec3 lin = env(r, a);
  // the metal: tinted by the soft box's colour (gold, rose gold), and a thin film whose hue turns with the angle
  vec3 tl = lab2lin(vec3(0.8, u_pal[5].yz * 2.2));
  lin *= tl / max(dot(tl, vec3(0.2126, 0.7152, 0.0722)), 1e-3);
  float fs = smoothstep(0.03, 0.11, length(u_pal[4].yz));
  vec3 lab = lin2lab(lin);
  float fh = atan(u_pal[4].z, u_pal[4].y) + (1.0 - n.z) * 5.0 + 0.8 * sin(a + p.x);
  float fc = mix(length(lab.yz), 0.13 + 0.05 * (1.0 - n.z), fs * 0.8);
  vec2 film = vec2(cos(fh), sin(fh)) * fc;
  lab.yz = mix(lab.yz, film, fs * 0.75 * (1.0 - smoothstep(-0.3, -0.9, r.z) * 0.75));
  lin = lab2lin(lab);
  float fres = pow(1.0 - n.z, 5.0);
  lin = mix(lin, vec3(1.0), fres * 0.12);
  float lip = smoothstep(0.012, 0.0, e) * smoothstep(-0.1, 0.6, n.y + 0.3);
  lin += lab2lin(vec3(u_pal[5].x, 0.0, 0.0)) * lip * 0.25;
  // the backdrop: a seamless sweep with a soft light and the drops' contact shadow
  vec3 bd = mix(u_pal[0], setL(u_pal[0], u_pal[0].x * mix(1.18, 1.04, 1.0 - u_dark) + 0.02), smoothstep(-1.2, 0.9, p.y));
  vec3 bLin = lab2lin(bd);
  vec2 gs;
  float Fs = field(p - vec2(0.05, -0.11), a, m, gs);
  bLin *= 1.0 - mix(0.18, 0.42, u_dark) * smoothstep(0.08, 0.55, Fs);
  bLin *= 0.88 + 0.12 * smoothstep(2.1, 0.3, length(p - vec2(0.0, 0.4)));
  float w = length(g) * u_px * 1.3 + 1e-4;
  float cov = smoothstep(th - w, th + w, F);
  return lin2srgb(shoulder(mix(bLin, lin, cov)));
}

// Velvet: draped satin. Two systems of folds cross: broad rounded bulges between narrow creases, lit from the top
// left, so every fold carries a bright ridge, a long sheen and a deep crease; a warm rim light catches the far sides.
// Palette: 0 crease shadow, 1 body, 2 lit cloth, 3 sheen, 4 colour in the creases, 5 rim light.
// Options: x = motion (how far the cloth shifts), y = folds (broad to fine).
const float T = 48.0;

float drape(vec2 q, float a, float m) {
  float w = q.y * 0.8 + 0.5 * m * sin(q.x * 0.7 + a);
  float u = q.x + 0.35 * sin(q.y * 1.1 + 0.4 * m * sin(a)) + 0.16 * m * sin(q.y * 2.3 - a + 1.0);
  return 0.5 * sin(u * 2.6 + 0.8 * sin(w)) + 0.26 * sin(u * 4.7 - 0.6 * w + 1.3) + 0.1 * sin(u * 8.1 + q.y * 0.9 + 2.0 * a);
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.5, u_opt.x);
  float fd = mix(0.7, 1.4, u_opt.y);
  vec2 q = rot(p, 0.5) * fd;
  float e = 0.003;
  float h0 = drape(q, a, m);
  float hx = drape(q + vec2(e, 0.0), a, m);
  float hy = drape(q + vec2(0.0, e), a, m);
  vec2 gr = vec2(hx - h0, hy - h0) / e;
  vec3 n = normalize(vec3(-gr * 0.4, 1.0));
  vec3 L = normalize(vec3(-0.38, 0.42, 0.82));
  float dif = dot(n, L);
  vec3 H = normalize(L + vec3(0.0, 0.0, 1.0));
  float nh = max(dot(n, H), 0.0);
  float spec = pow(nh, 48.0);
  float sheen = pow(nh, 6.0);
  float s = sat(dif * 0.95 + 0.18);
  float crease = smoothstep(-0.2, -0.75, h0);
  vec3 col = mix(u_pal[0], u_pal[1], smoothstep(0.05, 0.6, s));
  col = mix(col, u_pal[2], smoothstep(0.55, 0.95, s));
  col = mix(col, u_pal[4], 0.45 * crease * (1.0 - s));
  col = mix(col, u_pal[3], sat(spec * 0.95 + sheen * 0.3));
  float rim = pow(sat(dot(n.xy, normalize(vec2(0.85, -0.4))) * 2.2), 2.0);
  col = mix(col, u_pal[5], rim * 0.35);
  col.x *= 0.9 + 0.1 * smoothstep(2.0, 0.3, length(p - vec2(-0.5, 0.5)));
  return outLab(col);
}

// Spectra: a glass prism turning a little in a beam of white light; the beam leaves it as a fan of spectrum that sweeps
// slowly across the room, through a faint haze. In light mode it is the spectrum falling on a pale wall.
// Palette: 0 background, 1 background low, 2 haze, 3 the spectrum's first colour, 4 its last colour (the fan runs from
// 3 to 4 the long way round the hue circle), 5 the white of the beam.
// Options: x = motion (how far the prism turns), y = brightness.
const float T = 60.0;

float tri(vec2 q, float r, float rp) {
  float d = -1e3;
  for (int k = 0; k < 3; k++) {
    float an = rp - 1.5707963 + float(k) * 2.0943951;
    d = max(d, dot(q, vec2(cos(an), sin(an))));
  }
  return d - r * 0.5;
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.5, u_opt.x);
  float br = mix(0.55, 1.45, u_opt.y);
  float h3 = atan(u_pal[3].z, u_pal[3].y);
  float h4 = atan(u_pal[4].z, u_pal[4].y);
  if (h4 < h3) h4 += TAU;
  float Ls = 0.5 * (u_pal[3].x + u_pal[4].x);
  float Cs = 0.5 * (length(u_pal[3].yz) + length(u_pal[4].yz));
  vec2 P0 = vec2(-0.82, -0.1);
  float rp = 0.07 * m * sin(a) + 0.025 * m * sin(2.0 * a + 1.0);
  float R = 0.5;
  float dt = tri(p - P0, R, rp);
  float inside = smoothstep(u_px, -u_px, dt);

  vec3 bg = mix(u_pal[1], u_pal[0], smoothstep(-1.1, 1.0, p.y + 0.25 * p.x));
  vec3 bgLin = lab2lin(bg);
  float vig = 1.0 - 0.35 * smoothstep(0.6, 2.2, length(p * vec2(0.75, 1.0)));
  float haze = 0.78 + 0.22 * lnoise(p * 1.3, a, 0.35 * m);
  vec3 wht = lab2lin(u_pal[5]);

  // the white beam coming in from the left, stopping at the prism
  vec2 dIn = normalize(vec2(1.0, 0.16 + 0.5 * rp));
  vec2 B0 = P0 + vec2(-0.08, 0.03);
  float along = dot(p - B0, dIn);
  float across = dot(p - B0, vec2(-dIn.y, dIn.x));
  float beam = (gauss(across, 0.016 + u_px) + 0.18 * gauss(across, 0.09)) * smoothstep(0.02, -0.04, along) * (1.0 - inside);

  // the fan: angle about the exit point, s runs -1..1 across the spectrum
  vec2 O = P0 + vec2(0.1, -0.03);
  vec2 dv = p - O;
  float r = length(dv);
  float ang = atan(dv.y, dv.x);
  float axis = -0.2 + 2.2 * rp;
  float hw = 0.2 + 0.015 * m * sin(a + 2.0);
  float s = (ang - axis) / hw;
  float fanI = smoothstep(1.08, 0.62, abs(s)) * smoothstep(0.0, 0.35, r) * (1.0 - inside) / (1.0 + 0.35 * r);
  fanI *= step(0.0, dv.x + 0.25);
  vec3 sc = lab2lin(lch(Ls, Cs, mix(h4, h3, sat(s * 0.5 + 0.5))));
  float s2 = (ang - axis + 0.62 + 1.2 * rp) / 0.12;
  float fan2 = smoothstep(1.1, 0.4, abs(s2)) * smoothstep(0.0, 0.3, r) * (1.0 - inside) * 0.22 / (1.0 + 0.6 * r);
  vec3 sc2 = lab2lin(lch(Ls, Cs * 0.8, mix(h3, h4, sat(s2 * 0.5 + 0.5))));
  float halo = gauss(s, 1.25) * smoothstep(0.0, 0.5, r) * (1.0 - inside) * 0.07;

  // the glass: a faint body, a bright rim on the faces toward the light, the light inside it
  float rim = exp(-abs(dt) / (1.4 * u_px + 0.002));
  vec2 nq = normalize(p - P0 + 1e-4);
  float lit = 0.45 + 0.55 * sat(dot(nq, normalize(vec2(-0.6, 0.8))));
  vec2 pq = p - P0;
  float path = gauss(dot(pq, vec2(-dIn.y, dIn.x)) + 0.03 + 0.12 * sat(dot(pq, dIn) + 0.1), 0.035 + 0.06 * sat(dot(pq, dIn) + 0.15));
  float inner = inside * (0.012 + 0.2 * path * smoothstep(-0.3, 0.05, dot(pq, dIn)));
  float face = inside * gauss(dot(pq, normalize(vec2(-0.6, 0.8))) - 0.12, 0.12) * 0.06;
  vec3 inTint = sc * inside * path * smoothstep(-0.05, 0.12, dot(pq, dIn)) * 0.35;

  vec3 light = sc * fanI * haze + sc2 * fan2 + wht * (beam * 1.1 + halo * haze * 0.4);
  vec3 dk = bgLin * vig * (1.0 - 0.3 * inside) + light * br + lab2lin(u_pal[2]) * haze * 0.05 + wht * (inner + face + rim * lit * 0.55) + inTint * br;
  float shadow = smoothstep(0.12, -0.08, tri(p - P0 - vec2(0.07, -0.09), R, rp)) * (1.0 - inside);
  vec3 lt = bgLin * (1.0 - 0.1 * shadow) * mix(1.0, vig, 0.4);
  lt = mix(lt, sc * 1.05, sat(fanI * haze * 0.85 * br));
  lt = mix(lt, sc2, sat(fan2 * 1.6 * br));
  lt = mix(lt, wht, sat(beam * 0.9 + inner * 1.5 + rim * lit * 0.7));
  lt = mix(lt, lab2lin(u_pal[2]), inside * 0.2);
  return lin2srgb(shoulder(mix(lt, dk, u_dark)));
}

// Bloom: a flower made of light. Two rings of long translucent petals, each with a luminous edge and a clear heart,
// sway against each other and breathe; where petals cross, their light adds (dark) or they filter each other like
// tinted glass (light).
// Palette: 0 background, 1 background glow, 2 petal base, 3 petal tip, 4 inner ring, 5 the flower's core.
// Options: x = motion (how far the petals sway), y = softness (how feathered their edges are).
const float T = 72.0;

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.5, u_opt.x);
  float soft = mix(0.5, 1.8, u_opt.y);
  vec2 c = vec2(0.3, -0.06) + orbit(a, 0.02 * m);
  vec2 d = p - c;
  float r = length(d);
  vec3 bg = mix(u_pal[1], u_pal[0], smoothstep(0.1, 1.7, r));
  vec3 bgLin = lab2lin(bg);
  vec3 add = vec3(0.0);
  vec3 filt = vec3(1.0);
  float sect = TAU / 6.0;
  for (int j = 0; j < 2; j++) {
    float fj = float(j);
    float spin = (fj * 2.0 - 1.0) * 0.16 * m * sin(a + fj * 1.7) + fj * sect * 0.5 + 0.25;
    float len = (1.3 - 0.5 * fj) * (1.0 + 0.04 * m * sin(2.0 * a + fj * 2.0));
    float wid = 0.42 - 0.12 * fj;
    vec2 dj = d + tiltD(0.7 - 1.4 * fj);
    float ang = atan(dj.y, dj.x);
    float k0 = floor((ang - spin) / sect + 0.5);
    for (int k = 0; k < 3; k++) {
      float pa = (k0 + float(k) - 1.0) * sect + spin;
      vec2 q = rot(dj, -pa);
      float u = q.x / len;
      float bend = 0.1 * sin(pa * 2.0 + a) * m;
      float v0 = q.y - bend * u * u * len;
      float prof = pow(sat(sin(3.14159265 * pow(sat(u), 0.8))), 0.6);
      float w = wid * prof + 1e-3;
      float v = abs(v0) / w;
      float fe = 0.06 + 0.16 * soft;
      float body = smoothstep(1.0, 1.0 - fe * 2.0, v) * step(0.0, u) * smoothstep(1.0, 0.94, u);
      float edge = body * smoothstep(0.55, 0.98, v) + body * smoothstep(0.75, 0.98, u) * 0.6;
      float vein = body * gauss(v0 / w, 0.1) * smoothstep(0.2, 0.7, u) * 0.0;
      vec3 col = mix(u_pal[2], mix(u_pal[3], u_pal[4], fj), smoothstep(0.05, 0.95, u));
      col = hueShift(col, 0.14 * sin(pa * 2.0 + fj * 1.3 + 0.4 * sin(a)));
      vec3 cl = lab2lin(col);
      float amt = body * (0.14 + 0.26 * u) + edge * 0.55 + vein;
      add += cl * amt;
      filt *= mix(vec3(1.0), cl, sat(body * (0.2 + 0.35 * u) + edge * 0.35 + vein * 0.5));
    }
  }
  vec3 core = lab2lin(u_pal[5]) * (exp(-(r * r) / 0.006) * 0.9 + exp(-(r * r) / 0.06) * 0.3);
  vec3 dk = bgLin + add + core;
  vec3 lt = bgLin * filt + core * 0.3;
  return lin2srgb(shoulder(mix(lt, dk, u_dark)));
}

// Nebula: glowing gas folded by slow currents, with dark dust lanes across it and a few quiet stars. In light mode the
// same clouds read as pigment drifting in milk.
// Palette: 0 deep space, 1 space glow, 2 gas, 3 second gas, 4 warm dust, 5 the bright heart.
// Options: x = motion (how far the gas churns), y = density (how much of the sky it fills).
const float T = 90.0;

float stars(vec2 p, float a) {
  float sc = 26.0;
  vec2 q = p * sc;
  vec2 id = floor(q);
  vec3 h = hash33(vec3(id, 1.9)) * 0.5 + 0.5;
  vec2 c = id + 0.5 + (h.xy - 0.5) * 0.7;
  float d = length(q - c) / sc;
  float r = 0.8 * u_px;
  float s = exp(-(d * d) / (r * r)) * step(0.87, h.z) * (h.z - 0.87) * 7.0;
  float vis = sat((1.0 / sc) / u_px / 9.0 - 0.5);
  return s * (0.75 + 0.25 * sin(a * 2.0 + h.y * TAU)) * vis;
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.5, u_opt.x);
  float den = mix(0.65, 1.4, u_opt.y);
  vec2 pg = p + tiltD(-0.6);
  vec3 q = vec3(pg * 0.72, 0.0);
  vec3 o1 = vec3(orbit(a, 0.2 * m), 0.25 * m * sin(a + 1.0));
  vec2 w = vec2(fbm3(q + o1), fbm3(q + vec3(5.2, 1.3, 2.0) - o1.yxz));
  vec3 q2 = vec3(pg * 0.72 + w * 0.95, 0.5) + vec3(orbit(-a, 0.14 * m), 0.18 * m * cos(a));
  float dn = fbm4(q2 * 1.4);
  float lane = fbm3(q2 * 2.7 + vec3(7.0, 2.0, 1.0));
  float e = smoothstep(-0.2, 0.55, dn * den + 0.12 * (den - 1.0) - 0.06 * length(p));
  vec3 cl = mix(u_pal[2], u_pal[3], smoothstep(-0.35, 0.35, w.x - w.y));
  cl = mix(cl, u_pal[4], smoothstep(0.12, 0.5, dn) * 0.45);
  vec3 cLin = lab2lin(cl);
  float dust = smoothstep(-0.02, 0.32, lane) * e;
  vec3 bgLin = lab2lin(mix(u_pal[0], u_pal[1], smoothstep(-0.3, 0.6, w.y + 0.2 * e)));
  vec3 em = cLin * e * (1.0 - 0.6 * dust) * 1.05 + lab2lin(u_pal[5]) * pow(e, 3.0) * (1.0 - dust) * 0.4;
  vec3 dk = bgLin + em + vec3(stars(p + tiltD(0.9), a)) * (1.0 - e * 0.8);
  vec3 ab = -log(max(cLin, vec3(0.03))) * 0.55;
  vec3 lt = bgLin * exp(-ab * e * (1.6 + 0.6 * dust)) ;
  lt = mix(lt, lab2lin(u_pal[5]), pow(e, 3.0) * 0.25);
  return lin2srgb(shoulder(mix(lt, dk, u_dark)));
}

// Lagoon: sunlight focused by moving water onto a shallow floor. The caustic net is computed from the water surface
// itself: the surface is a sum of travelling waves whose speeds are whole multiples of the loop, its curvature is exact,
// and where the refracted light converges the floor brightens. It is done once per colour channel at slightly
// different focal depths, so each line carries a faint rainbow edge.
// Palette: 0 deep water, 1 shallow water, 2 sand, 3 caustic light, 4 shade, 5 sparkle.
// Options: x = motion (how strongly the water moves), y = clarity (how sharp the light lines are).
const float T = 40.0;

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.5, 1.4, u_opt.x);
  float clar = mix(0.2, 1.0, u_opt.y);
  vec2 x = p + 0.06 * m * vec2(lnoise(p * 0.8, a, 0.3), lnoise(p * 0.8 + 4.0, a, 0.3));
  x.y *= 1.12;
  float hxx = 0.0;
  float hyy = 0.0;
  float hxy = 0.0;
  for (int i = 0; i < 7; i++) {
    float f = float(i);
    float an = f * 2.39996 + 0.3;
    float kk = 10.5 + 3.0 * sin(f * 1.7 + 0.4);
    vec2 k = vec2(cos(an), sin(an)) * kk;
    float sg = mod(f, 2.0) < 0.5 ? 1.0 : -1.0;
    float n = sg * (1.0 + floor(f / 3.0));
    float A = 0.3 / (kk * kk) * (0.7 + 0.3 * m) * (1.0 - 0.06 * f);
    float s = -A * sin(dot(k, x) + n * a + f * 1.3);
    hxx += s * k.x * k.x;
    hyy += s * k.y * k.y;
    hxy += s * k.x * k.y;
  }
  float tr = hxx + hyy;
  float det = hxx * hyy - hxy * hxy;
  vec3 z = vec3(0.95, 1.0, 1.06) * 2.3;
  vec3 J = 1.0 + z * tr + z * z * det;
  float eps = mix(0.35, 0.06, clar);
  vec3 I = (1.0 + eps) / (abs(J) + eps);
  I = max(pow(I, vec3(1.2)) - 0.8, vec3(0.0));

  float depth = smoothstep(-1.3, 1.3, p.y * 0.85 - p.x * 0.3);
  vec3 water = mix(u_pal[1], u_pal[0], depth);
  water = mix(water, u_pal[2], mix(0.25, 0.08, u_dark) * (1.0 - depth));
  vec3 base = lab2lin(water);
  vec3 cl = lab2lin(u_pal[3]);
  vec3 lin = base * 0.78 + cl * I * mix(0.16, 0.22, u_dark) * (1.0 - 0.45 * depth);
  float lum = dot(I, vec3(0.3, 0.5, 0.2));
  lin += lab2lin(u_pal[5]) * pow(max(lum - 3.0, 0.0), 2.0) * 0.02;
  lin = mix(lin, lab2lin(u_pal[4]), 0.3 * smoothstep(0.6, 2.0, length(p * vec2(0.7, 1.0))));
  return lin2srgb(shoulder(lin));
}

// Iris: an iridescent film turning slowly. Its thickness field swirls and drains (thicker toward the bottom), and the
// thickness sets the colour the way interference does: a cycle through the pack's three film colours, with a darker
// trough between bands, so it reads as a soap film or a holographic foil rather than a gradient.
// Palette: 0 backdrop, 1 backdrop glow, 2 first film colour, 3 second, 4 third, 5 highlight.
// Options: x = motion (how far the film swirls), y = bands (broad to fine).
const float T = 50.0;

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.5, u_opt.x);
  float th = mix(0.6, 1.6, u_opt.y);
  vec2 c = vec2(0.25, 0.1);
  vec2 d = p - c;
  float r = length(d);
  vec2 q = rot(d, 1.1 * m * sin(a) * exp(-r * 0.9) + 0.3 * m * sin(a + r * 1.6));
  float n = gnoise(vec3(q * 0.7, 0.0) + vec3(orbit(a, 0.16 * m), 0.18 * m * sin(a + 2.0))) + 0.3 * gnoise(vec3(q * 1.5 + 2.0, 1.0) + vec3(orbit(-a, 0.12 * m), 0.0));
  float dd = (1.2 * n + 1.1 * sat(0.6 - q.y * 0.4) + 0.2 * sin(q.x * 2.0 + n * 3.0)) * th * 1.15;
  float ph = dd * TAU;
  float w0 = pow(0.5 + 0.5 * cos(ph), 2.0);
  float w1 = pow(0.5 + 0.5 * cos(ph - 2.0943951), 2.0);
  float w2 = pow(0.5 + 0.5 * cos(ph - 4.1887902), 2.0);
  vec3 fc = (u_pal[2] * w0 + u_pal[3] * w1 + u_pal[4] * w2) / (w0 + w1 + w2);
  float trough = 0.5 + 0.5 * cos(ph * 1.5 + 1.0);
  float view = dot(normalize(d + 1e-4), normalize(vec2(-0.6, 0.8)));
  fc = hueShift(fc, 0.35 * view * (0.6 + 0.4 * sin(a)));
  float lightAmt = 0.5 + 0.5 * smoothstep(1.9, 0.1, length(p - vec2(-0.3, 0.4)));
  vec3 bgLin = lab2lin(mix(u_pal[0], u_pal[1], smoothstep(1.5, 0.0, r)));
  vec3 hl = lab2lin(u_pal[5]) * (gauss(length(p - vec2(-0.6, 0.52)), 0.32) * 0.2 + gauss(length(p - vec2(-0.64, 0.56)), 0.05) * 0.3);
  vec3 dkc = vec3(fc.x * (0.55 + 0.4 * trough), fc.yz * (0.45 + 0.55 * trough));
  vec3 dk = bgLin * 0.6 + lab2lin(dkc) * lightAmt * 0.85 + hl;
  vec3 ltc = vec3(mix(0.8, fc.x, 0.6) * (0.92 + 0.08 * trough), fc.yz * (0.7 + 0.3 * trough));
  vec3 lt = mix(bgLin, lab2lin(ltc), 0.85) + hl * 0.3;
  return lin2srgb(shoulder(mix(lt, dk, u_dark)));
}

// Glasswave: two rods of clear glass, flattened and flowing in slow waves, lit from behind by coloured light. Like any
// solid glass rod, each shows the light behind it turned over and squeezed, a darker band where the light reflects
// inside, and thin bright lines near the edges, every one split by the glass into a faint spectrum. The light the rods
// focus falls as a soft coloured glow on the wall behind.
// Palette: 0 backdrop, 1 backdrop glow, 2 first light behind the glass, 3 second light, 4 third light, 5 the white of
// the edges and highlights.
// Options: x = motion (how far the glass flows), y = thickness (slim rods to broad, deep ones).
// Perspective: the rods lie at three depths (tiltD -1, 0, +1), their glow on the wall behind them.
const float T = 40.0;

// one rod: returns (across -1..1, along, half width, coverage distance); its centre line is y = c(x)
vec4 rod(vec2 p, float i, float a, float m, float th) {
  float ph = i * 0.75;
  float x = p.x;
  float base = -0.5 + 0.34 * i;
  float tilt = 0.2 - 0.03 * i;
  float A = 0.17 + 0.03 * i;
  float c = base + tilt * x + 0.2 * sin(x * 0.8 + 0.6) + m * (A * sin(x * 1.25 + a + ph) + 0.05 * sin(x * 2.3 - 2.0 * a + ph * 2.0));
  float dc = tilt + 0.16 * cos(x * 0.8 + 0.6) + m * (A * 1.25 * cos(x * 1.25 + a + ph) + 0.115 * cos(x * 2.3 - 2.0 * a + ph * 2.0));
  float w = th * (0.24 - 0.065 * i) * (1.0 + 0.3 * sin(x * 0.9 - a + ph * 1.9 + 1.0));
  float d = (p.y - c) / sqrt(1.0 + dc * dc);
  return vec4(d / w, x, w, abs(d) - w);
}

vec3 env(float s, float u, float a, float i) {
  float g = s + 0.35 * sin(u * 0.9 + a + i * 1.7);
  vec3 c = mix(u_pal[2], u_pal[3], smoothstep(-0.9, 0.5, g));
  c = mix(c, u_pal[4], smoothstep(0.2, 1.2, g + 0.3 * sin(u * 0.6 - a)));
  return lab2lin(c);
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.5, u_opt.x);
  float th = mix(0.7, 1.35, u_opt.y);
  vec3 wht = lab2lin(u_pal[5]);
  vec3 bg = lab2lin(mix(u_pal[0], u_pal[1], smoothstep(-1.4, 1.2, -p.y * 0.6 + p.x * 0.4)));
  vec3 col = bg;
  // the light the rods focus onto the wall, a little below them
  for (int j = 0; j < 3; j++) {
    vec4 r = rod(p + tiltD(float(j) - 1.5) + vec2(0.0, 0.12), float(j), a, m, th);
    float g = exp(-r.x * r.x * 0.35) * (0.6 + 0.4 * sin(r.y * 1.1 + a + float(j)));
    col += env(0.0, r.y, a, float(j)) * g * mix(0.1, 0.18, u_dark);
  }
  for (int j = 0; j < 3; j++) {
    float fj = float(j);
    vec4 r = rod(p + tiltD(fj - 1.0), fj, a, m, th);
    float v = r.x;
    float av = abs(v);
    float cov = smoothstep(1.3 * edgePx(), -1.3 * edgePx(), r.w);
    float nz = sqrt(max(1.0 - v * v, 0.0));
    // the light behind, seen through the rod: turned over and squeezed toward the centre
    vec3 c;
    vec3 vk = av * vec3(0.985, 1.0, 1.016);
    vec3 e1 = (vk - 0.9) / 0.03;
    vec3 e2 = (vk - 0.58) / 0.05;
    vec3 e3 = (vk - 0.76) / 0.07;
    vec3 line = exp(-e1 * e1) * 0.9 + exp(-e2 * e2) * 0.22;
    vec3 band = exp(-e3 * e3);
    c = env(-0.75 * v, r.y, a, fj);
    // what lies behind (the wall, or a rod further back) shows through, turned over with the rest
    c += (col - bg) * 0.55;
    c *= 0.75 + 0.45 * nz;
    c *= 1.0 - 0.45 * band;
    c += wht * line * mix(0.5, 0.8, u_dark);
    // the crest catches the studio light; the far edge reflects the dark
    float crest = exp(-pow((v - 0.72) / 0.12, 2.0));
    c += wht * crest * 0.12;
    c = mix(c, bg * 0.6, smoothstep(0.93, 1.0, av) * 0.5);
    // in light mode the glass reads lighter and clearer: the wall shows through it
    vec3 cl = mix(bg, c, 0.75) + wht * line * 0.15;
    c = mix(cl, c, u_dark);
    col = mix(col, c, cov);
  }
  return lin2srgb(shoulder(col));
}

// Corona: an aurora seen from straight beneath it. Its rays are vertical, so from below they all run toward one point
// overhead, just above the top of the window: a crown of light. Each curtain has a bright, sharp lower border, farthest
// from that point, folded and slowly travelling; its rays climb from it toward the crown, shimmering and fading from
// the border's colour through the body's to the crown's high, faint one.
// Palette: 0 the sky overhead, 1 the sky toward the edges, 2 lower border, 3 body, 4 crown, 5 the fringe just under the
// border.
// Options: x = motion (how far the curtains fold and drift), y = glow.
// Perspective: the stars are farthest, the lowest curtain nearest (tiltD 1, 0.2, -0.6).
const float T = 60.0;

float stars(vec2 p, float a) {
  float sc = 28.0;
  vec2 q = p * sc;
  vec2 id = floor(q);
  vec3 h = hash33(vec3(id, 5.3)) * 0.5 + 0.5;
  vec2 c = id + 0.5 + (h.xy - 0.5) * 0.7;
  float d = length(q - c) / sc;
  float r = 0.85 * u_px;
  float s = exp(-(d * d) / (r * r)) * step(0.86, h.z) * (h.z - 0.86) * 6.5;
  float vis = sat((1.0 / sc) / u_px / 9.0 - 0.5);
  return s * (0.7 + 0.3 * sin(a * 3.0 + h.x * TAU)) * vis;
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.5, u_opt.x);
  float glow = mix(0.5, 1.5, u_opt.y);
  vec2 V = vec2(0.42, 2.25);
  vec2 d = p - V;
  float r = length(d);
  float th = atan(d.x, -d.y);
  vec3 sky = mix(u_pal[0], u_pal[1], smoothstep(1.2, 3.8, r));
  vec3 skyLin = lab2lin(sky);
  float fine = sat(r * 0.016 / u_px / 3.0 - 0.3);
  vec3 add = vec3(0.0);
  float wsum = 0.0;
  for (int i = 0; i < 3; i++) {
    float f = float(i);
    // the lowest curtain is the nearest: each lies at its own depth for the perspective
    vec2 dd = p + tiltD(1.0 - 0.8 * f) - V;
    float r = length(dd);
    float th = atan(dd.x, -dd.y);
    float R0 = 3.05 - 0.62 * f;
    float u = th * (2.6 + 0.4 * f) + f * 2.7;
    float fold = 0.12 * sin(u * 2.2 + a + f * 1.9) + 0.05 * sin(u * 4.1 - 2.0 * a + f) + 0.025 * sin(u * 8.3 + 3.0 * a + f * 2.0);
    fold += 0.16 * m * lnoise(vec2(u * 0.9, f * 3.0), a + f, 0.5) + 0.05 * lnoise(vec2(u * 3.1, f * 7.0), 2.0 * a, 0.3);
    float rb = R0 + fold;
    float dr = rb - r;
    float h = 0.5 + 0.12 * f;
    float prof = dr < 0.0 ? exp(-(dr * dr) / 0.0012) : exp(-dr / h) * (0.35 + 0.65 * exp(-(dr * dr) / 0.03));
    float cov = smoothstep(-0.3, 0.45, lnoise(vec2(u * 0.55 + 4.0 * f, 9.0 + f), a, 0.4 + 0.25 * m));
    cov *= 0.55 + 0.6 * sat(0.5 + lnoise(vec2(u * 2.6 + 1.0, 4.0 * f + 2.0), 2.0 * a, 0.35));
    float k = th * 70.0 + fold * 6.0;
    float rays = 0.55 + 0.55 * lnoise(vec2(k, 3.0 * f + r * 0.4), 2.0 * a, 0.12 + 0.25 * m);
    rays = mix(0.85, rays, fine) * (0.75 + 0.45 * lnoise(vec2(th * 18.0, f * 5.0), a, 0.3 + 0.2 * m));
    rays = mix(1.0, max(rays, 0.0) * 1.3, smoothstep(-0.02, 0.1, dr));
    vec3 col = mix(u_pal[2], u_pal[3], smoothstep(0.02, 0.3, dr));
    col = mix(col, u_pal[4], smoothstep(0.2, 0.75, dr));
    col = mix(col, u_pal[5], smoothstep(0.0, -0.05, dr) * mix(0.3, 0.8, u_dark));
    float I = prof * cov * rays * (1.0 - 0.18 * f) * (1.0 + 0.9 * smoothstep(0.2, 0.8, dr));
    add += lab2lin(col) * I;
    wsum += I;
  }
  vec3 avg = add / max(wsum, 1e-4);
  vec3 dk = skyLin + add * glow * 0.8 + vec3(stars(p + tiltD(-1.0), a)) * (1.0 - sat(wsum * 1.4)) * 0.9;
  dk += avg * sat(wsum) * 0.05 * glow;
  float al = 1.0 - exp(-wsum * glow * 4.0);
  vec3 lt = mix(skyLin, avg, al * 0.88);
  return lin2srgb(shoulder(mix(lt, dk, u_dark)));
}

// Orbs: four soft-touch pebbles floating in a seamless studio. A wide soft box lights them from the upper left; the
// shadow side keeps a deeper, richer colour (the way lacquered clay holds its pigment), the floor's light comes back
// from below, each pebble tints its neighbours and the wall behind with its own colour, and their shadows fall soft and
// wide on the sweep. The pebbles turn slowly as they float, so the soft box slides over their curves.
// Palette: 0 backdrop, 1 backdrop low (the sweep's floor), 2 large orb, 3 second orb, 4 small orb, 5 the soft box.
// Options: x = motion (how far the orbs float), y = gloss (matte clay to lacquer).
// Dynamic: u_sun moves the soft box (and so the shading, the window and the shadows). Perspective: the wall is the far
// layer (tiltD -1) and each orb sits at a depth set by its distance from the wall.
const float T = 48.0;

// centre (x, y), radius, depth of the centre (larger is nearer)
vec4 orbAt(float i, float a, float m) {
  vec4 s = vec4(0.98, -0.55, 0.62, 0.15);
  if (i > 0.5) s = vec4(-1.08, 0.5, 0.3, 0.05);
  if (i > 1.5) s = vec4(0.22, -0.74, 0.25, 0.6);
  if (i > 2.5) s = vec4(1.38, 0.42, 0.15, 0.4);
  float ph = i * 1.9;
  s.xy += m * vec2(0.03 * sin(a + ph) + 0.01 * sin(2.0 * a + ph * 1.3), 0.045 * cos(a + ph) + 0.012 * sin(3.0 * a - ph));
  return s;
}

vec3 orbCol(float i) {
  vec3 c = u_pal[2];
  if (i > 0.5) c = u_pal[3];
  if (i > 1.5) c = u_pal[4];
  if (i > 2.5) c = mix(u_pal[3], u_pal[4], 0.5);
  return c;
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.3, 1.5, u_opt.x);
  float gloss = u_opt.y;
  // the soft box: its direction follows the time of day (u_sun), and the shadows and the mirrored window follow it
  vec2 L2 = vec2(-0.55, 0.62) + u_sun;
  vec3 Ld = normalize(vec3(L2, 0.62));
  vec2 sdir = -normalize(L2) * 0.47;
  vec2 pw = p + tiltD(-1.0);
  vec3 key = lab2lin(vec3(u_pal[5].x, u_pal[5].yz * 0.6));

  // the sweep: a wall that curves into a floor, lit from the upper left
  float sweep = smoothstep(-1.2, 0.5, pw.y);
  vec3 bd = mix(u_pal[1], u_pal[0], sweep);
  vec3 bg = lab2lin(bd);
  bg *= 0.8 + 0.32 * smoothstep(2.6, 0.0, length(pw - vec2(-1.2, 1.1) - u_sun));
  vec3 bleed = vec3(0.0);
  float shade = 1.0;
  for (int k = 0; k < 4; k++) {
    vec4 s = orbAt(float(k), a, m);
    float lift = 0.2 + s.w;
    vec2 sc = s.xy + sdir * lift;
    float pen = s.z * (0.45 + 1.1 * lift);
    float ds = length((pw - sc) * vec2(0.92, 1.12)) - s.z * 0.9;
    shade *= 1.0 - mix(0.3, 0.55, u_dark) * smoothstep(pen, -pen * 0.7, ds) / (1.0 + 0.8 * lift);
    // light that leaves the orb's lit side and lands, coloured, on the wall around it
    float dg = length(pw - s.xy + vec2(0.1, -0.05) * s.z) / s.z;
    bleed += lab2lin(orbCol(float(k))) * exp(-dg * dg * 0.7) * 0.1 / (1.0 + lift);
  }
  vec3 col = bg * shade + bleed * mix(0.5, 1.0, u_dark) * shade;

  // the orbs, far to near
  for (int k = 0; k < 4; k++) {
    float fi = float(k);
    vec4 s = orbAt(fi, a, m);
    // each orb at its own depth for the perspective: the far ones barely move, the near ones most
    s.xy -= tiltD(s.w * 2.4 - 0.6);
    // a pebble: an ellipsoid that turns slowly about the view axis
    float sq = 0.025 + 0.012 * fi;
    float tw = fi * 1.3 + 0.35 * sin(a + fi * 2.0);
    vec2 q = rot(p - s.xy, -tw) / (s.z * vec2(1.0 + sq, 1.0 - sq));
    float rr = dot(q, q);
    float rl = sqrt(rr);
    float cov = smoothstep(1.0 + 1.5 * edgePx() / s.z, 1.0 - 1.5 * edgePx() / s.z, rl);
    float nz = sqrt(max(1.0 - rr, 0.0));
    vec3 n = normalize(vec3(rot(q / vec2(1.0 + sq, 1.0 - sq), tw), nz));
    vec3 P = vec3(p, s.w + s.z * nz);
    vec3 alb = orbCol(fi);
    // half-Lambert from the wide soft box; the terminator keeps colour instead of greying
    float dif = pow(sat(0.5 + 0.5 * dot(n, Ld)), 1.6);
    vec3 lit = setL(alb, alb.x * mix(mix(0.5, 0.62, 1.0 - u_dark), 1.1, dif));
    lit.yz *= mix(1.05, 0.94, dif);
    lit = hueShift(lit, 0.16 * (dif - 0.5));
    vec3 c = lab2lin(lit);
    // the floor's light from below, and the wall's light at the rim
    c += lab2lin(u_pal[1]) * sat(-n.y * 0.8 + 0.1) * 0.16 * (1.0 - n.z * 0.5);
    float fr = pow(1.0 - n.z, 2.5);
    c = mix(c, lab2lin(setL(bd, bd.x * 1.06)) + bleed * 0.5, fr * mix(0.25, 0.45, gloss));
    // neighbours: occlusion where they come close, and their colour bounced across
    for (int j = 0; j < 4; j++) {
      float fj = float(j);
      float other = step(0.5, abs(fj - fi));
      vec4 o = orbAt(fj, a, m);
      vec3 D = vec3(o.xy, o.w) - P;
      float dl = length(D);
      float ff = sat(dot(n, D / dl)) * (o.z * o.z) / (dl * dl) * other;
      c *= 1.0 - 0.4 * ff;
      c += lab2lin(orbCol(fj)) * ff * 0.3;
    }
    // the soft box mirrored: a broad satin sheen, and on lacquer a soft-edged window with a brighter core
    vec3 H = normalize(Ld + vec3(0.0, 0.0, 1.0));
    float nh = sat(dot(n, H));
    float sheen = pow(nh, mix(5.0, 14.0, gloss)) * mix(0.1, 0.18, gloss);
    vec3 r = reflect(vec3(0.0, 0.0, -1.0), n);
    vec2 bx = rot(r.xy - L2 * 0.88, 0.6) / vec2(0.36, 0.2);
    float box = exp(-pow(dot(bx, bx), mix(1.0, 2.5, gloss)) * 1.6);
    float hot = pow(nh, mix(60.0, 400.0, gloss)) * gloss;
    c += key * (sheen + box * gloss * (0.18 + 0.3 * gloss) + hot * 0.6);
    col = mix(col, c, cov);
  }
  col *= 0.94 + 0.06 * smoothstep(2.3, 0.6, length(p * vec2(0.8, 1.0)));
  return lin2srgb(shoulder(col));
}

// Bubbles: soap bubbles drifting through still air. Each is almost clear in the middle and coloured toward its rim,
// where the film is seen at a slant and reflects the most; the colour is thin-film interference, banded by the film's
// thickness, which drains slowly downward and swirls as the bubble turns. A soft window and a smaller second one glint
// on each; the bubbles wobble a little as they float.
// Palette: 0 background, 1 background glow, 2 first film colour, 3 second, 4 third, 5 the window glint.
// Options: x = motion (how far the bubbles drift and swirl), y = colour (a thin, faint film to a rich, thick one).
// Perspective: the background is the far layer; each bubble's depth follows its size.
const float T = 60.0;

vec4 bub(float i, float a, float m) {
  vec4 b = vec4(0.95, -0.28, 0.5, 0.0);
  if (i > 0.5) b = vec4(-1.0, 0.42, 0.3, 1.7);
  if (i > 1.5) b = vec4(-0.28, -0.62, 0.17, 3.1);
  if (i > 2.5) b = vec4(0.12, 0.62, 0.11, 4.4);
  if (i > 3.5) b = vec4(1.45, 0.7, 0.08, 5.6);
  b.xy += m * vec2(0.06 * sin(a + b.w) + 0.02 * sin(2.0 * a + b.w * 2.0), 0.07 * cos(a + b.w * 1.3) + 0.02 * sin(3.0 * a - b.w));
  return b;
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.5, u_opt.x);
  float rich = mix(0.5, 1.4, u_opt.y);
  vec2 pb = p + tiltD(-1.0) - vec2(-0.4, 0.3);
  vec3 bg = mix(u_pal[0], u_pal[1], exp(-dot(pb, pb) * 0.4));
  vec3 bgLin = lab2lin(bg);
  vec3 col = bgLin;
  vec3 glintC = lab2lin(u_pal[5]);
  for (int i = 0; i < 5; i++) {
    float f = float(i);
    vec4 b = bub(f, a, m);
    // the larger a bubble, the nearer it floats: its own depth for the perspective
    vec2 d = p + tiltD(clamp((b.z - 0.22) * 4.0, -1.0, 1.0)) - b.xy;
    float r = length(d);
    float ang = atan(d.y, d.x);
    float R = b.z * (1.0 + 0.025 * m * sin(2.0 * ang + 2.0 * a + b.w) + 0.015 * m * sin(3.0 * ang - a + b.w));
    float e = r / R;
    float cov = smoothstep(1.0 + 1.5 * edgePx() / R, 1.0 - 1.5 * edgePx() / R, e);
    vec2 q = d / R;
    float nz = sqrt(max(1.0 - e * e, 0.0));
    // film thickness: thicker toward the bottom, swirled about the bubble's axis as it turns
    vec2 sw = rot(q, 0.9 * m * sin(a + b.w) + 0.6 * (1.0 - e));
    float th = 1.1 - 0.55 * sw.y + 0.35 * gnoise(vec3(sw * 1.8, b.w) + vec3(orbit(a, 0.3 * m), 0.2 * sin(a)));
    th *= rich;
    float ph = th * TAU * 1.3;
    float w0 = pow(0.5 + 0.5 * cos(ph), 2.0);
    float w1 = pow(0.5 + 0.5 * cos(ph - 2.0943951), 2.0);
    float w2 = pow(0.5 + 0.5 * cos(ph - 4.1887902), 2.0);
    vec3 fc = (u_pal[2] * w0 + u_pal[3] * w1 + u_pal[4] * w2) / (w0 + w1 + w2 + 1e-4);
    vec3 fl = lab2lin(fc);
    // reflectance grows toward the rim (a slanted film reflects more)
    float fres = 0.012 + 0.988 * pow(1.0 - nz, 3.4);
    float amt = fres * mix(0.55, 0.9, sat(rich - 0.4));
    vec3 film = fl * amt;
    // glints of a soft window, upper left, and a small second one lower right
    vec2 g1 = rot(q - vec2(-0.4, 0.44), 0.75) / vec2(0.1, 0.24);
    vec2 g2 = rot(q - vec2(0.52, -0.5), 0.75) / vec2(0.04, 0.09);
    vec2 a1 = g1 * g1;
    vec2 a2 = g2 * g2;
    float gl = exp(-pow(a1.x * a1.x + a1.y * a1.y, 0.75) * 1.2) * 0.9 + 0.45 * exp(-pow(a2.x * a2.x + a2.y * a2.y, 0.75) * 1.2);
    // the ground reflected dimly in the lower half
    vec3 dk = col * (1.0 - 0.2 * amt) + film * 1.1 + glintC * gl * 0.85;
    vec3 tintL = fl / max(dot(fl, vec3(0.2126, 0.7152, 0.0722)), 1e-3);
    vec3 lt = col * mix(vec3(1.0), tintL * 0.9, sat(amt * 1.5)) * (1.0 - 0.08 * smoothstep(0.0, -0.9, q.y) * (1.0 - nz)) + glintC * gl * 0.6;
    vec3 c = mix(lt, dk, u_dark);
    // the thin dark line of the film's edge, seen exactly edge-on
    c *= 1.0 - 0.25 * smoothstep(0.96, 1.0, e) * mix(1.0, 0.4, u_dark);
    col = mix(col, c, cov);
  }
  return lin2srgb(shoulder(col));
}

// Lensball: a sphere of clear crystal resting on a dark, glossy ledge at dusk, the sky behind it far out of focus. The
// crystal bends the whole scene into itself, sharp, turned upside down and squeezed toward its rim, so the soft
// colours behind become a small clear picture inside it: sky, glow and the line of distant hills. A thin bright rim and
// a darker ring where the light leaves through the edge outline it; the ledge mirrors it, and the light it gathers
// falls as a bright spot beside its shadow. Clouds drift across the sky, and inside the crystal they drift backwards.
// Palette: 0 the sky high up, 1 the sky low down, 2 the glow on the horizon, 3 the hills, 4 the ledge, 5 the sun.
// Options: x = motion (how fast the clouds drift), y = focus (how soft the background is).
// Dynamic: u_sun moves the sun along the horizon (and below it at night). Perspective: the far scene is tiltD -1, the
// crystal and its ledge tiltD 0.7.
const float T = 60.0;

// the land and sky behind the crystal; blur 0 = sharp, 1 = far out of focus
vec3 upper(vec2 q, float a, float m, float blur) {
  float hy = -0.3;
  vec3 sky = mix(u_pal[1], u_pal[0], smoothstep(hy - 0.05, 1.1, q.y));
  vec2 sp = vec2(-0.55, hy + 0.1) + u_sun * vec2(0.8, 0.6);
  float sd = length((q - sp) * vec2(0.8, 1.0));
  sky = mix(sky, u_pal[2], exp(-sd * sd / mix(0.08, 0.16, blur)) * 0.9);
  vec3 lin = lab2lin(sky);
  // clouds: long soft bands lit from below by the glow
  float cl = fbm3(vec3(q.x * 1.2 + 0.25 * m * sin(a), q.y * 4.0, 1.0) + vec3(orbit(a, 0.18 * m), 0.0));
  float band = smoothstep(0.05, 0.4, cl + 0.25 * sin(q.y * 9.0)) * smoothstep(hy + 0.05, hy + 0.35, q.y) * smoothstep(1.0, 0.3, q.y);
  lin = mix(lin, lab2lin(mix(u_pal[2], u_pal[0], 0.35)), band * mix(0.4, 0.22, blur));
  // the sun, low, and the hills on the horizon
  float sun = exp(-sd * sd / mix(0.0012, 0.02, blur));
  lin += lab2lin(u_pal[5]) * sun * mix(1.4, 0.5, blur);
  float hill = hy + 0.05 * sin(q.x * 3.1 + 1.0) + 0.03 * sin(q.x * 7.3 + 2.0) + 0.012 * sin(q.x * 17.0);
  float hs = mix(0.008, 0.05, blur);
  vec3 hc = lab2lin(mix(u_pal[3], u_pal[2], 0.15 * smoothstep(hill - 0.12, hill, q.y)));
  lin = mix(lin, hc, smoothstep(hill + hs, hill - hs, q.y));
  // the lights of a far town at the water's edge: large soft discs out of focus, sharp points in focus
  for (int i = 0; i < 9; i++) {
    float f = float(i);
    vec3 h = hash33(vec3(f * 3.7, 1.3, 7.1)) * 0.5 + 0.5;
    vec2 lp = vec2(-1.75 + f * 0.43 + 0.2 * h.x, hy - 0.06 + 0.035 * h.y);
    float br = mix(0.004, mix(0.035, 0.07, h.x), blur);
    float ld = length(q - lp);
    float disc = smoothstep(br, br * 0.8, ld) * (0.7 + 0.3 * smoothstep(br * 0.4, br * 0.95, ld));
    float pt = exp(-ld * ld / (br * br * 0.4));
    float k = mix(pt, disc * mix(0.35, 0.55, h.z), smoothstep(0.2, 0.6, blur));
    lin += lab2lin(mix(u_pal[2], u_pal[5], 0.45)) * k * (0.8 + 0.2 * sin(a * 2.0 + h.z * TAU)) * step(0.3, h.y + 0.25 * f - floor(h.y + 0.25 * f) + 0.0) ;
  }
  return lin;
}

// the whole scene: below the shore a still lake mirrors the land and sky, a little darker, with a long glitter of sun
vec3 scene(vec2 q, float a, float m, float blur) {
  float sy = -0.42;
  float ws = mix(0.003, 0.03, blur);
  float w = smoothstep(sy + ws, sy - ws, q.y);
  vec2 qq = mix(q, vec2(q.x + 0.006 * sin(q.y * 60.0 + 2.0 * a) * (sy - q.y), 2.0 * sy - q.y), w);
  vec3 lin = upper(qq, a, m, blur);
  float glit = exp(-pow((q.x + 0.55 - u_sun.x * 0.8) / mix(0.05, 0.1, blur), 2.0)) * (0.6 + 0.4 * sin(q.y * 140.0 - 3.0 * a));
  return mix(lin, lin * 0.62 + lab2lin(u_pal[5]) * glit * 0.12 * exp((q.y - sy) * 3.0), w);
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.3, 1.5, u_opt.x);
  float bl = mix(0.55, 1.0, u_opt.y);
  vec2 C = vec2(0.62, -0.08);
  float R = 0.52;
  float ledge = C.y - R;
  // behind: the scene out of focus, and the ledge in front of it, glossy and dark
  vec2 pf = p + tiltD(-1.0);
  p += tiltD(0.7);
  vec3 col = scene(pf, a, m, bl);
  float onLedge = smoothstep(ledge + 0.006, ledge - 0.006, p.y);
  float lip = exp(-pow((p.y - ledge + 0.008) / 0.006, 2.0));
  vec2 mp = vec2(p.x, 2.0 * ledge - p.y);
  // the ledge only below its edge (a branch by region, so the cost is paid only there)
  if (onLedge > 0.0) {
  vec3 refl = scene(vec2(mp.x, mp.y), a, m, 1.0) * 0.11;
  vec3 led = lab2lin(mix(u_pal[4], setL(u_pal[4], u_pal[4].x * 0.7), smoothstep(ledge, -1.0, p.y))) + refl;
  // the crystal's shadow and the light it focuses on the ledge
  vec2 sp = (p - vec2(C.x + 0.38, ledge - 0.05)) / vec2(0.55, 0.06);
  led *= 1.0 - 0.55 * exp(-dot(sp, sp));
  vec2 fp = (p - vec2(C.x + 0.3, ledge - 0.035)) / vec2(0.09, 0.016);
  led += lab2lin(mix(u_pal[2], u_pal[5], 0.5)) * exp(-dot(fp, fp)) * 0.9;
  // the crystal mirrored in the ledge
  vec2 dm = mp - C;
  float rm = length(dm) / R;
  vec3 mir = scene(C - dm * 2.3 / max(0.35, 1.0 - 0.45 * rm * rm), a, m, 0.0);
  led = mix(led, led * 0.5 + mir * 0.3, smoothstep(1.0, 0.96, rm) * smoothstep(ledge - 0.5, ledge, p.y));
  col = mix(col, led, onLedge);
  }
  col += lab2lin(mix(u_pal[2], u_pal[5], 0.5)) * lip * 0.12 * exp(-pow((p.x + 0.55) / 1.2, 2.0));
  // the crystal: the scene through it, upside down and squeezed toward the rim, with a fine spectral fringe
  vec2 d = p - C;
  float r = length(d) / R;
  float cov = smoothstep(1.0 + 1.5 * edgePx() / R, 1.0 - 1.5 * edgePx() / R, r);
  float k = 2.3 / max(0.35, 1.0 - 0.45 * r * r);
  vec2 qn = d / R;
  if (cov > 0.0) {
  vec3 inn;
  inn.r = scene(C - qn * R * k * 0.985, a, m, 0.0).r;
  inn.g = scene(C - qn * R * k, a, m, 0.0).g;
  inn.b = scene(C - qn * R * k * 1.018, a, m, 0.0).b;
  float rim = smoothstep(0.82, 0.97, r);
  inn *= 1.0 - 0.75 * rim * (1.0 - smoothstep(0.97, 1.0, r));
  inn += lab2lin(u_pal[5]) * exp(-pow((r - 0.985) / 0.01, 2.0)) * 0.35;
  // the window of the sky caught on the top, and a hot glint
  vec2 gq = (qn - vec2(-0.32, 0.55)) / vec2(0.32, 0.14);
  inn += lab2lin(mix(u_pal[0], u_pal[5], 0.4)) * exp(-pow(dot(gq, gq), 1.5)) * 0.16;
  col = mix(col, inn, cov);
  }
  return lin2srgb(shoulder(col));
}

// Ridgeline: range after range of mountains at the last of the sun, each ridge paler and bluer than the one in front
// as the air between them thickens, the sky burning from deep colour overhead to a hot glow on the horizon. Mist lies in
// the valleys and drifts slowly between the ranges, catching the light; the sun's glow breathes as thin cloud passes.
// Palette: 0 the sky overhead, 1 the glow on the horizon, 2 the nearest range, 3 the far ranges (the air), 4 the mist,
// 5 the sun.
// Options: x = motion (how far the mist drifts), y = haze (clear air to thick haze).
// Dynamic: u_sun moves the sun along the horizon. Perspective: each range is its own layer, the sky the farthest.
const float T = 72.0;

float ridge(float x, float i) {
  float s = i * 1.73;
  float h = 0.5 * sin(x * (1.1 + 0.25 * i) + s) + 0.25 * sin(x * (2.3 + 0.4 * i) + s * 2.1) + 0.12 * sin(x * (4.7 + 0.9 * i) + s * 0.7);
  h += 0.05 * sin(x * (9.8 + 2.0 * i) + s * 3.3) + 0.022 * sin(x * (21.0 + 3.0 * i) + s * 1.9);
  // rock: finer, sharper detail on the nearer ranges
  h += (0.012 * abs(sin(x * 43.0 + s)) + 0.006 * abs(sin(x * 97.0 + s * 2.0))) * i / 4.0;
  return h;
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.5, u_opt.x);
  float hz = mix(0.6, 1.5, u_opt.y);
  vec2 sun = vec2(0.45, -0.12) + u_sun;
  // the sky: deep overhead, burning toward the horizon, brightest near the sun
  vec2 ps = p + tiltD(-1.0);
  float sky = smoothstep(-0.35, 1.0, ps.y);
  vec3 col = lab2lin(mix(u_pal[1], u_pal[0], pow(sky, 0.8)));
  vec2 sd = (ps - sun) * vec2(0.6, 1.0);
  float glow = exp(-dot(sd, sd) * 2.2) * (0.85 + 0.15 * sin(a + 0.4));
  col += lab2lin(u_pal[1]) * glow * 0.45 + lab2lin(u_pal[5]) * (exp(-dot(sd, sd) * 60.0) * 0.9 + exp(-dot(sd, sd) * 9.0) * 0.18);
  // faint rays fanning up from the sun behind the far ridge
  vec2 rv = ps - sun;
  float ra = atan(rv.x, rv.y);
  float rays = 0.5 + 0.5 * sin(ra * 15.0 + 1.5 * sin(ra * 4.0 + 0.5 * sin(a)) + a);
  col += lab2lin(u_pal[1]) * rays * rays * exp(-length(rv) * 1.6) * smoothstep(0.0, 0.3, rv.y + 0.2) * 0.12 * (0.7 + 0.3 * sin(a + ra * 3.0));
  // thin high cloud catching the light
  float cl = fbm3(vec3(ps.x * 0.9 + 0.2 * m * sin(a), ps.y * 5.0, 2.0) + vec3(orbit(a, 0.2 * m), 0.0));
  col = mix(col, lab2lin(mix(u_pal[1], u_pal[5], 0.3)), smoothstep(0.1, 0.5, cl) * smoothstep(-0.05, 0.4, ps.y) * smoothstep(0.95, 0.35, ps.y) * 0.25);
  // the ranges, far to near; each further one is lifted toward the colour of the air
  for (int i = 0; i < 5; i++) {
    float f = float(i);
    float z = f / 4.0;
    vec2 q = p + tiltD(-0.7 + 1.7 * z);
    float base = -0.08 - 0.19 * f;
    float amp = 0.11 + 0.05 * f;
    float y = base + amp * ridge(q.x * (1.0 + 0.15 * f) + f * 3.1, f);
    float d = q.y - y;
    float ew = edgePx() * 1.2 + 0.01 * (1.0 - z) * hz;
    float cov = smoothstep(ew, -ew, d);
    float air = (1.0 - z) * 0.85 * hz;
    vec3 rc = mix(u_pal[2], u_pal[3], sat(air));
    // the slopes facing the sun keep a little warm light; the valleys fill with shade
    rc = setL(rc, rc.x + 0.05 * (1.0 - z) * exp(-pow((q.x - sun.x) * 0.9, 2.0)));
    vec3 lin = lab2lin(rc);
    lin = mix(lin, lab2lin(u_pal[1]), glow * (1.0 - z) * 0.35);
    // the mist in the valley just below this ridge's crest
    float mist = smoothstep(-0.04, -0.22 - 0.04 * f, d) * sat(0.55 + 0.6 * lnoise(vec2(q.x * 0.9 + f * 7.0, d * 7.0), a + f, 0.45 * m));
    lin = mix(lin, lab2lin(u_pal[4]) * (0.8 + 0.4 * glow), mist * (0.35 - 0.05 * f) * hz);
    col = mix(col, lin, cov);
  }
  return lin2srgb(shoulder(col));
}

// Plume: a peacock's feather seen close, its colour made by structure, not pigment. From the shaft, fine barbs sweep
// out and curve; each throws back one pure, metallic colour that depends on the angle between it, the light and the eye,
// so as the light slowly circles a wave of colour rolls along the vane, from green through blue to violet and gold.
// Only a band across the feather is in focus; beyond it the barbs melt into soft colour, as in a macro photograph.
// Palette: 0 background, 1 background glow, 2 first sheen colour, 3 second, 4 third, 5 the light on the shaft.
// Options: x = motion (how far the light swings and the feather sways), y = depth of field (deep to shallow).
// Perspective: the background is the far layer, the feather near.
const float T = 56.0;

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.4, u_opt.x);
  float dof = mix(0.4, 1.5, u_opt.y);
  vec2 pb = p + tiltD(-1.0) - vec2(-0.5, 0.3);
  vec3 col = lab2lin(mix(u_pal[0], u_pal[1], exp(-dot(pb, pb) * 0.5)));
  vec2 q = p + tiltD(0.6);
  // the shaft: a gentle curve from the lower left, swaying a little
  float sway = 0.03 * m * sin(a + 0.6);
  vec2 o = vec2(-1.9, -1.25);
  vec2 dir = normalize(vec2(1.0, 0.62));
  vec2 r = q - o;
  float u = dot(r, dir);
  float v0 = dot(r, vec2(-dir.y, dir.x));
  float bend = 0.07 * u * u - 0.02 * u * u * u + sway * u;
  float v = v0 - bend;
  float side = v >= 0.0 ? 1.0 : -1.0;
  float av = abs(v);
  // the vane's outline: wide in the middle, tapering to the tip, its edge ragged where barbs end at different lengths
  float len = 3.9;
  float s = u / len;
  float wv = 0.62 * pow(sat(sin(3.14159265 * pow(sat(s), 0.75))), 0.7);
  float k = 140.0;
  float ph = (u - av * 1.25 - av * av * 0.35) * k + 2.5 * gnoise(vec3(u * 3.0, av * 2.0, side));
  float bi = floor(ph / TAU);
  vec3 bh = hash33(vec3(bi, side, 3.3)) * 0.5 + 0.5;
  float edge = wv * (0.86 + 0.14 * (0.5 + 0.5 * gnoise(vec3(u * 4.5, side * 3.0, 1.0))) + 0.04 * bh.x);
  float inV = smoothstep(edge, edge - 0.12, av) * smoothstep(-0.05, 0.03, s) * smoothstep(1.02, 0.92, s);
  // focus: sharp in a band across the feather, soft away from it
  float fd = abs(u - 2.0 - 0.15 * v);
  float blur = sat(fd * 0.5 * dof);
  float fine = sat(TAU / k / u_px / 5.0 - 0.3);
  float sharpw = mix(5.0, 0.6, blur) * mix(1.0, 0.5, 1.0 - fine);
  float barb = pow(0.5 + 0.5 * cos(ph), sharpw);
  barb = mix(0.5, barb, fine * (1.0 - blur * 0.85));
  // the colour: set by the angle of each barb against the circling light
  vec2 bdir = normalize(vec2(1.25 + 0.7 * av + 0.4 * sin(u * 1.3), side * (1.0 - 0.6 * av)));
  float la = a + 0.5 * m * sin(a * 2.0);
  float c = dot(bdir, vec2(cos(la), sin(la))) * 0.5 + 0.5;
  float w2 = c * 1.4 - 0.25 + 0.4 * s + 1.1 * av / max(wv, 0.1) * (0.5 + 0.5 * sin(la - u * 0.8)) + 0.06 * bh.y;
  vec3 sc = mix(u_pal[2], u_pal[3], smoothstep(0.2, 0.9, w2));
  sc = mix(sc, u_pal[4], smoothstep(0.85, 1.6, w2));
  float shine = 0.25 + 0.95 * pow(sat(sin(c * 3.14159265)), 2.0);
  vec3 bl = lab2lin(sc) * shine;
  // the shaft itself: a thin pale line with a highlight
  float shaft = exp(-v * v / (0.00012 + 0.00002 * blur * 40.0)) * smoothstep(1.0, 0.85, s) * smoothstep(-0.02, 0.05, s);
  vec3 dk = col * (1.0 - inV * 0.85) + bl * inV * (0.18 + 1.05 * barb) * (1.0 - 0.5 * smoothstep(0.4, 1.0, av / max(edge, 1e-3))) + lab2lin(u_pal[5]) * shaft * 0.6;
  vec3 lt = mix(col, col * mix(vec3(1.0), bl / max(dot(bl, vec3(0.2126, 0.7152, 0.0722)), 0.05) * 0.8, 0.85) * (0.58 + 0.6 * barb) * (0.85 + 0.25 * shine), inV);
  lt = mix(lt, lab2lin(u_pal[5]), shaft * 0.5);
  return lin2srgb(shoulder(mix(lt, dk, u_dark)));
}

// Torus: a ring of solid clear glass hanging in front of soft fields of colour, turning slowly on a thread. Seen through
// its round tube the colours behind are turned over and squeezed, split into a fine spectrum at the edges, with the
// darker band and the bright inner lines a glass rod always shows; where the ring passes in front of itself, the near
// side bends the far side too. As it turns, the ring narrows toward edge-on and opens again.
// Palette: 0 the ground, 1 first field of colour, 2 second field, 3 third field, 4 the glass tint, 5 the white of the
// highlights.
// Options: x = motion (how far the ring turns), y = thickness of the glass.
// Perspective: the fields of colour are far (tiltD -1), the ring near (tiltD 0.8).
const float T = 48.0;

vec3 fields(vec2 q, float a, float m) {
  vec3 c = u_pal[0];
  vec2 c1 = vec2(-0.9, 0.45) + m * 0.12 * vec2(sin(a), cos(a));
  vec2 c2 = vec2(0.9, -0.55) + m * 0.1 * vec2(cos(a + 2.0), sin(a + 2.0));
  vec2 c3 = vec2(0.45, 0.75) + m * 0.1 * vec2(sin(a + 4.0), cos(a + 4.0));
  float w1 = exp(-dot(q - c1, q - c1) * 0.9);
  float w2 = exp(-dot(q - c2, q - c2) * 0.8);
  float w3 = exp(-dot(q - c3, q - c3) * 1.4);
  c = mix(c, u_pal[1], w1);
  c = mix(c, u_pal[2], w2);
  c = mix(c, u_pal[3], w3 * 0.9);
  return lab2lin(c);
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.3, 1.4, u_opt.x);
  float rt = mix(0.08, 0.15, u_opt.y);
  vec2 pf = p + tiltD(-1.0);
  vec3 bg = fields(pf, a, m);
  vec2 q = p + tiltD(0.8);
  vec2 C = vec2(0.42, 0.02);
  float Rm = 0.6;
  float phi = 0.55 + 0.75 * m * sin(a + 0.9) + 0.15 * m * sin(2.0 * a + 1.0);
  float psi = 0.42;
  float cf = cos(phi);
  float sf = sin(phi);
  float cp = cos(psi);
  float sp = sin(psi);
  // the nearest point of the ring's centre line, on its near half and on its far half
  float dN = 9.0;
  float dF = 9.0;
  float tN = 0.0;
  float tF = 0.0;
  for (int i = 0; i < 40; i++) {
    float th = float(i) * TAU / 40.0;
    vec2 P = C + Rm * vec2(cos(th) * cf, sin(th) * cp + cos(th) * sf * sp);
    float Z = sin(th) * sp - cos(th) * sf * cp;
    float d = length(q - P);
    if (Z >= 0.0) { if (d < dN) { dN = d; tN = th; } } else { if (d < dF) { dF = d; tF = th; } }
  }
  vec3 col = bg;
  vec3 wht = lab2lin(u_pal[5]);
  vec3 tint = lab2lin(vec3(0.85, u_pal[4].yz * 0.7));
  tint /= max(dot(tint, vec3(0.2126, 0.7152, 0.0722)), 1e-3);
  // far half first, then the near half over it
  for (int j = 0; j < 2; j++) {
    float th0 = j == 0 ? tF : tN;
    // this half of the ring runs over [lo, lo + pi]: the near half where the ring faces us, the far half behind
    float lo = atan(sf * cp, sp) + (j == 0 ? 3.14159265 : 0.0);
    // refine the nearest point with two Newton-like steps along the curve
    float th = th0;
    for (int k = 0; k < 3; k++) {
      vec2 P = C + Rm * vec2(cos(th) * cf, sin(th) * cp + cos(th) * sf * sp);
      vec2 D = Rm * vec2(-sin(th) * cf, cos(th) * cp - sin(th) * sf * sp);
      th += clamp(dot(q - P, D) / max(dot(D, D), 1e-4), -0.12, 0.12);
      float rel = th - lo;
      rel -= TAU * floor(rel / TAU);
      rel = rel > 3.14159265 + 0.5 * (TAU - 3.14159265) ? 0.0 : min(rel, 3.14159265);
      th = lo + rel;
    }
    vec2 P = C + Rm * vec2(cos(th) * cf, sin(th) * cp + cos(th) * sf * sp);
    vec2 D = normalize(Rm * vec2(-sin(th) * cf, cos(th) * cp - sin(th) * sf * sp));
    vec2 nrm = vec2(-D.y, D.x);
    float sv = dot(q - P, nrm);
    // beyond the end of this half the other half takes over: a straight cut, not a cap
    float along = abs(dot(q - P, D));
    float v = sv / rt;
    float av = abs(v);
    float cov = smoothstep(1.0 + edgePx() / rt, 1.0 - edgePx() / rt, av) * smoothstep(0.06, 0.03, along);
    float nz = sqrt(max(1.0 - v * v, 0.0));
    // through the rod: what lies behind, turned over and squeezed, a little split by colour
    vec2 base = P - nrm * sv * 2.6;
    vec3 thru;
    thru.r = fields(base - nrm * sv * 0.12 + tiltD(-1.0), a, m).r;
    thru.g = fields(base + tiltD(-1.0), a, m).g;
    thru.b = fields(base + nrm * sv * 0.14 + tiltD(-1.0), a, m).b;
    thru = mix(thru, (col - bg) * 0.6 + thru, 0.5);
    thru *= mix(vec3(1.0), tint, 0.35) * (0.8 + 0.35 * nz);
    vec3 vk = av * vec3(0.985, 1.0, 1.016);
    vec3 e1 = (vk - 0.9) / 0.035;
    vec3 e2 = (vk - 0.6) / 0.06;
    vec3 e3 = (vk - 0.76) / 0.08;
    vec3 line = exp(-e1 * e1) * 1.0 + exp(-e2 * e2) * 0.25;
    thru *= 1.0 - 0.6 * exp(-e3 * e3);
    thru += wht * line * mix(0.35, 0.6, u_dark);
    // the highlight of the light above, along the upper side of the tube
    vec3 n3 = vec3(nrm * v, nz);
    vec3 H = normalize(normalize(vec3(-0.45, 0.75, 0.55)) + vec3(0.0, 0.0, 1.0));
    float nh = sat(dot(n3, H));
    thru += wht * (pow(nh, 90.0) * 0.9 + pow(nh, 12.0) * 0.06);
    thru = mix(thru, bg * 0.55, smoothstep(0.94, 1.0, av) * 0.4);
    col = mix(col, thru, cov);
  }
  return lin2srgb(shoulder(col));
}

// Quicksilver: a sea of liquid metal under an evening sky. Long, slow swells roll across it toward the horizon, and
// every one mirrors the sky exactly: deep colour where the surface tips toward the zenith, the glow of the horizon where
// it faces away, and a broken path of hot light below the low sun. Near swells are large and smooth; far off they crowd
// into a fine shimmer and then a flat bright line at the horizon.
// Palette: 0 the sky overhead, 1 the glow on the horizon, 2 the second glow, 3 the metal's tint, 4 the sky's mid
// colour, 5 the sun.
// Options: x = motion (how high the swells run), y = swell (long and glassy to short and choppy).
// Dynamic: u_sun moves the sun. Perspective: the sky is far, the sea near.
const float T = 40.0;

vec3 sky(vec3 r, vec2 sunP) {
  float e = r.y;
  vec3 c = mix(u_pal[1], u_pal[4], smoothstep(0.0, 0.22, e));
  c = mix(c, u_pal[0], smoothstep(0.15, 0.75, e));
  float az = r.x / max(r.z, 0.05) - sunP.x;
  float sd = length(vec2(az * 0.8, e - sunP.y));
  c = mix(c, u_pal[2], exp(-sd * sd * 3.0) * 0.6 * smoothstep(0.5, -0.05, e));
  vec3 lin = lab2lin(c);
  lin += lab2lin(u_pal[5]) * (exp(-sd * sd * 700.0) * 2.0 + exp(-sd * sd * 30.0) * 0.25);
  return lin;
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.4, 1.4, u_opt.x);
  float sw = mix(0.75, 1.5, u_opt.y);
  float hy = 0.02;
  vec2 sunP = vec2(0.35, 0.09) + u_sun * vec2(0.6, 0.4);
  vec2 ps = p + tiltD(-1.0);
  vec3 col;
  if (ps.y > hy) {
    col = sky(normalize(vec3(ps.x, ps.y - hy, 1.6)), sunP);
  } else {
    vec2 q = p + tiltD(0.8);
    float dy = max(hy - q.y, 0.002);
    float z = 1.1 / dy;
    vec2 W = vec2(q.x * z, z);
    // the swells: travelling waves whose speeds are whole numbers of turns per loop; their height fades with distance
    // as each one becomes smaller than a pixel
    float foot = z * z * u_px / 1.1;
    vec2 g = vec2(0.0);
    for (int i = 0; i < 8; i++) {
      float f = float(i);
      float an = 0.18 + 0.32 * sin(f * 2.3 + 0.4) * (0.4 + 0.15 * f);
      vec2 k = vec2(sin(an), cos(an)) * (0.7 + 0.55 * f + 0.08 * f * f) * sw;
      float kk = length(k);
      float A = 0.3 * m / (1.0 + 2.0 * f) * exp(-foot * kk * 1.2);
      float n = 1.0 + floor(f * 0.5);
      float ph = dot(k, W) - n * a + f * 1.7;
      g += A * kk * cos(ph) * k / kk;
    }
    vec3 nrm = normalize(vec3(-g.x, 1.0, -g.y));
    vec3 d = normalize(vec3(q.x, q.y - hy, 1.6));
    vec3 r = reflect(d, nrm);
    r.y = abs(r.y);
    vec3 env = sky(r, sunP);
    vec3 tint = lab2lin(vec3(0.85, u_pal[3].yz));
    tint /= max(dot(tint, vec3(0.2126, 0.7152, 0.0722)), 1e-3);
    float fres = 0.72 + 0.28 * pow(1.0 - sat(dot(-d, nrm)), 5.0);
    col = env * tint * fres;
    // the far sea melts into a bright line at the horizon
    col = mix(col, sky(normalize(vec3(q.x, 0.004, 1.6)), sunP) * 0.95, smoothstep(0.04, 0.0, dy) * 0.8);
  }
  return lin2srgb(shoulder(col));
}

// Milky Way: the core of the galaxy rising over a dark ridge on a moonless night. The band of light climbs from the
// horizon, brightest and warmest in the bulge low down, split by dark rifts of dust; stars crowd toward it. Near the
// horizon the air itself glows faintly green and red in slow ripples, and now and then a meteor draws a quick line.
// Palette: 0 the sky high, 1 the sky low, 2 the band's light, 3 the bulge, 4 the airglow, 5 the stars.
// Options: x = motion (how much the airglow ripples and the stars twinkle), y = brightness of the band.
// Perspective: the sky is far (tiltD -1), the ridge near (tiltD 1).
const float T = 75.0;

float starField(vec2 q, float sc, float thr, float a, float seed) {
  vec2 g = q * sc;
  vec2 id = floor(g);
  vec3 h = hash33(vec3(id, seed)) * 0.5 + 0.5;
  vec2 c = id + 0.5 + (h.xy - 0.5) * 0.75;
  float d = length(g - c) / sc;
  float r = 0.8 * u_px;
  float s = exp(-(d * d) / (r * r)) * step(thr, h.z) * (h.z - thr) / (1.0 - thr);
  float vis = sat((1.0 / sc) / u_px / 7.0 - 0.4);
  return s * vis * (0.75 + 0.25 * sin(a * 3.0 + h.x * TAU));
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.3, 1.4, u_opt.x);
  float br = mix(0.55, 1.4, u_opt.y);
  vec2 q = p + tiltD(-1.0);
  vec3 col = lab2lin(mix(u_pal[1], u_pal[0], smoothstep(-0.7, 0.9, q.y)));
  // the band: a great circle climbing from the lower left
  vec2 o = vec2(-0.75, -0.62);
  vec2 dir = normalize(vec2(0.62, 1.0));
  vec2 r = q - o;
  float along = dot(r, dir);
  float across = dot(r, vec2(-dir.y, dir.x));
  float wid = 0.24 + 0.1 * smoothstep(0.8, 0.0, along);
  float band = exp(-across * across / (wid * wid)) * smoothstep(-0.25, 0.15, along) * (0.55 + 0.45 * smoothstep(2.6, 0.2, along));
  float bulge = exp(-dot(r - dir * 0.18, r - dir * 0.18) * 5.0);
  // clouds of stars and the dark rifts of dust along it
  vec3 sq = vec3(along * 2.2, across * 3.2, 1.0);
  float mot = fbm4(sq * 1.3 + vec3(0.0, 0.0, 0.0));
  float lane = 1.0 - abs(fbm3(vec3(along * 2.0, across * 4.5 + 0.6 * mot, 4.0)) * 2.6);
  float rift = smoothstep(0.45, 0.92, lane) * exp(-pow(across / wid - 0.1, 2.0) * 1.5);
  float grain = 0.6 + 0.8 * (0.5 + 0.5 * gnoise(vec3(along * 16.0, across * 16.0, 3.0))) * (0.5 + 0.5 * gnoise(vec3(along * 5.0, across * 5.0, 6.0)));
  float glow = band * (0.45 + 0.6 * mot) * grain * (1.0 - 0.8 * rift);
  vec3 bc = mix(lab2lin(u_pal[2]), lab2lin(u_pal[3]), bulge);
  col += bc * (glow * 0.34 + bulge * (1.0 - 0.75 * rift) * 0.35) * br;
  // stars, more of them near the band
  float stars = starField(q, 34.0, 0.9 - 0.06 * band, a, 2.0) + 0.7 * starField(q, 71.0, 0.86 - 0.1 * band, a, 5.0);
  stars += 0.5 * starField(q + 0.37, 140.0, 0.8 - 0.15 * band, a, 9.0) * band;
  col += lab2lin(u_pal[5]) * stars;
  // airglow: faint banded light low in the sky, rippling slowly
  float wave = sin(q.x * 5.0 + q.y * 9.0 - 2.0 * a + 0.8 * sin(q.x * 1.3 + a)) * 0.5 + 0.5;
  float ag = exp(-pow((q.y + 0.4) / 0.24, 2.0)) * (0.45 + 0.55 * mix(0.5, wave, sat(0.5 * m + 0.2))) * (0.75 + 0.25 * sin(q.x * 1.7 - a));
  col += lab2lin(u_pal[4]) * ag * 0.26;
  // a meteor, twice per loop, each a short bright streak that fades
  for (int k = 0; k < 2; k++) {
    float fk = float(k);
    float ph = fract(a / TAU * 2.0 + fk * 0.5 + 0.13);
    float life = smoothstep(0.0, 0.02, ph) * smoothstep(0.08, 0.02, ph);
    vec2 s0 = vec2(0.9 - 1.4 * fk, 0.75 - 0.15 * fk);
    vec2 md = normalize(vec2(-0.7 + 1.0 * fk, -0.45));
    vec2 mp = s0 + md * ph * 6.0;
    vec2 dv = q - mp;
    float al = dot(dv, md);
    float ac = dot(dv, vec2(-md.y, md.x));
    float streak = exp(-ac * ac / (u_px * u_px * 1.6 + 1e-6)) * smoothstep(-0.25, 0.0, al) * smoothstep(0.01, -0.01, al);
    col += lab2lin(u_pal[5]) * streak * life * 0.9 * (0.5 + 0.5 * m);
  }
  // the ridge, black against the glow, with the faintest rim of light
  vec2 qr = p + tiltD(1.0);
  float ridge = -0.7 + 0.1 * sin(qr.x * 1.3 + 2.0) + 0.05 * sin(qr.x * 3.7 + 0.4) + 0.02 * sin(qr.x * 9.1) + 0.008 * sin(qr.x * 23.0 + 1.0);
  float rc = smoothstep(edgePx() * 1.3, -edgePx() * 1.3, qr.y - ridge);
  vec3 rl = lab2lin(setL(u_pal[0], u_pal[0].x * mix(0.45, 0.75, 1.0 - u_dark)));
  col = mix(col, rl, rc);
  // light mode: the same sky at the blue hour, so the band is a pale veil
  vec3 lt = mix(lab2lin(mix(u_pal[1], u_pal[0], smoothstep(-0.7, 0.9, q.y))), lab2lin(u_pal[4]), exp(-pow((q.y + 0.6) / 0.35, 2.0)) * 0.6 * (0.55 + 0.9 * ag));
  lt = mix(lt, bc, sat(glow * 0.9 + bulge * 0.4) * 0.5 * br);
  lt = mix(lt, rl, rc);
  return lin2srgb(shoulder(mix(lt, col, u_dark)));
}

// Taffeta: a length of shot silk lifting in a slow wind. Shot silk is woven with a warp of one colour and a weft of
// another, so the cloth shows one where it faces you and the other where it turns away: as the billows travel across
// it, the colour rolls from one to the other along every fold. A long soft sheen rides the crests, and the troughs
// fall into a deep, rich shade.
// Palette: 0 the deepest shade, 1 the warp (facing colour), 2 the weft (the colour at a slant), 3 the sheen, 4 the
// warm light on the crests, 5 the shade's colour.
// Options: x = motion (how high the cloth billows), y = folds (broad billows to fine ripples).
// Dynamic: u_sun turns the light, so the sheen slides across the folds through the day.
const float T = 45.0;

float cloth(vec2 q, float a, float m) {
  // flow lines across the cloth, bent by billows travelling along it; the folds lie along them
  float v = q.y;
  float u = q.x * 3.6 + 0.9 * sin(v * 0.9 + a + 0.3 * q.x) + 0.28 * m * sin(v * 1.7 - 2.0 * a + 1.0) + 0.12 * m * sin(v * 3.1 + 3.0 * a + 2.0);
  float h = (sin(u) * 0.62 + 0.24 * sin(2.0 * u + 0.6 + 0.5 * sin(a + v * 0.7))) * (0.75 + 0.35 * sin(v * 0.6 - q.x * 0.5 + a));
  // a soft crease in each trough, where the cloth folds under
  h -= 0.4 * pow(0.5 - 0.5 * sin(u + 0.25), 5.0);
  // the whole sheet lifts and settles in long swells
  h += 0.5 * m * sin(v * 1.1 + q.x * 0.6 - a);
  return h;
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.45, 1.4, u_opt.x);
  float fk = mix(0.75, 1.5, u_opt.y);
  vec2 q = rot(p, -0.42) * fk;
  float e = 0.004;
  float h0 = cloth(q, a, m);
  float hx = cloth(q + vec2(e, 0.0), a, m);
  float hy = cloth(q + vec2(0.0, e), a, m);
  vec2 g = vec2(hx - h0, hy - h0) / e * 0.36;
  vec3 n = normalize(vec3(-g, 1.0));
  vec3 L = normalize(vec3(vec2(-0.45, 0.55) + u_sun, 0.7));
  vec3 V = vec3(0.0, 0.0, 1.0);
  float facing = n.z;
  // the two threads: the warp seen face on, the weft as the cloth turns away
  float slant = smoothstep(0.93, 0.55, facing);
  vec3 base = mix(u_pal[1], u_pal[2], slant * 0.8);
  float dif = sat(dot(n, L) * 1.1 + 0.05);
  float occ = smoothstep(-0.9, 0.5, h0);
  vec3 col = mix(u_pal[0], base, smoothstep(0.0, 0.8, dif * (0.55 + 0.45 * occ)));
  col = mix(col, setL(base, base.x * 1.18), smoothstep(0.75, 1.0, dif) * 0.6);
  col = mix(col, u_pal[5], 0.35 * (1.0 - occ) * (1.0 - dif));
  // silk's sheen: long and soft across the threads, a brighter line along the crest
  vec3 H = normalize(L + V);
  float nh = sat(dot(n, H));
  float sheen = pow(nh, 7.0) * 0.45 + pow(nh, 70.0) * 0.7;
  vec3 sc = mix(u_pal[3], u_pal[4], smoothstep(0.2, 0.9, h0 * 0.5 + 0.5));
  col = mix(col, sc, sat(sheen * mix(0.75, 0.9, u_dark)));
  col.x *= 0.92 + 0.1 * smoothstep(2.2, 0.4, length(p - vec2(-0.6, 0.6)));
  return outLab(col);
}

// Medusa: moon jellies drifting in deep water, lit from within. Each bell is almost clear: its light gathers at the
// scalloped rim, along the fine canals that run out from the crown, and in the four glowing rings at its heart; a fringe
// of hair-fine tentacles hangs from the rim and four ruffled arms trail below. The bells pulse, contracting and
// opening, each in its own slow rhythm, rising a little at every beat.
// Palette: 0 the deep water, 1 the water toward the light, 2 first bell, 3 second bell, 4 the tentacles and arms,
// 5 the glow of the rings.
// Options: x = motion (how strongly the bells pulse and drift), y = glow.
// Perspective: the water is far (tiltD -1); each jelly's depth follows its size.
const float T = 40.0;

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.4, u_opt.x);
  float gl = mix(0.5, 1.5, u_opt.y);
  vec2 pw = p + tiltD(-1.0);
  vec3 water = lab2lin(mix(u_pal[0], u_pal[1], smoothstep(-1.2, 1.4, pw.y + 0.2 * pw.x)));
  // light from the surface, in soft shafts
  float shaft = 0.5 + 0.5 * sin(pw.x * 4.0 + pw.y * 1.2 + 0.4 * sin(a));
  water *= 1.0 + 0.12 * shaft * smoothstep(-0.6, 1.2, pw.y);
  vec3 col = water;
  vec3 sumC = vec3(0.0);
  float sumW = 0.0;
  vec3 glowC = lab2lin(u_pal[5]);
  vec3 tl = lab2lin(u_pal[4]);
  for (int i = 0; i < 3; i++) {
    float f = float(i);
    vec2 c = vec2(-0.95, 0.38);
    float S = 0.42;
    float tilt = 0.28;
    vec3 bc = u_pal[2];
    if (i == 1) { c = vec2(0.98, 0.1); S = 0.56; tilt = -0.2; bc = u_pal[3]; }
    if (i == 2) { c = vec2(0.12, 0.74); S = 0.2; tilt = 0.12; bc = mix(u_pal[2], u_pal[3], 0.5); }
    float pulse = 0.5 + 0.5 * sin(a * 2.0 + f * 2.1);
    float pk = pow(pulse, 3.0);
    c += m * vec2(0.04 * sin(a + f * 1.7), 0.05 * cos(a + f) + 0.03 * pk);
    vec2 q = rot(p + tiltD((S - 0.3) * 4.0) - c, -tilt) / S;
    // the bell: a low dome, its rim scalloped; it narrows and deepens as it contracts
    float wB = 1.0 - 0.13 * m * pk;
    float hB = 0.5 + 0.1 * m * pk;
    float ax = abs(q.x / wB);
    float top = hB * pow(max(1.0 - pow(ax, 2.2), 0.0), 0.55);
    float scal = 0.018 * abs(sin(q.x / wB * 14.0));
    float bot = -0.06 + 0.16 * ax * ax - 0.05 * m * pk - scal * smoothstep(0.6, 1.0, ax);
    float ew = 2.0 * edgePx() / S;
    float inB = smoothstep(1.0 + ew, 1.0 - ew, ax) * smoothstep(bot - ew, bot + ew, q.y) * smoothstep(top + ew, top - ew, q.y);
    float h = sat((q.y - bot) / max(top - bot, 0.05));
    float rimT = exp(-pow((q.y - top) / 0.035, 2.0)) * smoothstep(1.02, 0.9, ax);
    float edge = exp(-pow((q.y - bot) / 0.028, 2.0)) * smoothstep(1.06, 0.95, ax);
    // the radial canals, seen through the dome
    float ang = atan(q.x / wB, max(q.y + 0.35, 0.05));
    float canals = pow(0.5 + 0.5 * cos(ang * 22.0), 14.0) * inB * (1.0 - h) * 0.6;
    // the four rings at the heart, seen from the side as horseshoes
    float rings = 0.0;
    for (int k = 0; k < 4; k++) {
      float fk = float(k);
      float an = fk * 1.5708 + 0.4;
      vec2 rc = vec2(cos(an) * 0.2 * wB, 0.16 + sin(an) * 0.06);
      vec2 rq = (q - rc) / vec2(0.13, 0.07);
      float rr = abs(length(rq) - 0.75);
      rings += exp(-rr * rr / 0.12) * 0.6 + exp(-dot(rq, rq) * 0.8) * 0.15;
    }
    rings *= inB;
    float body = inB * (0.08 + 0.35 * pow(ax, 2.5) + 0.12 * (1.0 - h) + 0.2 * pow(h, 6.0));
    // the fringe of fine tentacles from the rim, and four ruffled arms below
    float tent = 0.0;
    for (int k = 0; k < 13; k++) {
      float fk = float(k);
      float x0 = (-0.98 + fk * 0.163) * wB;
      float yy = -0.06 + 0.16 * (x0 / wB) * (x0 / wB) - 0.05 * m * pk - q.y;
      float sway = (0.08 * m * sin(yy * 3.5 - a * 2.0 + fk * 1.3 + f) + 0.04 * sin(yy * 1.7 + fk)) * yy;
      float dx = q.x - x0 * (1.0 - 0.15 * yy) - sway;
      tent += exp(-dx * dx / (pow(edgePx() * 0.9 / S, 2.0) + 0.000015)) * smoothstep(0.0, 0.04, yy) * exp(-yy * 1.3) * 0.8;
    }
    float arm = 0.0;
    for (int k = 0; k < 2; k++) {
      float fk = float(k);
      float yy = -0.06 - q.y;
      float dx = q.x - (fk - 0.5) * 0.22 - 0.09 * m * sin(yy * 4.0 - a * 2.0 + fk * 2.0) * yy;
      float w = 0.05 + 0.028 * sin(yy * 22.0 + fk + a) + 0.01 * sin(yy * 41.0);
      arm += smoothstep(w, w * 0.4, abs(dx)) * smoothstep(0.0, 0.1, yy) * exp(-yy * 1.3);
    }
    vec3 bl = lab2lin(bc);
    vec3 L = bl * (body + rimT * 0.6 + canals * 0.5) + mix(bl, glowC, 0.6) * edge * 0.9 + mix(bl, glowC, 0.45) * rings * 0.4 + tl * (tent * 0.55 + arm * 0.3);
    vec2 hq = q - vec2(0.0, 0.18);
    float halo = exp(-dot(hq, hq) * 1.6) * 0.1;
    L += bl * halo;
    col += L * gl * u_dark;
    float w = body + rimT * 0.5 + canals * 0.4 + edge * 0.7 + rings * 0.5 + tent * 0.6 + arm * 0.35 + halo;
    sumC += mix(mix(bl, glowC, sat(rings * 0.5)), tl, sat((tent + arm) / max(w, 1e-3))) * w;
    sumW += w;
  }
  vec3 avg = sumC / max(sumW, 1e-4);
  vec3 lt = mix(water, avg * 0.9, sat(1.0 - exp(-sumW * 2.6 * gl)) * 0.95);
  return lin2srgb(shoulder(mix(lt, col, u_dark)));
}

// Equinox: a ringed planet seen close, the sun low beyond its right shoulder. The rings are thousands of fine bands
// with dark gaps between them; they cross in front of the planet and pass behind it, the planet casts its shadow across
// them, and they lay their own thin stripes of shadow on its cloud belts. The belts turn slowly, faint spokes drift
// round the rings, and a thin haze of light rims the planet's edge.
// Palette: 0 space, 1 the bright cloud belts, 2 the dark belts, 3 the bright rings, 4 the inner, darker rings, 5 the
// sunlight on the rim.
// Options: x = motion (how turbulent the turning belts are), y = rings (sparse and faint to dense and bright).
// Dynamic: u_sun moves the sun. Perspective: the stars are far (tiltD -1), the planet and rings near (tiltD 0.6).
const float T = 90.0;

float ringDensity(float r, float rk, float fp) {
  // fp: how far r moves across one pixel; bands finer than that fade out instead of aliasing
  // r in planet radii; the rings run from 1.25 to 2.25 with a wide dark gap at 1.95
  float d = smoothstep(1.24, 1.32, r) * smoothstep(2.27, 2.2, r);
  float bands = 0.68 + 0.12 * sin(r * 61.0) * sat(1.6 - 61.0 * fp) + 0.09 * sin(r * 143.0 + 1.0) * sat(1.6 - 143.0 * fp) + 0.07 * sin(r * 311.0 + 2.0) * sat(1.6 - 311.0 * fp) + 0.04 * sin(r * 701.0) * sat(1.6 - 701.0 * fp);
  float zones = mix(0.35, 1.0, smoothstep(1.45, 1.6, r)) * mix(1.0, 0.6, smoothstep(2.0, 2.1, r));
  float gap = 1.0 - 0.92 * exp(-pow((r - 1.93) / 0.025, 2.0)) - 0.6 * exp(-pow((r - 2.13) / max(0.006, fp), 2.0));
  return sat(d * bands * zones * gap * rk);
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.3, 1.5, u_opt.x);
  float rk = mix(0.6, 1.25, u_opt.y);
  vec2 ps = p + tiltD(-1.0);
  vec3 col = lab2lin(mix(u_pal[0], setL(u_pal[0], u_pal[0].x * 1.3 + 0.01), smoothstep(1.2, -1.0, ps.y + ps.x * 0.3)));
  // a few faint stars
  vec2 sg = ps * 30.0;
  vec3 sh = hash33(vec3(floor(sg), 3.3)) * 0.5 + 0.5;
  float sd = length(fract(sg) - 0.5 - (sh.xy - 0.5) * 0.6) / 30.0;
  col += vec3(exp(-sd * sd / (0.7 * u_px * u_px)) * step(0.9, sh.z) * (sh.z - 0.9) * 6.0 * sat((1.0 / 30.0) / u_px / 9.0 - 0.5)) * u_dark;

  vec2 q = p + tiltD(0.6);
  vec2 C = vec2(-1.05, -0.95);
  float R = 1.08;
  vec3 N = normalize(vec3(-0.3, 0.92, 0.25));
  vec3 S = normalize(vec3(vec2(0.8, 0.32) + u_sun, mix(0.6, -0.38, u_dark)));
  vec2 d = (q - C) / R;
  float rr = dot(d, d);
  float inP = smoothstep(1.0 + 1.5 * edgePx() / R, 1.0 - 1.5 * edgePx() / R, sqrt(rr));
  float zs = sqrt(max(1.0 - rr, 0.0));
  vec3 Pn = vec3(d, zs);
  // the ring plane along this line of sight
  float zr = -(d.x * N.x + d.y * N.y) / N.z;
  vec3 X = vec3(d, zr);
  float r = length(X);
  // the planet: belts set by latitude about the ring axis, turning with longitude
  vec3 e1 = normalize(cross(N, vec3(0.0, 0.0, 1.0)));
  vec3 e2 = cross(N, e1);
  float lat = dot(Pn, N);
  float phi = atan(dot(Pn, e2), dot(Pn, e1)) + a;
  vec3 lq = vec3(lat * 5.0, 1.4 * cos(phi), 1.4 * sin(phi));
  float turb = fbm3(lq) * sqrt(max(1.0 - lat * lat, 0.0));
  float w = lat * 1.0 + (0.025 + 0.025 * m) * turb;
  float belt = 0.5 + 0.3 * sin(w * 18.0 + 0.6 * sin(w * 5.0)) + 0.14 * sin(w * 47.0 + 1.0) + 0.06 * sin(w * 113.0);
  vec3 pc = mix(u_pal[2], u_pal[1], smoothstep(0.1, 0.9, belt));
  pc = mix(pc, u_pal[2], smoothstep(0.75, 0.95, abs(lat)) * 0.5);
  float lit = dot(Pn, S);
  float dif = smoothstep(-0.05, 0.7, lit);
  // the rings' shadow on the planet
  float tS = -dot(Pn, N) / dot(S, N);
  float fp = 1.2 * edgePx() / R / 0.45;
  float rsh = tS > 0.0 ? ringDensity(length(Pn + S * tS), rk, fp * 2.0) : 0.0;
  vec3 planet = lab2lin(pc) * (dif * (1.0 - 0.75 * rsh) + 0.015);
  float limb = pow(1.0 - zs, 3.0);
  planet += lab2lin(u_pal[5]) * limb * smoothstep(-0.1, 0.5, lit) * 0.5;
  planet *= 0.75 + 0.25 * zs;
  col = mix(col, planet, inP);
  // the haze of light round the lit limb, outside the disc
  float rim = exp(-max(sqrt(rr) - 1.0, 0.0) * 40.0) * (1.0 - inP) * smoothstep(-0.2, 0.6, dot(normalize(vec3(d, 0.0)), S));
  col += lab2lin(u_pal[5]) * rim * 0.35;
  // the rings: in front of the planet, or anywhere off its disc
  float vis = (rr > 1.0 || zr > zs) ? 1.0 : 0.0;
  float dens = ringDensity(r, rk, fp) * vis;
  // spokes drifting round, and the planet's shadow across the rings
  float ang = atan(dot(X, e2), dot(X, e1));
  float spokes = 1.0 - 0.18 * smoothstep(0.3, 0.9, gnoise(vec3(1.2 * cos(ang - a), 1.2 * sin(ang - a), r * 3.0)));
  float b = dot(X, S);
  float disc = b * b - (dot(X, X) - 1.0);
  float shadow = (b < 0.0 && disc > 0.0) ? 0.08 : 1.0;
  float facing = abs(dot(S, N));
  vec3 rc = mix(u_pal[4], u_pal[3], smoothstep(1.4, 1.8, r));
  vec3 ring = lab2lin(rc) * mix(0.8, 0.45 + 0.9 * facing + 0.5 * smoothstep(0.0, -0.3, S.z), u_dark) * shadow * spokes;
  col = mix(col, ring, dens * mix(0.9, 0.85, u_dark));
  return lin2srgb(shoulder(col));
}

// Billow: a cloud of ink unfurling in clear water, seen close, as in a macro photograph. Two inks rise together in one
// plume that curls over to the right; its surface is sculpted into rounded billows, each lit from the upper left so it
// reads as a solid, soft form, with fine tendrils fraying off its edges. In dark mode the ink glows against black
// water; in light mode it is dense pigment in a white tank, deepest in its folds.
// Palette: 0 the water, 1 the water's light, 2 first ink, 3 second ink, 4 the ink's lit edges, 5 the light.
// Options: x = motion (how far the ink unfurls), y = density (thin veils to dense plumes).
// Perspective: the water is far (tiltD -1), the plume near (tiltD 0.7).
const float T = 60.0;

// the plume's envelope: a soft tube along a curve rising from the lower left and curling over to the right
float envelope(vec2 q) {
  float s = sat((q.x + 1.6) / 3.0);
  float cy = -1.05 + 1.5 * s - 0.9 * s * s * s + 0.08 * sin(s * 7.0);
  float r = 0.25 + 0.5 * s * (1.0 - 0.4 * s);
  float d = (q.y - cy) / r;
  return exp(-d * d * 0.9) * smoothstep(0.0, 0.15, s) * smoothstep(1.0, 0.75, s);
}

float fbm2(vec3 p) { return 0.5 * gnoise(p) + 0.25 * gnoise(p * 2.03 + vec3(1.7, 9.2, 3.1)); }

// the ink density; the gradient samples use two octaves only (the third is too fine to change the shading)
float dens(vec2 q, vec2 w, float a, float m, float dk) {
  vec2 x = q + w;
  vec3 X = vec3(x * 2.6, 0.0) + vec3(orbit(a, 0.18 * m), 0.2 * m * sin(a + 1.0));
  float f = dk > 0.5 ? fbm3(X) : fbm2(X);
  float env = envelope(q + w * 0.8);
  return env + 0.95 * f * (0.3 + 0.7 * smoothstep(0.02, 0.45, env));
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.4, u_opt.x);
  float dn = mix(0.65, 1.35, u_opt.y);
  vec2 pw = p + tiltD(-1.0);
  vec3 water = lab2lin(mix(u_pal[0], u_pal[1], exp(-dot(pw - vec2(-0.7, 0.7), pw - vec2(-0.7, 0.7)) * 0.4)));
  vec2 q = p + tiltD(0.7);
  // the large flow that sculpts the billows, shared by the density and its gradient
  vec3 o = vec3(orbit(a, 0.22 * m), 0.25 * m * sin(a));
  vec2 w = 0.6 * vec2(fbm2(vec3(q * 0.9, 1.0) + o), fbm2(vec3(q * 0.9 + 5.3, 2.0) - o.yxz)) * 1.15;
  float e = 0.012;
  float d0 = dens(q, w, a, m, 1.0);
  float d1 = dens(q, w, a, m, 0.0);
  float dx = dens(q + vec2(e, 0.0), w, a, m, 0.0);
  float dy = dens(q + vec2(0.0, e), w, a, m, 0.0);
  vec2 g = vec2(dx - d1, dy - d1) / e;
  float thr = mix(0.75, 0.45, sat((dn - 0.65) / 0.7));
  float body = smoothstep(thr - 0.05, thr + 0.35, d0);
  // tendrils: thin filaments where the density crosses the threshold
  float rg = 1.0 - abs(gnoise(vec3((q + w) * 6.0, 3.0) + o * 0.5));
  float fil = pow(rg, 8.0) * smoothstep(thr - 0.3, thr - 0.02, d0) * (1.0 - body) * 0.35;
  // shading of the billows: a normal from the density gradient, lit from the upper left
  vec3 n = normalize(vec3(-g * 0.08, 1.0));
  vec3 L = normalize(vec3(-0.55, 0.6, 0.6));
  float lit = sat(dot(n, L) * 0.9 + 0.2);
  float rimL = pow(1.0 - n.z, 1.5);
  // which ink
  float mixI = smoothstep(-0.7, 0.7, w.x * 3.0 + 0.5 * (q.x - 0.2));
  vec3 ink = mix(lab2lin(u_pal[2]), lab2lin(u_pal[3]), mixI);
  vec3 edgeC = lab2lin(u_pal[4]);
  vec3 lightC = lab2lin(u_pal[5]);
  // dark: the ink glows, brightest on the lit sides of each billow and along its edges
  vec3 dk = water + ink * (body * (0.25 + 0.95 * lit) + fil * 0.8) + edgeC * (rimL * body * 0.35 + fil * 0.3) + lightC * pow(lit, 6.0) * body * 0.12;
  // light: pigment absorbing in clear water, deeper where the ink is thick and in the shaded folds
  vec3 ab = -log(max(ink, vec3(0.02))) * 0.6;
  vec3 lt = water * exp(-ab * (body * (1.1 + 0.9 * (1.0 - lit)) + fil * 0.5) * dn);
  lt += lightC * pow(lit, 8.0) * body * 0.06;
  return lin2srgb(shoulder(mix(lt, dk, u_dark)));
}

// Chroma: a field of pure colour that breathes. Five colours sit at five slowly circling points and flow into one
// another across the whole frame, mixed the way light mixes, through clean, rich in-between hues, never through grey
// (the mix keeps its chroma). Where two colours meet the field lifts a little, like a sheet of light, and one soft
// glow drifts across it; a fine still grain keeps the broad fields photographic.
// Palette: 0 the deep edge, 1 first colour, 2 second, 3 third, 4 fourth, 5 the light.
// Options: x = motion (how far the colours drift), y = edges (crisp meetings to melted ones).
// Perspective: the colours are far (tiltD -1), the light on them near (tiltD 0.8).
const float T = 36.0;

vec3 slot(float i) {
  vec3 c = u_pal[1];
  if (i > 0.5) c = u_pal[2];
  if (i > 1.5) c = u_pal[3];
  if (i > 2.5) c = u_pal[4];
  if (i > 3.5) c = mix(u_pal[1], u_pal[3], 0.5);
  return c;
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.3, 1.4, u_opt.x);
  float soft = u_opt.y;
  vec2 q = p + tiltD(-1.0);
  q += 0.12 * vec2(sin(q.y * 1.3 + a), sin(q.x * 1.1 - a + 1.0)) * m;
  float k = mix(2.6, 1.3, soft);
  float wsum = 0.0;
  vec2 ab = vec2(0.0);
  float L = 0.0;
  float C = 0.0;
  float w1 = 0.0;
  for (int i = 0; i < 5; i++) {
    float f = float(i);
    float an = f * 1.2566 + 0.4;
    vec2 c = vec2(1.15 * cos(an), 0.72 * sin(an)) * (0.75 + 0.15 * sin(f * 2.7));
    c += m * 0.22 * vec2(sin(a + f * 2.3), cos(a + f * 1.7)) + m * 0.06 * vec2(sin(2.0 * a - f), cos(3.0 * a + f));
    vec3 col = slot(f);
    float br = 0.5 + 0.5 * sin(a + f * 1.9);
    float d = length(q - c) / (0.8 + 0.18 * m * (br - 0.5));
    float w = 1.0 / pow(d * d + 0.02, k * 0.5);
    wsum += w;
    ab += col.yz * w;
    L += col.x * w;
    C += length(col.yz) * w;
    w1 += w * w;
  }
  vec2 mab = ab / wsum;
  vec3 lab = vec3(L / wsum, normalize(mab + 1e-5) * mix(length(mab), C / wsum, 0.9));
  // where two colours meet the field lifts a little, as a sheet of light would, softly
  float meet = sat((1.0 - w1 / (wsum * wsum)) / 0.75);
  vec2 qs = p + tiltD(0.8);
  float fold = smoothstep(0.2, 1.0, meet);
  lab.x += 0.035 * fold * (0.6 + 0.4 * sin(qs.x * 0.9 - qs.y * 0.7 + a));
  // the dark ground at the edges of the frame
  float vig = smoothstep(2.3, 0.5, length(p * vec2(0.7, 1.0)));
  lab = mix(u_pal[0], lab, mix(mix(0.8, 0.4, u_dark), 1.0, vig));
  // a fine, still grain, as in a photograph of light, so the large fields never band
  vec3 gh = hash33(vec3(floor(p / u_px), 7.0));
  lab.x += gh.x * 0.006;
  vec3 lin = lab2lin(lab);
  // one soft glow drifting across, where the light is strongest
  vec2 gp = qs - vec2(0.3 * sin(a), 0.2 * cos(a)) * m - vec2(-0.2, 0.25);
  lin += lab2lin(u_pal[5]) * exp(-dot(gp, gp) * 1.8) * mix(0.05, 0.1, u_dark);
  return lin2srgb(shoulder(lin));
}

// Totality: a total eclipse of the sun. The moon is a disc of perfect black; round it the corona spreads in pearly
// streamers, long along the sun's equator and short and brushed at its poles, finely striated, slowly shimmering. A thin
// rim of rose-red chromosphere hugs the limb with a few small prominences, and at one point on the edge the last bead of
// sunlight burns as a diamond. The sky is the deep blue of totality, with the glow of a far sunset all along the horizon.
// Palette: 0 the sky high, 1 the horizon glow, 2 the corona, 3 the chromosphere, 4 the far land, 5 the diamond.
// Options: x = motion (how much the corona shimmers), y = corona (short and faint to long and bright).
// Dynamic: u_sun moves the eclipse a little. Perspective: the sky and eclipse far (tiltD -1), the land near (tiltD 1).
const float T = 60.0;

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.3, 1.4, u_opt.x);
  float cr = mix(0.6, 1.4, u_opt.y);
  vec2 q = p + tiltD(-1.0);
  vec2 S = vec2(0.72, 0.36) + u_sun * vec2(0.4, 0.3);
  float R = 0.14;
  vec2 d = q - S;
  float r = length(d) / R;
  float ang = atan(d.y, d.x);
  // the sky: deep blue overhead, warming to the glow of a sunset all round the horizon
  // through a rose band between the glow and the blue, so the blend never greys
  vec3 mid = mix(u_pal[3], u_pal[0], 0.55);
  vec3 sky = mix(u_pal[1], mid, smoothstep(-0.8, -0.35, q.y));
  sky = mix(sky, u_pal[0], smoothstep(-0.45, 0.3, q.y));
  vec3 col = lab2lin(sky);
  col *= 1.0 + 0.25 * exp(-max(r - 1.0, 0.0) * 0.25);
  // the corona: brightness falling with distance, streamers brushed along it
  float eq = abs(cos(ang - 0.35));
  float reach = mix(0.55, 1.0, eq) * cr;
  float ra = ang + 0.05 * m * sin(a);
  vec2 dirv = vec2(cos(ra), sin(ra));
  float str = 0.55 + 0.45 * gnoise(vec3(dirv * 6.0, r * 0.15) + vec3(orbit(a, 0.35 * m), 0.0));
  str *= 0.7 + 0.3 * gnoise(vec3(dirv * 22.0, 1.0) + vec3(orbit(a, 0.2 * m), 0.3));
  float fine = 0.85 + 0.15 * sin(ang * 140.0 + 2.0 * gnoise(vec3(dirv * 3.0, 2.0)));
  float rr = max(r - 1.0, 0.0);
  float cor = (exp(-rr / (0.35 * reach)) * 0.9 + exp(-rr / (1.6 * reach * str)) * 0.45 * str) * fine * step(1.0, r + 0.02);
  vec3 corC = lab2lin(u_pal[2]);
  col += corC * cor * mix(0.75, 1.0, u_dark);
  // the chromosphere and its prominences, a thin rose rim at the limb
  float prom = pow(max(gnoise(vec3(dirv * 5.0, 7.0)), 0.0), 2.0) * 3.0;
  float chrom = exp(-pow((r - 1.0) / (0.012 + 0.03 * prom), 2.0)) * (0.5 + 0.5 * prom) * step(0.995, r);
  col += lab2lin(u_pal[3]) * chrom * 1.2;
  // the moon: black, its edge crisp
  float disc = smoothstep(1.0 + 1.3 * edgePx() / R, 1.0 - 1.3 * edgePx() / R, r);
  col = mix(col, lab2lin(setL(u_pal[0], 0.06)) * 0.6, disc);
  // the diamond: the last bead of sunlight, with a short starburst
  vec2 bd = S + R * vec2(cos(-0.75), sin(-0.75)) * 1.003;
  vec2 bq = q - bd;
  float bl = length(bq);
  float bead = 0.5 + 0.5 * sin(a);
  bead = bead * bead;
  float burst = exp(-bl * bl / 0.0004) * 1.6 + exp(-bl * 9.0) * 0.35;
  float rays = pow(abs(cos(atan(bq.y, bq.x) * 3.0)), 90.0) * exp(-bl * 10.0) * 0.45;
  col += lab2lin(u_pal[5]) * (burst * (1.0 - disc * 0.6) + rays * (1.0 - disc)) * mix(0.35, 1.0, bead);
  // a few stars and a bright planet in the dark of totality
  vec2 sg = q * 24.0;
  vec3 sh = hash33(vec3(floor(sg), 4.4)) * 0.5 + 0.5;
  float sd = length(fract(sg) - 0.5 - (sh.xy - 0.5) * 0.6) / 24.0;
  col += vec3(exp(-sd * sd / (0.7 * u_px * u_px)) * step(0.94, sh.z) * (sh.z - 0.94) * 9.0) * smoothstep(-0.2, 0.4, q.y) * sat((1.0 / 24.0) / u_px / 9.0 - 0.5) * u_dark * (1.0 - disc) * (1.0 - sat(cor));
  // the far land, dark against the horizon glow
  vec2 ql = p + tiltD(1.0);
  float land = -0.74 + 0.04 * sin(ql.x * 2.1 + 0.5) + 0.02 * sin(ql.x * 5.3) + 0.008 * sin(ql.x * 13.0 + 1.0);
  float lc = smoothstep(edgePx() * 1.3, -edgePx() * 1.3, ql.y - land);
  col = mix(col, lab2lin(u_pal[4]), lc);
  return lin2srgb(shoulder(col));
}

// Dunes: ridge after ridge of sand under a low sun. The far ridges fade into the haze, the near ones carry a lit face,
// a shadowed lee and fine wind ripples; as the sun swings a little, the light slides across the faces and the ripples
// creep.
// Palette: 0 zenith, 1 horizon, 2 far haze, 3 lit sand, 4 shadowed sand, 5 sun and crest light.
// Options: x = motion (how far the sun swings and the sand drifts), y = ripples.
const float T = 60.0;

float ridge(float x, float k) {
  return 0.55 * sin(x + 0.35 * sin(2.0 * x + k)) + 0.28 * sin(2.3 * x + 1.0 + k) + 0.1 * sin(4.7 * x + 2.0 * k);
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.5, u_opt.x);
  float rip = u_opt.y;
  float sunX = 0.65 + 0.22 * m * sin(a);
  vec2 sun = vec2(sunX, 0.28 + 0.04 * m * cos(a)) + u_sun;
  vec3 col = mix(u_pal[1], u_pal[0], smoothstep(-0.05, 1.0, p.y));
  float sg = length(p - sun);
  col = mix(col, u_pal[5], exp(-(sg * sg) / 0.03) * 0.75 + exp(-(sg * sg) / 0.35) * 0.25);
  for (int i = 0; i < 5; i++) {
    float f = float(i);
    float fk = f / 4.0;
    float sc = 1.0 + 0.45 * f;
    vec2 pt = p + tiltD(f * 0.5 - 1.0);
    float x = pt.x * sc + f * 2.3 + 0.06 * m * sin(a + f);
    float A = 0.07 + 0.05 * f;
    float y = 0.12 - 0.27 * f + A * ridge(x, f);
    float e = 0.003;
    float slope = A * (ridge(x + e, f) - ridge(x, f)) / e * sc;
    float dd = y - pt.y;
    float cov = smoothstep(-u_px * 1.2, u_px * 1.2, dd);
    float lit = smoothstep(-0.55, 0.45, -slope + 0.14 * m * sin(a + f * 0.7) + 0.05);
    float litE = mix(lit, 0.42 + 0.2 * lit, smoothstep(0.02, 0.3, dd));
    vec3 lc = mix(u_pal[4], u_pal[3], litE);
    lc = mix(u_pal[2], lc, 0.35 + 0.65 * fk);
    float crest = exp(-max(dd, 0.0) / (0.006 + 0.004 * f)) * lit;
    lc = mix(lc, u_pal[5], crest * (0.25 + 0.3 * fk));
    lc.x *= 1.0 - (0.1 + 0.08 * fk) * smoothstep(0.0, 0.45, dd);
    float rf = 34.0 + 10.0 * f;
    float rv = sin(dd * rf + pt.x * 3.0 + 0.6 * sin(pt.x * 2.1 + f) + a);
    float fade = sat(1.0 - rf * u_px * 3.0) * fk * fk * rip;
    lc.x += 0.03 * rv * fade * (0.5 + 0.5 * lit);
    col = mix(col, lc, cov);
  }
  return outLab(col);
}

// Tides: five broad waves of colour stacked across the window, each laid over the one behind with a soft shadow under
// its edge and a bright lip along its crest, rolling slowly, in the manner of the layered macOS wallpapers.
// Palette: 0 the farthest wave, 1 to 4 the waves toward the front, 5 crest light.
// Options: x = motion (how far the waves roll), y = depth (how strong the shadows are).
const float T = 45.0;

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.5, u_opt.x);
  float depth = mix(0.35, 1.4, u_opt.y);
  vec2 dir = normalize(vec2(0.36, 1.0));
  float u = dot(p, dir);
  float v = dot(p, vec2(dir.y, -dir.x));
  vec3 col = setL(u_pal[0], u_pal[0].x + 0.03 + 0.04 * (1.0 - u_dark));
  col = mix(col, u_pal[5], 0.12 * smoothstep(0.4, 1.4, u));
  for (int k = 0; k < 5; k++) {
    float f = float(k);
    vec2 pk = p + tiltD(f * 0.5 - 1.0);
    float uk = dot(pk, dir);
    float vk = dot(pk, vec2(dir.y, -dir.x));
    float e = 0.92 - 0.42 * f + (0.13 * sin(vk * 1.15 + f * 1.9 + a) + 0.05 * sin(vk * 2.5 - f + 2.0 * a)) * (0.55 + 0.45 * m)
            + 0.05 * m * lnoise(vec2(vk * 0.6, f * 3.0), a, 0.4);
    float dd = e - uk;
    float cov = smoothstep(-u_px, u_px, dd);
    float sh = exp(-max(-dd, 0.0) / 0.1) * (1.0 - cov) * 0.16 * depth;
    col.x -= sh * mix(0.6, 1.0, u_dark);
    vec3 lc = mix(u_pal[k], u_pal[k + 1], smoothstep(-1.6, 1.8, vk) * 0.55);
    float crest = exp(-max(dd, 0.0) / 0.018) * cov;
    lc.x += 0.07 * crest - 0.06 * smoothstep(0.0, 0.42, dd);
    lc = mix(lc, u_pal[5], crest * 0.18);
    col = mix(col, lc, cov);
  }
  return outLab(col);
}

// Afterglow: warm light leaking into the frame, as at the edge of a roll of film: wide soft flares that slide along the
// edges, swell and fade, with a hot core and a faint streak, over a quiet dark (or paper-pale) ground.
// Palette: 0 ground, 1 ground glow, 2 warm leak, 3 hot leak, 4 cool counter-light, 5 the hot core.
// Options: x = motion (how far the leaks travel), y = intensity.
const float T = 36.0;

vec2 leak(vec2 p, vec2 c, vec2 s, float b) {
  vec2 d = (p - c) / s;
  float q = dot(d, d);
  return vec2(exp(-q), exp(-q * 5.0)) * b;
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.5, u_opt.x);
  float k = mix(0.45, 1.35, u_opt.y);
  vec3 ground = mix(u_pal[0], u_pal[1], smoothstep(-1.4, 1.4, p.x * 0.5 - p.y * 0.7));
  vec3 lin = lab2lin(ground);
  vec2 l1 = leak(p, vec2(-1.75, 0.25 + 0.45 * m * sin(a)), vec2(0.75, 1.3), 0.6 + 0.4 * cos(a + 0.5));
  vec2 l2 = leak(p, vec2(1.0 + 0.35 * m * cos(a + 1.0), 1.25), vec2(1.2, 0.55), 0.5 + 0.4 * cos(a + 2.6));
  vec2 l3 = leak(p, vec2(0.3 + 0.55 * m * sin(a + 2.0), -1.3), vec2(1.1, 0.5), 0.45 + 0.35 * cos(a + 4.2));
  vec2 l4 = leak(p, vec2(1.75, -0.45 + 0.3 * m * cos(a + 3.0)), vec2(0.5, 0.9), 0.25 + 0.2 * cos(a + 1.3));
  float sx = -1.05 + 0.3 * m * sin(a + 0.7);
  float streak = gauss(p.x - sx - 0.12 * p.y, 0.09) * (0.15 + 0.1 * cos(a * 2.0)) * smoothstep(1.3, -0.2, abs(p.y - 0.1));
  vec3 cw = lab2lin(u_pal[2]);
  vec3 ch = lab2lin(u_pal[3]);
  vec3 cc = lab2lin(u_pal[4]);
  vec3 c5 = lab2lin(u_pal[5]);
  vec3 L = cw * (l1.x + l3.x * 0.8) + ch * (l1.x * l1.x + l2.x) * 0.8 + cc * l4.x + c5 * (l1.y + l2.y * 0.7 + l3.y * 0.5) + cw * streak;
  L *= k;
  // dark: light added to film, its faint tails falling off faster than its core, so the ground stays clean between leaks
  vec3 dk = 1.0 - (1.0 - lin) * exp(-(L * 0.9 + L * L * 1.1));
  float wsum = l1.x + l2.x + l3.x + l4.x + streak;
  // light mode: the leaks are coloured light laid over paper, so their colour shows as a wash, deepest at the edge of
  // the frame, with a lighter hot core: visibly colourful, still soft
  float al = 1.0 - exp(-wsum * k * 4.2);
  vec3 Lc = cw * (l1.x + l3.x * 0.8 + streak) + ch * (l1.x * l1.x + l2.x) * 0.8 + cc * l4.x;
  vec3 avg = Lc / max(l1.x * (1.8 + l1.x * 0.8) + l2.x * 0.8 + l3.x * 0.8 + l4.x + streak, 1e-3);
  vec3 lt = mix(lin, avg, al * 0.94);
  lt = mix(lt, c5, sat((l1.y + l2.y * 0.7 + l3.y * 0.5) * k * 0.55));
  return lin2srgb(shoulder(mix(lt, dk, u_dark)));
}

// Inkwell: two inks dropped into still water, billowing and unfurling into fine tendrils. In light mode the ink absorbs
// light as real ink does in clear water (Beer-Lambert): thin veils stay pale and dense plumes go deep. In dark mode the
// same clouds glow, lit from the side.
// Palette: 0 water, 1 water glow, 2 first ink, 3 second ink, 4 where the inks scatter light, 5 light through the water.
// Options: x = motion (how far the ink unfurls), y = density.
const float T = 60.0;

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.5, u_opt.x);
  float den = mix(0.55, 1.45, u_opt.y);
  vec3 o = vec3(orbit(a, 0.22 * m), 0.28 * m * sin(a + 1.0));
  vec2 w = vec2(fbm3(vec3(p * 0.8, 0.0) + o), fbm3(vec3(p * 0.8 + 3.3, 1.0) - o.yxz));
  vec2 q = p + 0.6 * w;
  float f = fbm4(vec3(q * 1.5, 2.0) + o * 0.6);
  float fil = 1.0 - abs(gnoise(vec3(q * 3.4, 4.0) + o * 0.5));
  fil = fil * fil * fil;
  float eA = sat(1.0 - length((q - vec2(-0.55, 0.3)) * vec2(0.8, 0.62)));
  float eB = sat(1.0 - length((q - vec2(0.75, -0.25)) * vec2(0.75, 0.7)));
  float dA = eA * eA * sat(f * 1.6 + 0.45) * (0.55 + 0.7 * fil) * den;
  float dB = eB * eB * sat(-f * 1.4 + 0.45) * (0.55 + 0.7 * fil) * den;
  vec3 water = lab2lin(mix(u_pal[0], u_pal[1], smoothstep(-1.4, 1.2, p.y + 0.3 * p.x)));
  vec3 iA = lab2lin(u_pal[2]);
  vec3 iB = lab2lin(u_pal[3]);
  vec3 abA = -log(max(iA, vec3(0.015)));
  vec3 abB = -log(max(iB, vec3(0.015)));
  vec3 lt = water * exp(-(abA * dA + abB * dB) * 1.5);
  lt += lab2lin(u_pal[5]) * 0.05 * smoothstep(0.8, -1.2, p.y - p.x * 0.4);
  vec3 glow = iA * dA + iB * dB;
  vec3 dk = water * exp(-(abA * dA + abB * dB) * 0.35) + glow * 0.9 + lab2lin(u_pal[4]) * pow(sat(dA + dB), 2.0) * fil * 0.25;
  return lin2srgb(shoulder(mix(lt, dk, u_dark)));
}

// Fluted: colour drifting behind a pane of reeded glass. Each reed is a small cylindrical lens that flips and squeezes
// the colour behind it, with a soft highlight down its face and a fine seam between reeds. The glass stays still; only
// the colour behind it moves.
// Palette: 0 base, 1 to 4 the drifting colours, 5 the glass highlight.
// Options: x = motion (how far the colours drift), y = reeds (fine to wide).
const float T = 48.0;

vec3 field(vec2 p, float a, float m) {
  vec3 acc = u_pal[0] * 0.25;
  float ws = 0.25;
  for (int i = 0; i < 4; i++) {
    float f = float(i);
    float n = mod(f, 2.0) < 0.5 ? 1.0 : -1.0;
    vec2 c = vec2(cos(f * 1.9 + 0.5) * 1.05, sin(f * 2.7 + 1.0) * 0.55) + orbit(n * a + f * 1.7, 0.45 * m);
    vec2 d = p - c;
    float w = exp(-dot(d, d) / 0.28);
    acc += u_pal[i + 1] * w;
    ws += w;
  }
  return acc / ws;
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.5, u_opt.x);
  float W = mix(0.065, 0.16, u_opt.y);
  float xr = p.x / W;
  float cell = floor(xr);
  float u = fract(xr) * 2.0 - 1.0;
  vec2 ps = vec2((cell + 0.5) * W - u * W * 0.85, p.y + 0.015 * u * u) + tiltD(-2.0);
  vec3 c = (field(ps, a, m) * 2.0 + field(ps + vec2(0.0, 0.05), a, m) + field(ps - vec2(0.0, 0.05), a, m)) * 0.25;
  float lum = 0.965 + 0.05 * (1.0 - u * u);
  float hl = gauss(u + 0.5, 0.18) * 0.1 + gauss(u - 0.72, 0.07) * 0.04;
  float sw = max(0.06, 1.6 * u_px / W);
  float seam = gauss(1.0 - abs(u), sw) * 0.05;
  vec3 col = vec3(c.x * lum - seam, c.yz * (1.0 + 0.08 * (1.0 - u * u)));
  col = mix(col, u_pal[5], hl);
  return outLab(col);
}

// Meridian: a slow-turning gradient. Five colours lie round a point below and to the right of the window and turn once
// a loop; the angle bends gently with distance, the centre melts into the colours' average and a soft light lifts it.
// Palette: 0 to 4 the five colours round the circle, 5 the light at the centre.
// Options: x = motion (how much the gradient sways as it turns), y = softness (how long the colour blends are).
const float T = 90.0;

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.3, 1.5, u_opt.x);
  float sp = mix(5.0, 1.6, u_opt.y);
  vec2 c = vec2(1.95, -1.35) + orbit(a, 0.08 * m);
  vec2 d = p - c;
  float r = length(d);
  float ang = 2.0 * atan(d.y, d.x) - a + 0.35 * m * sin(r * 1.3 - a) + 0.5 * sin(r * 0.9);
  // the stops are mixed in LCh: lightness and chroma by weight, hue as a weighted mean on the circle, so the blend
  // between two stops keeps its colour instead of passing through grey
  float Ls = 0.0;
  float Cs = 0.0;
  vec2 hv = vec2(0.0);
  float ws = 0.0;
  for (int i = 0; i < 5; i++) {
    float w = pow(0.5 + 0.5 * cos(ang - float(i) * 1.2566371), sp);
    vec3 s = u_pal[i];
    float C = length(s.yz);
    Ls += s.x * w;
    Cs += C * w;
    hv += s.yz / max(C, 1e-4) * w;
    ws += w;
  }
  vec3 col = vec3(Ls / ws, normalize(hv + 1e-5) * (Cs / ws));
  col = mix(col, u_pal[5], 0.14 * exp(-dot(p - vec2(-0.6, 0.6), p - vec2(-0.6, 0.6)) / 0.9));
  float sheen = gauss(dot(p, normalize(vec2(0.85, 0.5))) + 0.35 + 0.25 * sin(a + 1.0) * m, 0.5);
  col.x += 0.045 * sheen * (1.0 - 0.4 * u_dark);
  col.x *= 1.0 - 0.07 * smoothstep(1.0, 2.6, length(p - c * 0.5));
  return outLab(col);
}

// Nacre: mother of pearl. A slow field is cut into many fine layers like the inside of a shell. Each layer is a
// shade lighter or darker than its neighbour and carries its own faint hue, which turns with the direction the layer
// faces, so the surface shimmers as it drifts; a soft sheen lies across it.
// Palette: 0 the pearl, 1 to 4 the hues the layers take in turn, 5 the sheen.
// Options: x = motion (how far the layers drift), y = layers (few to many).
const float T = 56.0;

float fld(vec2 p, float a, float m) {
  vec2 q = p + 0.25 * vec2(gnoise(vec3(p * 0.4, 3.0) + vec3(orbit(a, 0.15 * m), 0.0)), 0.0);
  return 0.38 * fbm3(vec3(q * 0.55, 0.0) + vec3(orbit(a, 0.2 * m), 0.25 * m * sin(a + 1.0))) + 0.42 * q.y + 0.2 * q.x + 0.06 * dot(q, q);
}

// the layer colour: the pack's four hues blended round the circle in LCh (lightness and chroma by weight, hue as a
// weighted mean of directions), so two opposite hues never cancel into grey
vec3 hues(float ph) {
  float L = 0.0;
  float C = 0.0;
  vec2 hv = vec2(0.0);
  float ws = 0.0;
  for (int i = 0; i < 4; i++) {
    float w = pow(0.5 + 0.5 * cos(ph - float(i) * 1.5707963), 3.0);
    vec3 s = u_pal[1 + i];
    float c = length(s.yz);
    L += s.x * w;
    C += c * w;
    hv += s.yz / max(c, 1e-4) * w;
    ws += w;
  }
  return vec3(L / ws, normalize(hv + 1e-5) * (C / ws));
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.5, u_opt.x);
  float N = mix(7.0, 20.0, u_opt.y);
  float e = 0.004;
  float f0 = fld(p, a, m);
  vec2 gv = vec2(fld(p + vec2(e, 0.0), a, m) - f0, fld(p + vec2(0.0, e), a, m) - f0) / e;
  float g = length(gv) + 1e-4;
  vec2 nd = gv / g;
  float x = f0 * N;
  float id = floor(x);
  float fr = x - id;
  float dLo = fr / (N * g);
  float dHi = (1.0 - fr) / (N * g);
  float view = dot(nd, vec2(cos(a), sin(a)));
  float ph = id * 0.7 + 2.2 * view + 0.8 * f0;
  vec3 c = hues(ph);
  vec3 cPrev = hues(ph - 0.7);
  vec3 cNext = hues(ph + 0.7);
  float step1 = 0.5 * (1.0 - smoothstep(0.0, u_px * 1.5, dLo));
  float step2 = 0.5 * (1.0 - smoothstep(0.0, u_px * 1.5, dHi));
  c = mix(c, cPrev, step1);
  c = mix(c, cNext, step2);
  // dark: the base keeps its own colour and the layers glow over it, brightest where they face the light; light: a pearl
  vec3 base = mix(u_pal[0], hueShift(u_pal[0], 0.6 * view), 0.5 * u_dark);
  vec3 col = mix(base, c, mix(0.55, 0.8, u_dark));
  float facing = sat(0.5 + 0.5 * dot(nd, normalize(vec2(-0.5, 0.85))));
  col.x += u_dark * (0.07 * facing - 0.03) + 0.018 * sin(id * 2.3) + 0.022 * exp(-dHi / 0.008) - 0.02 * exp(-dLo / 0.012);
  col.yz *= 1.0 + 0.25 * u_dark * facing;
  float sheen = gauss(dot(p, vec2(0.6, 0.8)) - 0.3 + 0.2 * sin(a), 0.55);
  col = mix(col, u_pal[5], sheen * 0.25);
  return outLab(col);
}

// Ribbon: two satin ribbons floating across the window, twisting slowly as they go. Where a ribbon turns edge-on it
// narrows to a line; its two faces have their own colours, a sheen runs along it, and each casts a soft shadow behind.
// Palette: 0 background top, 1 background low, 2 ribbon face, 3 face second colour, 4 the reverse face, 5 sheen.
// Options: x = motion (how far the ribbons sway and twist), y = width.
const float T = 40.0;

float yc(float x, float a, float m, float off, float ph) {
  return off + (0.2 * sin(x * 1.05 + ph + a) + 0.09 * sin(x * 0.55 - a + ph * 2.0)) * (0.7 + 0.3 * m);
}

vec4 rib(vec2 p, float a, float m, float off, float W, float ph) {
  float y0 = yc(p.x, a, m, off, ph);
  float tw = p.x * 1.15 + ph + 0.8 * m * sin(a + p.x * 0.45);
  float ct = cos(tw);
  float h = W * abs(ct) + 1e-3;
  float v = (p.y - y0) / h;
  float cov = 1.0 - smoothstep(1.0 - 1.5 * u_px / h, 1.0 + 1.5 * u_px / h, abs(v));
  float bend = tw + 0.45 * v * sign(ct);
  vec2 n = vec2(-sin(bend), cos(bend));
  n *= sign(n.y);
  vec2 L = normalize(vec2(0.55, 0.83));
  float dif = dot(n, L);
  float spec = pow(sat(dot(n, normalize(L + vec2(0.0, 1.0)))), 40.0);
  float front = step(0.0, ct);
  vec3 fc = mix(u_pal[2], u_pal[3], 0.5 + 0.5 * sin(p.x * 0.7 + ph));
  vec3 c = mix(u_pal[4], fc, front);
  c.x *= 0.55 + 0.5 * sat(dif);
  c = mix(c, u_pal[5], spec * 0.7);
  c.x -= 0.06 * smoothstep(0.6, 1.0, abs(v));
  return vec4(c, cov);
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.5, u_opt.x);
  float wk = mix(0.7, 1.35, u_opt.y);
  vec3 col = mix(u_pal[1], u_pal[0], smoothstep(-1.2, 1.1, p.y + 0.2 * p.x));
  vec2 p1 = p + tiltD(-0.5);
  vec2 p2 = p + tiltD(0.8);
  float sh1 = gauss(p1.y - yc(p1.x - 0.05, a, m, 0.38, 2.2) + 0.13, 0.2 * wk) * 0.1;
  col.x -= sh1 * mix(0.7, 1.0, u_dark);
  vec4 r1 = rib(p1, a, m, 0.38, 0.13 * wk, 2.2);
  col = mix(col, r1.xyz, r1.w);
  float sh2 = gauss(p2.y - yc(p2.x - 0.06, a, m, -0.18, 0.0) + 0.16, 0.26 * wk) * 0.14;
  col.x -= sh2 * mix(0.7, 1.0, u_dark);
  vec4 r2 = rib(p2, a, m, -0.18, 0.22 * wk, 0.0);
  col = mix(col, r2.xyz, r2.w);
  return outLab(col);
}

// Pleat: a sheet of heavy paper folded in a Miura pattern, the tessellation of zigzag pleats that folds flat in one
// movement. Every facet is a small flat parallelogram, so each turns to the lamp at its own angle: rows of light and
// shade that zig across the sheet. The sheet slowly gathers and relaxes, as if someone held its ends, so the facets
// tilt and the light runs over them; the creases catch a hairline of light and the paper keeps its fine tooth.
// Palette: 0 paper, 1 paper's second tint, 2 lamp light, 3 shade, 4 bounce light from the far side, 5 the fold light.
// Options: x = motion (how far the sheet gathers), y = pleats (wide to fine).
const float T = 64.0;

// a triangle wave with softly rounded corners, and its slope
vec2 tri(float x, float r) {
  float f = fract(x) - 0.5;
  float s = sqrt(f * f + r * r);
  return vec2(s * 2.0, 2.0 * f / s);
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.4, u_opt.x);
  float sc = mix(1.7, 3.2, u_opt.y);
  vec2 pp = p + tiltD(0.2);
  // the sheet bows away from us toward the top, so its pleats grow finer there
  float persp = 1.0 + 0.32 * (pp.y + 1.0);
  vec2 q = rot(vec2(pp.x * persp, pp.y + 0.12 * pp.y * pp.y), -0.18) * sc;
  // the gathering: the zigzag deepens and the facets steepen, then relax
  float g = 0.5 + 0.5 * sin(a);
  float k = 0.45 + 0.25 * m * g;
  float depth = (0.28 + 0.18 * m * g) / sc;
  float r = max(0.035, edgePx() * sc * 2.0);
  vec2 tx = tri(q.x * 0.5, r);
  float arg = q.y + k * tx.x;
  vec2 ty = tri(arg, r);
  // the height is depth * ty.x; its slopes, chained through the zigzag
  float dhy = depth * ty.y * sc;
  float dhx = depth * ty.y * k * tx.y * 0.5 * sc;
  vec2 gr = rot(vec2(dhx, dhy), 0.18);
  vec3 n = normalize(vec3(-gr * 1.25, 1.0));
  float la = 2.2 + 0.25 * m * sin(a + 0.8) - 0.6 * u_sun.x;
  vec3 L = normalize(vec3(cos(la), sin(la), 0.85));
  float dif = dot(n, L);
  vec3 L2 = normalize(vec3(-cos(la), -sin(la), 0.5));
  float bounce = sat(dot(n, L2));
  // the creases: ridges where the zigzag turns over, valleys where it turns under
  float fy = abs(fract(arg) - 0.5);
  float ridge = exp(-fy * fy / (0.0015 + r * r * 0.5));
  float valley = exp(-pow(0.5 - fy, 2.0) / (0.002 + r * r * 0.5));
  // the lamp: a soft pool from the upper left that drifts slowly
  vec2 lc = vec2(-0.5, 0.45) + u_sun + orbit(a, 0.18 * m);
  float pool = exp(-dot(p - lc, p - lc) / 2.8);
  vec3 paper = mix(u_pal[0], u_pal[1], smoothstep(-1.6, 1.6, p.x - 0.4 * p.y));
  vec3 col = mix(u_pal[3], paper, smoothstep(-0.35, 1.0, dif));
  col = mix(col, u_pal[2], smoothstep(0.75, 1.0, dif) * 0.55 * pool);
  col = mix(col, u_pal[4], bounce * 0.25 * (1.0 - smoothstep(0.2, 0.7, dif)));
  col.x *= 0.82 + 0.26 * pool;
  col.x -= 0.05 * valley * (0.4 + g);
  col = mix(col, u_pal[5], ridge * sat(dif) * 0.35 * (0.35 + 0.65 * pool));
  float tooth = gnoise(vec3(p * vec2(150.0, 80.0), 0.5)) + 0.5 * gnoise(vec3(p * 400.0, 2.0));
  col.x += 0.006 * tooth;
  return outLab(col);
}

// Isles: wooded islands on a still sea at first light, lying in ranks one behind another and drifting slowly past, the
// far ranks slower than the near, as from the deck of a boat. Mist pools at their feet, the low sun rims their crowns,
// and each is mirrored, softly broken by the swell, in the water below.
// Palette: 0 zenith, 1 the glow at the horizon, 2 the farthest islands, 3 the nearest islands, 4 deep water, 5 the sun.
// Options: x = motion (how much the mist and the water stir), y = mist (thin to thick).
const float T = 90.0;

// a rank of islands: periodic along the shore, so the rank drifts exactly one period per loop
float isle(float x, float a, float f) {
  float D = 3.6 + 2.4 * f;
  float u = TAU * x / D + a + f * 1.9;
  float g = 0.5 * sin(u) + 0.3 * sin(2.0 * u + 1.3 + f) + 0.18 * sin(3.0 * u + 0.4 + 2.0 * f) + 0.1 * sin(5.0 * u + 2.1 * f);
  float k = sat((g - 0.22) / 0.5);
  float dome = (0.06 + 0.05 * f) * sqrt(k) * (1.0 + 0.3 * sin(7.0 * u + f));
  // the crowns of the trees: fine bumps along the top, only where there is land
  float crown = (0.5 * sin(17.0 * u + f) + 0.3 * sin(31.0 * u + 2.0 * f) + 0.2 * sin(57.0 * u + 0.7)) * (0.007 + 0.004 * f);
  return dome + crown * sat(k * 5.0);
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.4, u_opt.x);
  float mist = mix(0.4, 1.4, u_opt.y);
  float yh = -0.3;
  vec2 sun = vec2(0.95, yh + 0.17) + u_sun + tiltD(-1.0);
  // the sky, and the sun just above the far islands
  float sg = length((p - sun) * vec2(1.0, 1.25));
  vec3 sky = mix(u_pal[1], u_pal[0], pow(smoothstep(yh - 0.05, 1.05, p.y), 0.7));
  sky = mix(sky, u_pal[5], sat(smoothstep(0.036, 0.03, length(p - sun)) + exp(-sg * sg / 0.012) * 0.5 + exp(-sg / 0.4) * 0.3));
  // the water: the sky mirrored, darkened, broken by a gentle swell that moves toward the shore
  float dz = max(yh - p.y, 0.0);
  float z = 1.0 / (dz + 0.04);
  vec2 wq = vec2(p.x * z * 0.35, z * 0.9);
  float sw = lnoise(wq * vec2(1.0, 1.0), a, 0.35 * m) * 0.6 + 0.4 * lnoise(wq * 2.3 + 5.0, 2.0 * a, 0.25 * m);
  float wob = sw * (0.012 + 0.045 * dz);
  vec2 rp = vec2(p.x + wob, 2.0 * yh - p.y);
  float rg = length((rp - sun) * vec2(1.0, 1.25));
  vec3 refl = mix(u_pal[1], u_pal[0], pow(smoothstep(yh - 0.05, 1.05, rp.y), 0.7));
  refl = mix(refl, u_pal[5], exp(-rg * rg / 0.03) * 0.6 + exp(-rg / 0.5) * 0.22);
  vec3 water = mix(refl, u_pal[4], 0.3 + 0.4 * smoothstep(0.0, 0.7, dz));
  float glint = exp(-pow((p.x + wob * 3.0 - sun.x) / (0.08 + 0.25 * dz), 2.0)) * smoothstep(0.85, 0.0, dz) * sat(0.6 + 0.8 * sw);
  // fine ripples catching the sky: horizontal streaks, finer toward the horizon
  float st = lnoise(vec2(p.x * z * 0.12, z * 7.0), a, 0.3 * m);
  water.x += 0.025 * st * smoothstep(0.0, 0.05, dz);
  water = mix(water, u_pal[5], glint * sat(0.25 + 0.9 * st) * 0.55);
  vec3 col = mix(water, sky, smoothstep(-u_px, u_px, p.y - yh));
  for (int i = 0; i < 4; i++) {
    float f = float(i);
    float fk = f / 3.0;
    float base = yh - 0.008 - 0.018 * f - 0.022 * f * f;
    // each rank is its own Perspective layer, the far ranks moving least
    vec2 pl = p + tiltD(-0.6 + 0.53 * f);
    float h = isle(pl.x, a, f);
    vec3 ic = mix(u_pal[2], u_pal[3], fk);
    ic = mix(ic, u_pal[1], 0.18 * (1.0 - fk));
    // the island itself, rimmed on its sun side
    float top = base + h;
    float cov = smoothstep(edgePx(), -edgePx(), pl.y - top) * step(base - u_px, pl.y) * step(0.004, h);
    float side = 0.4 + 0.6 * exp(-abs(pl.x - sun.x) * 1.4);
    float rim = exp(-max(top - pl.y, 0.0) / (0.006 + 0.002 * f)) * side * (1.0 - 0.5 * fk);
    vec3 lc = mix(ic, u_pal[5], rim * 0.35);
    lc.x += 0.03 * (1.0 - fk) * smoothstep(0.0, 0.12, pl.y - base);
    col = mix(col, lc, cov);
    // its reflection, broken by the swell
    float hr = isle(pl.x + wob, a, f);
    float rcov = smoothstep(-edgePx() * 2.0, edgePx() * 2.0, pl.y - (base - hr * 0.92)) * step(pl.y, base) * step(0.004, hr);
    vec3 rc = mix(ic, u_pal[4], 0.3);
    rc.x *= 0.92;
    col = mix(col, rc, rcov * 0.9);
    // the mist lying at its feet
    float my = pl.y - base;
    float mf = exp(-abs(my) / (0.025 + 0.03 * f)) * (0.45 + 0.3 * lnoise(vec2(p.x * 1.4 + f * 3.0, f), a, 0.4 * m)) * mist;
    col = mix(col, mix(u_pal[1], u_pal[5], 0.25), sat(mf * (0.55 - 0.08 * f)));
  }
  return outLab(col);
}

// Relief: a plaster relief of a few plain forms (discs raised and cut, an arch) on a wall, each
// panel washed in its own faint colour. A low light travels slowly round it, so the bevelled edges catch and lose the
// light and the shadows lengthen, swing and shorten, as across a gallery wall through an afternoon.
// Palette: 0 wall, 1 the large forms, 2 the raised disc, 3 the cuts, 4 shadow and the cool fill, 5 the warm light.
// Options: x = motion (how far the light travels), y = depth (shallow to deep relief).
const float T = 72.0;

float box(vec2 p, vec2 c, vec2 b, float r) {
  vec2 d = abs(p - c) - b + r;
  return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0) - r;
}
float edge(float sd, float w) { return smoothstep(w, -w, sd); }

// the relief's height, and in w which surface the point is on (0 wall, 1 the large forms, 2 the raised disc, 3 a cut)
vec2 relief(vec2 p, float dep) {
  float w = 0.022;
  float sA = length(p - vec2(1.18, 0.3)) - 0.9;
  float sB = length(p - vec2(0.62, -0.35)) - 0.42;
  vec2 ac = vec2(-1.02, -1.0);
  float sD = min(box(p, ac, vec2(0.34, 0.55), 0.0), length(p - ac - vec2(0.0, 0.55)) - 0.34);
  float sE = box(p, vec2(0.0, -1.02), vec2(3.0, 0.13), 0.0);
  float sF = length(p - vec2(-0.78, 0.6)) - 0.15;
  float eA = edge(sA, w);
  float eB = edge(sB, w);
  float eD = edge(sD, w);
  float eE = edge(sE, w);
  float eF = edge(sF, w);
  float h = 0.05 * eA + 0.045 * eB + 0.06 * eD + 0.025 * eE - 0.035 * eF;
  float id = max(eA, eD) + eB - eF;
  return vec2(h * dep, id);
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.3, u_opt.x);
  float dep = mix(0.55, 1.5, u_opt.y);
  float az = 2.25 + 0.75 * m * sin(a) + 0.12 * m * sin(2.0 * a + 0.5) - 0.9 * u_sun.x;
  float el = max(0.14, 0.3 + 0.07 * cos(a) + 0.5 * u_sun.y);
  vec2 ld = vec2(cos(az), sin(az));
  vec3 L = vec3(ld * cos(el), sin(el));
  vec2 r0 = relief(p, dep);
  float e = 0.004;
  float hx = relief(p + vec2(e, 0.0), dep).x - r0.x;
  float hy = relief(p + vec2(0.0, e), dep).x - r0.x;
  vec3 n = normalize(vec3(-hx / e, -hy / e, 1.0));
  float dif = dot(n, L);
  // the shadow: march toward the light and see whether the relief rises above the ray
  float sh = 1.0;
  float tl = tan(el);
  for (int i = 0; i < 12; i++) {
    float s = 0.01 + 0.026 * float(i);
    float hh = relief(p + ld * s, dep).x;
    sh = min(sh, sat(1.0 - (hh - r0.x - s * tl) / (0.006 + 0.16 * s)));
  }
  // the surfaces' colours: the wall and each panel faintly tinted
  float id = r0.y;
  vec3 alb = mix(u_pal[0], u_pal[1], sat(id));
  alb = mix(alb, u_pal[2], sat(id - 1.0));
  alb = mix(alb, u_pal[3], sat(-id));
  // a broad wash of the light from its side, so the wall is never flat
  float wash = sat(0.5 + 0.38 * dot(p, ld));
  float lit = sat(dif / sin(el)) * sh;
  vec3 col = mix(u_pal[4], alb, 0.45 + 0.55 * lit);
  col = mix(col, u_pal[5], sat(dif - sin(el)) * 0.75 * sh);
  col.x *= 0.84 + 0.24 * wash;
  col = mix(col, u_pal[5], 0.22 * wash * wash * lit);
  col = mix(col, u_pal[4], 0.18 * (1.0 - wash));
  // plaster: a faint fixed trowel texture
  float tex = gnoise(vec3(p * vec2(9.0, 5.0), 1.3)) * 0.6 + gnoise(vec3(p * 60.0, 2.0)) * 0.3 + gnoise(vec3(p * 220.0, 4.0)) * 0.25;
  col.x += 0.009 * tex;
  return outLab(col);
}

// Louver: late sun through a window's slatted blind, laid across a quiet wall and folding down onto the floor below.
// The bars of light lean with the sun; their edges soften the farther they fall from the blind and warm a little at the
// penumbra, as real sunlight does. The patch slides slowly as the sun moves and the slats tilt a touch.
// Palette: 0 wall, 1 wall's lower tone, 2 sunlight, 3 the warm penumbra, 4 floor, 5 the brightest light.
// Options: x = motion (how far the light slides), y = slats (wide to narrow).
const float T = 80.0;

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.3, u_opt.x);
  float P = mix(0.24, 0.12, u_opt.y);
  float yf = -0.68;
  float onFloor = smoothstep(yf + u_px, yf - u_px, p.y);
  // a point on the floor is lit by the ray that would have reached the wall above the fold
  float df = max(yf - p.y, 0.0);
  vec2 q = mix(p, vec2(p.x - df * 1.6, yf + df * 0.55), onFloor);
  // the patch of light from the blind, sliding along the sun's path
  vec2 c = vec2(0.45, 0.02) + vec2(-0.7 * u_sun.x, 0.6 * u_sun.y) + vec2(0.45, -0.18) * m * sin(a) + vec2(0.05, 0.04) * m * sin(2.0 * a + 0.7);
  float ang = -0.42 + 0.04 * m * sin(a + 1.2);
  vec2 r = rot(q - c, -ang);
  r.x += 0.22 * r.y;
  float soft = 0.018 + 0.05 * sat(0.5 + 0.35 * (q.x - q.y));
  float px = smoothstep(1.05 + soft * 5.0, 1.05 - soft * 5.0, abs(r.x));
  float py = smoothstep(0.6 + soft * 4.0, 0.6 - soft * 4.0, abs(r.y));
  float win = px * py;
  // the slats: bars of light across the patch, their duty breathing as the slats tilt
  float duty = 0.36 + 0.08 * sin(a + 0.4);
  float s = r.y / P;
  float f = abs(fract(s) - 0.5) * 2.0;
  float bar = smoothstep(duty - soft / P, duty + soft / P, f);
  float penum = exp(-pow((f - duty) / (soft / P + 0.02), 2.0));
  // the room
  vec3 wc = mix(u_pal[1], u_pal[0], smoothstep(-0.9, 1.0, p.y + 0.25 * p.x));
  vec3 fc = mix(u_pal[4], u_pal[1], smoothstep(-1.0, yf, p.y) * 0.4);
  vec3 base = mix(wc, fc, onFloor);
  base.x -= 0.03 * exp(-abs(p.y - yf) / 0.03);
  vec3 lin = lab2lin(base);
  float light = win * bar;
  lin += lab2lin(u_pal[2]) * light * mix(0.75, 0.5, u_dark) * (1.0 - 0.2 * onFloor);
  lin += lab2lin(u_pal[3]) * win * penum * 0.08;
  lin += lab2lin(u_pal[5]) * light * exp(-dot(r, r) / 0.5) * 0.12;
  // the light bounced off the floor warms the bottom of the wall a little
  lin += lab2lin(u_pal[2]) * 0.05 * exp(-max(p.y - yf, 0.0) / 0.25) * (1.0 - onFloor) * smoothstep(1.2, 0.0, abs(p.x - c.x + 0.4));
  lin *= 1.0 + 0.02 * gnoise(vec3(p * 160.0, 2.0));
  return lin2srgb(shoulder(lin));
}

// Kiln: very close to a tall vase turning slowly on a potter's wheel under a studio softbox. Its flambe glaze ran in
// the kiln: one colour streams down through another in long drips, pools deeper in a band where the wall turns, and is
// flecked with a few dark pinholes. The softbox lies in the glaze as one tall, soft highlight, rippled where the drips
// stand proud. The vase turns exactly once a loop, so the glaze passes under the light and comes round again.
// Palette: 0 the vase's shaded side, 1 the first glaze, 2 the second glaze, 3 the pooled glaze, 4 the flecks, 5 the
// softbox's light.
// Options: x = motion (how strongly the light swells; the turn is the loop), y = drips (few to many).
const float T = 90.0;

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.3, u_opt.x);
  float dr = mix(0.6, 1.6, u_opt.y);
  // the vase: a cylinder wider than the window, its surface point at angle th, turned by the loop
  float Rv = 1.95;
  float th = asin(clamp(p.x / Rv, -0.99, 0.99));
  float ang = th + a;
  float Rn = 1.6;
  vec3 cq = vec3(Rn * cos(ang), Rn * sin(ang), p.y * 0.42);
  // the drips: streams running down the wall, long in height and narrow around
  vec3 dq = vec3(cq.xy * 1.4 * dr, cq.z * 0.9);
  float run = fbm3(dq + vec3(0.0, 0.0, 0.3 * fbm3(dq * 1.7 + 3.0)));
  float streak = gnoise(vec3(cq.xy * 9.0 * dr, cq.z * 0.35 + 5.0)) * 0.6 + gnoise(vec3(cq.xy * 21.0 * dr, cq.z * 0.5 + 2.0)) * 0.4;
  float g2 = smoothstep(-0.3, 0.45, run * 0.8 + 0.35 * streak + 0.5 * (p.y - 0.1));
  // the band where the glaze pooled as it ran
  float pool = smoothstep(-0.45, -1.05, p.y + 0.12 * gnoise(vec3(cq.xy * 2.0, 1.0)) + 0.05 * streak);
  vec3 glaze = mix(u_pal[1], u_pal[2], g2);
  glaze = mix(glaze, u_pal[3], sat(pool * 0.7));
  // pinholes, fixed to the glaze
  float fl = smoothstep(0.78, 0.86, gnoise(vec3(cq.xy * 45.0, cq.z * 45.0)));
  glaze = mix(glaze, u_pal[4], fl * 0.4);
  // the light: the round of the vase, and the softbox's tall reflection, rippled by the drips' relief
  float lit = 0.5 + 0.5 * cos(th * 1.2 + 0.35 - u_sun.x * 0.5);
  vec3 col = mix(u_pal[0], glaze, sat(lit));
  float relief = 0.06 * (run + 0.4 * streak);
  float hx = th + relief * 3.5 + 0.32 - 0.6 * u_sun.x + 0.03 * sin(p.y * 2.0 + 0.5);
  float sb = exp(-pow(hx / (0.04 + 0.02 * smoothstep(1.0, -1.0, p.y)), 2.0)) * smoothstep(1.3, 0.1, abs(p.y - 0.2)) * (0.75 + 0.25 * smoothstep(-1.0, 0.8, p.y)) * (0.8 + 0.2 * m * sin(a * 2.0 + 0.5));
  float sb2 = exp(-pow((th - 0.95 + relief) / 0.22, 2.0)) * 0.18;
  // the dark of the studio reflected beside the light, which is what makes a glaze read as glass
  float dk = exp(-pow((hx - 0.2) / 0.12, 2.0));
  col.x -= 0.06 * dk;
  col = mix(col, u_pal[5], sat(sb * 0.7 + sb2));
  // the glaze's gloss: a faint sheen everywhere it faces the light
  col.x += 0.03 * cos(th * 2.0 + 0.5) + 0.02 * relief;
  return outLab(col);
}

// Summit: a snow mountain in the last light, long after the valley has gone into shadow. The faces turned to the
// set sun glow rose; the faces turned away hold a cold blue; ribs of dark rock show where it is too steep for snow.
// A plume of spindrift streams from the summit ridge in the high wind, and a lower ridge stands dark in front.
// Palette: 0 the high sky, 1 the sky low, 2 snow in shadow, 3 snow in the glow, 4 rock, 5 the brightest glow.
// Options: x = motion (how hard the wind blows the plume), y = glow (faint to strong).
const float T = 60.0;

// the main massif: its height above the base line, and in w its shading slope across the face
float massif(float x) {
  float r = 0.62 - 0.85 * abs(x - 0.25) + 0.05 * sin(x * 7.0 + 1.0) + 0.025 * sin(x * 17.0 + 0.4);
  r = max(r, 0.38 - 0.55 * abs(x + 0.75) + 0.03 * sin(x * 11.0));
  return r + 0.012 * sin(x * 41.0);
}

// the relief of the face: ridged noise, sharp along its crests, its gullies running down the slope
float face(vec2 q) {
  vec2 r = vec2(q.x * 3.2 + 0.4 * sin(q.y * 2.0), q.y * 1.3);
  float h = 0.0;
  float w = 0.5;
  for (int i = 0; i < 3; i++) {
    h += w * (1.0 - abs(gnoise(vec3(r, 1.7 + float(i)))));
    r = r * 2.1 + vec2(0.3, 1.1);
    w *= 0.45;
  }
  return h * 0.12;
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.4, u_opt.x);
  float gk = mix(0.5, 1.3, u_opt.y);
  // the sky
  vec2 pf = p + tiltD(-1.0);
  vec3 sky = mix(u_pal[1], u_pal[0], smoothstep(-0.4, 1.0, pf.y));
  vec3 col = sky;
  // the far range, faint in the blue
  float far = -0.22 + 0.12 * sin(pf.x * 2.3 + 1.0) + 0.05 * sin(pf.x * 5.7) + 0.02 * sin(pf.x * 13.0);
  col = mix(col, mix(u_pal[2], u_pal[1], 0.6), smoothstep(edgePx(), -edgePx(), pf.y - far));
  // the massif
  vec2 pm = p + tiltD(0.0);
  float base = -0.35;
  float top = base + massif(pm.x);
  float inM = smoothstep(edgePx(), -edgePx(), pm.y - top);
  // its face: a relief of sharp ribs and gullies (ridged noise) on the cone of the mountain, lit from the west
  float hgt = top - pm.y;
  float e = 0.006;
  float h0 = face(pm);
  float hx = face(pm + vec2(e, 0.0)) - h0;
  float hy = face(pm + vec2(0.0, e)) - h0;
  float cone = (pm.x < 0.25 + 0.02 * sin(pm.y * 9.0)) ? 1.0 : -1.0;
  vec3 n = normalize(vec3(-hx / e * 1.6 + 0.4 * cone, -hy / e * 1.2 + 0.2, 1.0));
  vec3 Ld = normalize(vec3(0.85 - 0.4 * u_sun.x, 0.15, 0.5));
  float lit = sat(dot(n, Ld));
  float glowH = smoothstep(-0.45, 0.05, pm.y) * (0.8 + 0.2 * sin(a + 0.6)) * gk;
  vec3 snow = mix(u_pal[2], u_pal[3], sat(smoothstep(0.25, 0.85, lit) * glowH));
  snow = mix(snow, u_pal[5], pow(sat(lit * glowH), 4.0) * smoothstep(0.5, 0.0, hgt) * 0.5);
  // rock where the face is too steep to hold snow: the sharp crests' flanks
  float steep = length(vec2(hx, hy)) / e;
  float rock = smoothstep(0.75, 1.25, steep) * smoothstep(0.02, 0.1, hgt);
  snow = mix(snow, mix(u_pal[4], u_pal[3], 0.3 * lit * glowH), rock * 0.8);
  col = mix(col, snow, inM);
  // the spindrift: a soft plume streaming right from the summit, its field travelling with the wind
  float D = 3.0;
  float R = D / TAU;
  vec2 sp = pm - vec2(0.27, base + 0.62);
  float ph = TAU * sp.x / D - a;
  float pl = fbm3(vec3(R * cos(ph), R * sin(ph), sp.y * 4.0) * 2.0);
  float plume = smoothstep(-0.1, 0.35, pl) * exp(-pow((sp.y - 0.06 * sp.x) / (0.03 + 0.12 * max(sp.x, 0.0)), 2.0)) * smoothstep(-0.02, 0.08, sp.x) * exp(-max(sp.x, 0.0) * 1.3);
  col = mix(col, mix(u_pal[3], u_pal[5], 0.4), sat(plume * 0.55 * m * gk));
  // valley mist at the mountain's foot
  float mist = exp(-pow((p.y + 0.42) / 0.16, 2.0)) * (0.7 + 0.3 * lnoise(vec2(p.x * 1.5, 0.0), a, 0.3 * m));
  col = mix(col, mix(u_pal[2], u_pal[1], 0.5), mist * 0.45);
  // the dark ridge in front
  vec2 pn = p + tiltD(1.0);
  float near = -0.62 + 0.14 * sin(pn.x * 1.7 + 2.2) + 0.05 * sin(pn.x * 4.3 + 0.5) + 0.015 * sin(pn.x * 19.0);
  vec3 nc = mix(u_pal[4], u_pal[2], 0.25);
  nc.x *= 0.8 + 0.12 * smoothstep(-1.0, near, pn.y);
  col = mix(col, nc, smoothstep(edgePx(), -edgePx(), pn.y - near));
  return outLab(col);
}

// Furrow: a dry garden seen from above: pale gravel raked into fine straight furrows that bend into rings round three
// stones, each stone with a collar of moss. The low sun moves across the garden, so the furrows catch the light on one
// flank and then the other, and the stones' long shadows swing slowly round them.
// Palette: 0 the gravel in shade, 1 the gravel, 2 the gravel in the sun, 3 the stones, 4 the moss, 5 the light's warmth.
// Options: x = motion (how far the sun moves), y = furrows (wide to fine).
const float T = 80.0;

// the stones: centre, radius
vec3 stone(float i) {
  return i < 0.5 ? vec3(-0.98, -0.5, 0.3) : (i < 1.5 ? vec3(1.12, 0.46, 0.17) : vec3(1.42, 0.2, 0.1));
}

// the garden's height: straight furrows, rings raked round each stone out to a border, and the stones themselves;
// y = how much of a stone is here
vec2 garden(vec2 p, float K) {
  float sv = p.y + 0.03 * sin(p.x * 0.8);
  float st = 0.0;
  float rim = 9.0;
  for (int i = 0; i < 3; i++) {
    vec3 c = stone(float(i));
    vec2 q = p - c.xy;
    float d = length(q);
    float an = atan(q.y, q.x);
    // the stone's outline is irregular, as a real stone's is
    float r = c.z * (1.0 + 0.12 * sin(an * 3.0 + c.x * 4.0) + 0.06 * sin(an * 5.0 + c.y * 3.0));
    float rz = c.z * 2.7;
    // inside the raked rings the furrows follow the stone; the rings stop at their own outermost furrow
    float inR = smoothstep(rz + 0.02, rz - 0.02, d);
    sv = mix(sv, d - r, inR);
    rim = min(rim, abs(d - rz));
    st = max(st, sat(1.0 - (d * d) / (r * r)));
  }
  float fur = 0.5 - 0.5 * cos(sv * K * TAU);
  float h = 0.012 * fur * (1.0 - smoothstep(0.0, 0.15, st)) + 0.13 * sqrt(st);
  return vec2(h, st);
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.3, u_opt.x);
  float K = mix(9.0, 17.0, u_opt.y);
  float az = 2.6 + 0.6 * m * sin(a + 0.9) + 0.12 * m * sin(2.0 * a) - 0.8 * u_sun.x;
  vec3 L = normalize(vec3(cos(az), sin(az), 0.55 + 0.6 * u_sun.y));
  vec2 g0 = garden(p, K);
  float e = 0.0025;
  float hx = garden(p + vec2(e, 0.0), K).x - g0.x;
  float hy = garden(p + vec2(0.0, e), K).x - g0.x;
  // the border where the rings meet the straight furrows is a step; keep its slope from spiking
  vec2 gg = vec2(hx, hy) / e;
  gg *= min(1.0, (0.35 + 2.5 * g0.y) / max(length(gg), 1e-4));
  vec3 n = normalize(vec3(-gg, 1.0));
  float dif = dot(n, L);
  // the stones' long shadows on the gravel
  float sh = 1.0;
  vec2 ld = normalize(L.xy);
  for (int i = 0; i < 3; i++) {
    vec3 c = stone(float(i));
    vec2 q = p - c.xy;
    float along = dot(q, ld);
    float across = abs(dot(q, vec2(-ld.y, ld.x)));
    float len = c.z * 2.2 / max(L.z, 0.2);
    float s = smoothstep(c.z * 1.05, c.z * 0.75, across + 0.15 * max(-along, 0.0)) * smoothstep(0.0, -c.z * 0.4, along) * smoothstep(-len, -len * 0.4, along);
    sh = min(sh, 1.0 - 0.6 * s);
  }
  float lit = sat(dif / max(L.z, 0.3)) * sh;
  vec3 gravel = mix(u_pal[0], u_pal[1], smoothstep(0.3, 0.9, lit));
  gravel = mix(gravel, u_pal[2], smoothstep(0.9, 1.5, lit) * 0.8);
  gravel.x += 0.025 * gnoise(vec3(p * 260.0, 1.0)) + 0.012 * gnoise(vec3(p * 60.0, 2.0));
  // the stones and their moss
  float st = g0.y;
  vec3 stc = u_pal[3];
  stc.x *= 0.55 + 0.9 * sat(dif);
  stc.x += 0.08 * pow(sat(dif), 6.0);
  stc.x += 0.04 * gnoise(vec3(p * 40.0, 4.0));
  // moss in patches on the stone's lower flanks, never a ring
  float mp = gnoise(vec3(p * 9.0, 6.0)) + 0.5 * gnoise(vec3(p * 23.0, 8.0));
  float moss = smoothstep(0.0, 0.2, st) * smoothstep(0.6, 0.2, st) * smoothstep(0.1, 0.45, mp);
  vec3 col = mix(gravel, stc, smoothstep(0.0, 0.06, st));
  col = mix(col, mix(u_pal[4], u_pal[2], 0.2 * sat(dif)), moss * 0.75);
  // the warmth of the low sun across the garden
  col = mix(col, u_pal[5], 0.16 * sat(dot(p, ld) * 0.4 + 0.5) * sh * sat(lit));
  return outLab(col);
}

// Lucent: the light that passes through cut glass onto a sunlit table. It falls as a broad band of coloured light; in
// it the glass gathers the sun into a few long, bright curves of caustic light, each edged with a little
// spectrum. The glass turns imperceptibly in the moving air, so the curves slide, fold and part.
// The caustic is computed, not drawn: a gently curved glass surface bends parallel light, and where the bent rays
// converge (where the map's Jacobian falls to zero) the light piles up; done once per colour channel at slightly
// different strengths, which is the dispersion.
// Palette: 0 table, 1 table's far tone, 2 the pool's warm colour, 3 the pool's cool colour, 4 shade, 5 caustic light.
// Options: x = motion (how far the curves travel), y = caustic (soft to sharp).
const float T = 60.0;

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.4, 1.3, u_opt.x);
  float foc = mix(0.0, 1.0, u_opt.y);
  // the light through the glass lies in a broad band across the table, its edges soft and wavering
  vec2 pc = vec2(0.35, 0.05) + u_sun * 0.6;
  vec2 d = rot(p - pc, -0.5) / vec2(2.4, 0.95);
  float rr = length(d);
  float pool = smoothstep(1.25, 0.45, rr + 0.08 * lnoise(p * 0.9, a, 0.25));
  float core = pool * (0.6 + 0.4 * smoothstep(0.9, 0.0, rr));
  // the glass surface: a few long waves, its curvature exact
  vec2 x = rot(p - pc, -0.38) * vec2(0.8, 1.15) + 0.05 * m * vec2(lnoise(p * 0.6, a, 0.3), lnoise(p * 0.6 + 3.0, a, 0.3));
  float hxx = 0.0;
  float hyy = 0.0;
  float hxy = 0.0;
  for (int i = 0; i < 4; i++) {
    float f = float(i);
    float an = f * 2.39996 + 0.9;
    float kk = 2.6 + 0.9 * f;
    vec2 k = vec2(cos(an), sin(an)) * kk;
    float sg = mod(f, 2.0) < 0.5 ? 1.0 : -1.0;
    float A = (0.62 - 0.08 * f) / (kk * kk) * (0.8 + 0.2 * m);
    float s = -A * sin(dot(k, x) + sg * a + f * 1.3 + 0.35 * m * sin(a + f));
    hxx += s * k.x * k.x;
    hyy += s * k.y * k.y;
    hxy += s * k.x * k.y;
  }
  float tr = hxx + hyy;
  float det = hxx * hyy - hxy * hxy;
  vec3 z = vec3(0.94, 1.0, 1.065) * 2.15;
  vec3 J = 1.0 + z * tr + z * z * det;
  float eps = mix(0.22, 0.05, foc);
  vec3 I = (1.0 + eps) / (abs(J) + eps);
  I = max(I - 1.0, vec3(0.0));
  // the table and the light
  vec3 table = mix(u_pal[0], u_pal[1], smoothstep(-1.2, 1.4, p.y + 0.2 * p.x));
  table = mix(table, u_pal[4], 0.35 * smoothstep(0.6, 1.9, length((p - vec2(-0.2, 0.0)) * vec2(0.6, 1.0))));
  vec3 lin = lab2lin(table);
  vec3 tint = lab2lin(mix(u_pal[2], u_pal[3], smoothstep(-0.9, 0.9, d.x - 0.6 * d.y)));
  lin = mix(lin, lin * mix(0.62, 0.5, u_dark), pool);
  lin = mix(lin, tint, core * mix(0.75, 0.6, u_dark));
  vec3 cl = mix(lab2lin(u_pal[5]), tint / max(dot(tint, vec3(0.33)), 1e-3) * 0.6, 0.35);
  lin += cl * I * core * mix(0.16, 0.12, u_dark);
  // a faint weave in the cloth
  lin *= 1.0 + 0.02 * gnoise(vec3(p * vec2(240.0, 240.0), 1.0));
  return lin2srgb(shoulder(lin));
}

// Rime: frost on a window pane on a winter morning, with the low sun coming up behind it. The frost has grown in from
// the frame in feathered fronds, thickest in the corners, leaving the middle of the pane clear; the light behind
// glows through the fronds and every crystal edge catches it. The frost breathes a little as the sun warms the glass,
// and the glow drifts as the sun climbs.
// Palette: 0 the sky behind high, 1 the sky behind low, 2 the sun's glow, 3 the frost, 4 the frost in the light,
// 5 the glints.
// Options: x = motion (how much the frost breathes and the glow drifts), y = frost (light to heavy).
const float T = 70.0;

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.3, u_opt.x);
  float fr = mix(0.7, 1.35, u_opt.y);
  // the world behind the glass, far out of focus
  vec2 gc = vec2(0.55, -0.25) + vec2(0.22, 0.12) * m * sin(a) + u_sun;
  float gg = length((p - gc) * vec2(0.8, 1.0));
  vec3 back = mix(u_pal[1], u_pal[0], smoothstep(-1.0, 1.0, p.y));
  back = mix(back, u_pal[2], exp(-gg * gg / 0.35) * 0.85 + exp(-gg / 0.8) * 0.2);
  vec3 lin = lab2lin(back);
  // how far in from the frame the frost has grown: thickest in the corners
  float ax = 1.6;
  vec2 ed = vec2(ax - abs(p.x), 1.0 - abs(p.y));
  float edge = min(ed.x * 0.8, ed.y * (0.75 + 0.35 * step(0.0, p.y))) - 0.22 * sat(1.0 - length(ed) * 0.8);
  float reach = (0.42 + 0.08 * m * sin(a + 1.0)) * fr;
  // the fronds: stems growing in from the frame, each feathered with side branches at sixty degrees
  vec2 gd = normalize(-p * vec2(0.35, 1.0) + vec2(0.0, 1e-3));
  vec2 gn = vec2(-gd.y, gd.x);
  vec2 q = p * 3.0;
  vec2 wq = q + 0.35 * vec2(gnoise(vec3(q * 0.5, 1.0)), gnoise(vec3(q * 0.5, 3.0)));
  vec2 sq = vec2(dot(wq, gd), dot(wq, gn));
  float stem = sat(1.0 - abs(gnoise(vec3(sq.x * 0.6, sq.y * 3.2, 5.0))));
  vec2 b1 = rot(sq, 1.05);
  vec2 b2 = rot(sq, -1.05);
  float br = max(sat(1.0 - abs(gnoise(vec3(b1.x * 1.2, b1.y * 9.0, 7.0)))), sat(1.0 - abs(gnoise(vec3(b2.x * 1.2, b2.y * 9.0, 8.0)))));
  float f3 = sat(1.0 - abs(gnoise(vec3(wq * 7.0, 2.0))));
  float fern = pow(stem, 10.0) * 0.8 + pow(br, 14.0) * 0.7 * smoothstep(0.3, 0.8, stem) + pow(f3, 14.0) * 0.08;
  float grow = smoothstep(reach + 0.1, reach - 0.3, edge + 0.22 * gnoise(vec3(p * 1.3, 4.0)) + 0.08 * gnoise(vec3(p * 4.0, 6.0)));
  float dens = sat(grow * (0.18 + 1.6 * fern) * 0.85);
  // frost lit from behind: it scatters the glow toward us, brighter where the glow is
  float glow = exp(-gg * gg / 0.6);
  vec3 fc = mix(lab2lin(u_pal[3]), lab2lin(u_pal[4]), sat(glow * 1.2));
  // in daylight the clear glass between the fronds reads a touch deeper, so the white frost stands out
  lin *= 1.0 - 0.14 * grow * (1.0 - dens) * (1.0 - u_dark);
  lin = mix(lin, fc, dens * mix(0.95, 0.85, u_dark));
  // glints on the crystal edges, turning with the light
  vec3 sh = hash33(vec3(floor(p * 140.0), 3.0));
  float gl = step(0.985, sh.x * 0.5 + 0.5) * grow * fern * (0.5 + 0.5 * sin(sh.y * TAU + a * 2.0));
  lin += lab2lin(u_pal[5]) * gl * (0.25 + 0.6 * glow);
  // the faint mist of breath on the clear glass
  lin = mix(lin, fc, 0.06 * (1.0 - grow));
  return lin2srgb(shoulder(lin));
}

// Terraces: flooded rice terraces seen from above at sunset. Each terrace is a still pool following the contour of the
// hill, and each pool holds its own piece of the evening sky, a little brighter or deeper than its neighbour; the thin
// green banks between them trace the hillside's curves. Cloud reflections drift slowly across the pools, and a breath of
// wind now and then dulls a pool's mirror. The clouds' field repeats along their path, so the loop is exact.
// Palette: 0 the sky's deepest, 1 the sky, 2 the sky's glow, 3 the banks, 4 the banks in the light, 5 the bright cloud.
// Options: x = motion (how fast the reflections drift), y = terraces (few to many).
const float T = 80.0;

float hill(vec2 p) {
  return 0.55 * p.y - 0.3 * p.x + 0.09 * dot(p, p) + 0.35 * fbm3(vec3(p * 0.7, 2.0)) + 0.12 * sin(p.x * 1.3 + 0.5);
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.3, u_opt.x);
  float N = mix(6.0, 11.0, u_opt.y);
  float h = hill(p);
  float e = 0.004;
  vec2 g = vec2(hill(p + vec2(e, 0.0)) - h, hill(p + vec2(0.0, e)) - h) / e;
  float gl = length(g) + 1e-4;
  float x = h * N;
  float id = floor(x);
  float fr = fract(x);
  // the bank: a thin line at the lower edge of each pool, wider where the hill is gentle
  float dist = fr / (N * gl);
  // the bank: an earthen bund along the lower edge of each pool, a little uneven in width as banks built by hand are
  float bw = 0.024 + 0.018 * gnoise(vec3(p * 4.0, id * 1.3)) + 0.006 * sin(id * 1.7);
  float u = dist / bw;
  float bank = smoothstep(1.0 + edgePx() / bw, 0.7, u);
  float bank2 = smoothstep(2.2, 1.0, u);
  // the sky reflected in the pool: the same sky everywhere, but each pool turned a little toward its own slope
  float D = 7.0;
  float R = D / TAU;
  vec2 rq = p + 0.22 * vec2(sin(id * 2.1), cos(id * 1.3));
  float ph = TAU * (rq.x + 0.4 * rq.y) / D + a;
  float cl = fbm3(vec3(R * cos(ph), R * sin(ph), rq.y * 0.9 - 0.4 * rq.x) * 1.3);
  float glow = smoothstep(-1.4, 1.2, -p.x * 0.6 + p.y * 0.5);
  vec3 sky = mix(u_pal[0], u_pal[1], glow);
  sky = mix(sky, u_pal[2], smoothstep(0.55, 1.0, glow) * 0.8);
  sky = mix(sky, u_pal[5], smoothstep(0.0, 0.35, cl) * 0.55);
  // each pool a touch brighter or deeper; wind dulls one now and then
  float pv = sin(id * 12.9898) * 0.5;
  sky.x += 0.07 * pv;
  sky.yz *= 1.0 + 0.15 * cos(id * 4.1);
  float wind = smoothstep(0.55, 0.95, sin(a * (1.0 + mod(id, 2.0)) + id * 2.7)) * 0.5;
  float ripple = gnoise(vec3(p * 60.0, id));
  sky = mix(sky, u_pal[1], wind * 0.25);
  sky.x += wind * 0.015 * ripple;
  // the banks: grass, lit along their top by the low sun
  vec2 nd = g / gl;
  float facing = sat(dot(nd, normalize(vec2(-0.7, 0.7))) * 0.8 + 0.4);
  // the bund's profile: a low rounded ridge of earth with grass on its crown; lit on the side that faces the low sun
  float prof = cos(3.14159 * sat(u));
  float side = (facing - 0.6) * 2.0;
  float grass = gnoise(vec3(p * vec2(70.0, 90.0), id)) * 0.6 + gnoise(vec3(p * 22.0, id + 3.0)) * 0.4;
  float crown = smoothstep(0.1, 0.5, u) * smoothstep(1.0, 0.55, u) * smoothstep(-0.3, 0.4, grass + gnoise(vec3(p * 4.0, id + 5.0)));
  vec3 bk = mix(u_pal[3], u_pal[4], crown * 0.8);
  bk.x *= 0.9 + 0.22 * prof * side + 0.08 * grass;
  vec3 col = mix(sky, bk, bank);
  // the water close under each bund holds its dark reflection, and the edge of the pool below takes the bund's colour
  col.x -= 0.035 * (bank2 - bank);
  float lip = smoothstep(0.018 + edgePx(), 0.0, (1.0 - fr) / (N * gl));
  col = mix(col, u_pal[3], 0.3 * lip);
  return outLab(col);
}

// Nocturne: a long exposure of the night sky above a dark ridge, the last of the twilight still low in the west. Every
// star has drawn an arc round the pole, the bright ones a little thicker and each with its own faint colour, from blue
// to pale gold. The whole sky of trails turns slowly round the pole, as the earth does, and comes back to itself once
// a loop: the trails are laid in rings whose pattern repeats six times round, and the sky turns one sixth of a turn.
// Palette: 0 the sky at the zenith, 1 the twilight low in the sky, 2 the twilight's glow, 3 blue stars, 4 gold stars,
// 5 the ridge.
// Options: x = motion (how fast the sky turns is the loop; this sets how much the twilight breathes), y = trails
// (short to long).
const float T = 90.0;

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.3, u_opt.x);
  float L = mix(0.35, 0.95, u_opt.y);
  vec2 pole = vec2(-1.15, 1.25) + tiltD(-1.0);
  // the sky
  vec3 sky = mix(u_pal[1], u_pal[0], smoothstep(-0.6, 1.0, p.y));
  float tw = exp(-pow((p.y + 0.55) / 0.45, 2.0)) * (0.55 + 0.45 * smoothstep(1.6, -0.8, p.x - u_sun.x));
  sky = mix(sky, u_pal[2], tw * (0.65 + 0.1 * m * sin(a)));
  vec3 lin = lab2lin(sky);
  // the trails, in the sky's rotating frame
  vec2 v = p + tiltD(-1.0) - pole;
  float r = length(v);
  float ph = atan(v.y, v.x) - a / 6.0;
  float dr = 0.032;
  float k = floor(r / dr);
  vec3 trails = vec3(0.0);
  for (int j = 0; j < 2; j++) {
    float kk = k + float(j);
    float rc = kk * dr;
    float S = 6.0 * max(1.0, floor(rc * 1.6));
    float sec = TAU / S;
    float si = floor(ph / sec);
    for (int i = 0; i < 3; i++) {
      float idx = si + float(i);
      float w = mod(idx, S / 6.0);
      vec3 h = hash33(vec3(kk, w, 3.0)) * 0.5 + 0.5;
      float on = step(0.45, h.z);
      float rs = rc + (h.y - 0.5) * dr * 0.8;
      // the arc runs back from the star's place through an angle set by the exposure, at most two sectors
      float end = (idx + 0.2 + 0.6 * h.x) * sec;
      float len = min(L * (0.75 + 0.25 * h.y) * 0.75, sec * 1.95);
      float dph = end - ph;
      float along = smoothstep(-0.002, 0.004, dph) * smoothstep(len, len * 0.85, dph);
      float br = pow((h.z - 0.45) / 0.55, 4.0);
      float wd = (0.0008 + 0.0018 * br) + edgePx() * 0.6;
      float d = abs(r - rs);
      float line = exp(-d * d / (wd * wd)) * along * on;
      vec3 sc = mix(lab2lin(u_pal[3]), lab2lin(u_pal[4]), h.x);
      trails += sc * line * (0.12 + 1.2 * br);
    }
  }
  // the trails fade toward the twilight, where the sky is too bright to hold them
  lin += trails * (1.0 - 0.8 * tw) * mix(0.55, 0.85, u_dark);
  // the ridge
  vec2 q = p + tiltD(1.0);
  float rid = -0.72 + 0.1 * sin(q.x * 1.3 + 0.4) + 0.05 * sin(q.x * 3.7 + 1.0) + 0.02 * sin(q.x * 9.0) + 0.008 * sin(q.x * 31.0);
  lin = mix(lin, lab2lin(u_pal[5]), smoothstep(edgePx(), -edgePx(), q.y - rid));
  return lin2srgb(shoulder(lin));
}

// Beacon: a lighthouse on a dark headland at dusk, its lamp turning in a sea haze. The two beams sweep round once a
// loop: each is a soft shaft of light laid across the haze, long and faint when it points away along the coast,
// shortening and brightening as it swings toward us, until for a moment the lamp flares. Banks of haze drift slowly
// through the beams over a calm, darkening sea.
// Palette: 0 the high sky, 1 the haze low in the sky, 2 the sea, 3 the beam's light, 4 the headland, 5 the lamp.
// Options: x = motion (how much the haze drifts), y = haze (clear to thick).
const float T = 40.0;

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.3, u_opt.x);
  float hz = mix(0.55, 1.4, u_opt.y);
  float yh = -0.28;
  vec2 lamp0 = vec2(1.0, -0.0);
  vec2 lamp = lamp0 - tiltD(0.6);
  // the sky and the sea
  vec3 sky = mix(u_pal[1], u_pal[0], smoothstep(yh, 1.1, p.y));
  float dz = max(yh - p.y, 0.0);
  vec3 sea = mix(u_pal[1], u_pal[2], smoothstep(0.0, 0.35, dz));
  sea.x += 0.015 * lnoise(vec2(p.x * 8.0, dz * 40.0 / (dz + 0.1)), a, 0.3 * m);
  vec3 col = mix(sea, sky, smoothstep(-edgePx(), edgePx(), p.y - yh));
  vec3 lin = lab2lin(col);
  // the haze, drifting in banks
  float hn = lnoise(p * vec2(0.9, 2.2) + vec2(0.0, 1.0), a, 0.35 * m) * 0.6 + lnoise(p * vec2(2.1, 4.0), a, 0.25 * m) * 0.4;
  float haze = sat((0.55 + 0.6 * hn) * exp(-abs(p.y - yh - 0.15) * 1.6)) * hz;
  // the beams: each turns round a vertical axis; on the screen it reaches out to one side, foreshortened as it turns
  vec3 bl = lab2lin(u_pal[3]);
  float glowSum = 0.0;
  for (int i = 0; i < 2; i++) {
    float th = a + float(i) * 3.14159265;
    float cx = cos(th);
    float tw = sin(th);
    vec2 d = p - lamp;
    float s = d.x * sign(cx);
    float reach = 0.9 + 2.6 * abs(cx);
    float along = s / reach;
    float wd = 0.012 + 0.07 * max(s, 0.0) + 0.05 * (1.0 - abs(cx));
    float off = d.y + 0.035 * s;
    float beam = exp(-off * off / (wd * wd)) * smoothstep(-0.01, 0.04, s) * exp(-max(along, 0.0) * 1.4);
    // brighter as it turns toward us, the way light scattered forward in haze is
    float fwd = 0.55 + 0.45 * sat(tw);
    // the two lamps of the lens are not matched: one beam is a little weaker
    float bi = 1.0 - 0.4 * float(i);
    // the beam lights the haze it passes through, so it carries the haze's own texture
    glowSum += beam * fwd * (0.45 + 0.9 * haze) * (0.75 + 0.5 * hn) * bi;
    // the flare when the beam points straight at us
    float fl = pow(sat(tw), 24.0);
    float r = length(d * vec2(0.6, 1.0));
    glowSum += fl * (exp(-r * r / 0.02) * 1.2 + exp(-r / 0.35) * 0.35) * bi;
  }
  // the haze round the lamp is always lit: a soft glow, and a faint band along the height of the beams
  vec2 dl = (p - lamp) * vec2(0.45, 1.0);
  float halo = exp(-length(dl) / 0.28) * 0.45 + exp(-dot(dl, dl) / 0.004) * 0.6;
  float band = exp(-pow((p.y - lamp.y + 0.01 * (p.x - lamp.x)) / 0.12, 2.0)) * exp(-abs(p.x - lamp.x) * 0.55) * 0.22;
  glowSum += (halo + band * (0.6 + 0.8 * hn)) * (0.5 + 0.7 * haze);
  // dark: light added to the night; light: the warm beam laid over a pale evening, so it keeps its colour
  vec3 lit = lin + bl * glowSum * 0.7;
  vec3 lay = mix(lin, bl, sat(glowSum * 0.85));
  lin = mix(lay, lit, u_dark);
  lin = mix(lin, lab2lin(mix(u_pal[1], u_pal[3], 0.2)), haze * 0.25);
  // the reflection of the lamp's glow on the sea
  float refl = exp(-pow((p.x - lamp.x) / (0.05 + 0.4 * dz), 2.0)) * smoothstep(0.6, 0.0, dz) * step(p.y, yh);
  lin += bl * refl * 0.08 * (0.5 + 0.5 * lnoise(vec2(p.x * 20.0, dz * 60.0), a * 2.0, 0.5));
  // the headland and the tower
  vec2 q = p + tiltD(0.6);
  float land = 0.0;
  {
    float x0 = q.x;
    float top = yh + 0.2 * smoothstep(0.55, 1.05, x0) + 0.012 * sin(x0 * 11.0 + 1.0) + 0.006 * sin(x0 * 29.0);
    float hl = -1.4 + (top + 1.4) * smoothstep(0.36, 0.6, x0);
    float x1 = x0 + 0.004;
    float top1 = yh + 0.2 * smoothstep(0.55, 1.05, x1) + 0.012 * sin(x1 * 11.0 + 1.0) + 0.006 * sin(x1 * 29.0);
    float hl1 = -1.4 + (top1 + 1.4) * smoothstep(0.36, 0.6, x1);
    float sl = (hl1 - hl) / 0.004;
    land = smoothstep(edgePx(), -edgePx(), (q.y - hl) / sqrt(1.0 + sl * sl));
  }
  float hl = yh + 0.2 * smoothstep(0.55, 1.05, q.x);
  float tw2 = 0.02 + 0.012 * (lamp0.y - q.y) / 0.2;
  float tower = smoothstep(tw2 + edgePx(), tw2 - edgePx(), abs(q.x - lamp0.x)) * smoothstep(lamp0.y - 0.01, lamp0.y - 0.02, q.y) * step(hl - 0.03, q.y);
  vec3 lc = lab2lin(u_pal[4]);
  lin = mix(lin, lc, sat(max(land, tower)));
  // the lamp itself
  float lr = length(p - lamp);
  lin += lab2lin(u_pal[5]) * (smoothstep(0.016, 0.008, lr) + exp(-lr * lr / 0.003) * 0.4);
  return lin2srgb(shoulder(lin));
}

// Reeds: the edge of a lake at sunrise, seen through a stand of tall reeds. Mist lies on the water and the low sun glows
// through it; the reeds stand dark against the light along the bottom of the frame, nearer ones taller and softer as a
// lens sees them, each with its feathery plume, and they sway in the morning air at their own pace.
// Palette: 0 the high sky, 1 the mist, 2 the sun's glow, 3 the water, 4 the reeds, 5 the sun.
// Options: x = motion (how far the reeds sway), y = reeds (sparse to dense).
const float T = 36.0;

// one rank of reeds: x positions on a grid, each reed a thin stem bending from its root, topped with a plume
vec2 rank(vec2 p, float a, float m, float f, float den, float soft) {
  float sp = 0.07 + 0.05 * f;
  float cell = floor(p.x / sp);
  float cov = 0.0;
  float plume = 0.0;
  for (int i = 0; i < 5; i++) {
    float c = cell + float(i) - 2.0;
    vec3 h = hash33(vec3(c, f, 2.0)) * 0.5 + 0.5;
    float x0 = (c + 0.2 + 0.6 * h.x) * sp;
    // the stand thins toward the middle, where the light comes through
    float side = 0.25 + 0.75 * smoothstep(0.15, 1.1, abs(x0 + 0.35));
    float on = step(1.0 - den * side, h.z);
    float base = -1.05;
    float ht = (0.35 + 0.4 * h.y) * (0.7 + 0.35 * f) * (0.55 + 0.45 * side);
    float u = sat((p.y - base) / ht);
    float n = mod(c, 2.0) < 0.5 ? 1.0 : -1.0;
    float bend = (0.04 + 0.05 * h.x) * m * sin(a * (1.0 + floor(h.y * 2.0)) * n + h.z * TAU) + 0.03 * (h.y - 0.5);
    float x = x0 + bend * u * u + 0.02 * u;
    float w = (0.0011 + 0.0008 * f) * (1.0 - 0.55 * u) + soft * 0.3;
    float stem = smoothstep(w + edgePx(), w, abs(p.x - x)) * step(p.y, base + ht);
    // the plume: a feathery tassel that droops to one side from the top of the stem, its fibres catching the light
    float dir = h.x < 0.5 ? -1.0 : 1.0;
    vec2 tq = p - vec2(x0 + bend + 0.02, base + ht);
    float s = sat(-tq.y / (0.2 + 0.07 * f) + 0.12);
    float cx = dir * (0.05 + 0.03 * f) * s * s + bend * 0.3 * s;
    float wd = (0.01 + 0.03 * sin(3.14159 * sat(s))) * (1.0 + 0.5 * f) + soft * 3.0;
    float across = (tq.x - cx) / wd;
    float fib = 0.55 + 0.45 * gnoise(vec3(across * 2.5, tq.y * 60.0, c + f * 7.0));
    float plc = exp(-across * across) * smoothstep(1.0, 0.75, s) * smoothstep(0.0, 0.08, s) * fib;
    cov = max(cov, stem * on);
    plume = max(plume, plc * on);
  }
  return vec2(cov, plume);
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.3, u_opt.x);
  float den = mix(0.35, 0.8, u_opt.y);
  float yh = -0.32;
  vec2 sun = vec2(-0.55, yh + 0.2) + u_sun + tiltD(-1.0);
  // the sky, the mist and the sun
  float sd = length((p - sun) * vec2(0.8, 1.0));
  vec3 sky = mix(u_pal[1], u_pal[0], smoothstep(yh, 1.1, p.y));
  sky = mix(sky, u_pal[2], exp(-sd / 0.55) * 0.75);
  sky = mix(sky, u_pal[5], smoothstep(0.07, 0.05, length(p - sun)) * 0.9 + exp(-sd * sd / 0.02) * 0.5);
  // the water, still, holding the glow and mist
  float dz = max(yh - p.y, 0.0);
  vec3 water = mix(u_pal[1], u_pal[3], smoothstep(0.0, 0.5, dz));
  water = mix(water, u_pal[2], exp(-pow((p.x - sun.x) / (0.15 + 0.6 * dz), 2.0)) * 0.55 * exp(-dz * 2.0));
  water.x += 0.012 * lnoise(vec2(p.x * 3.0, dz * 30.0), a, 0.3 * m);
  vec3 col = mix(water, sky, smoothstep(-edgePx(), edgePx(), p.y - yh));
  // the mist on the water
  float mist = exp(-pow((p.y - yh - 0.02) / 0.12, 2.0)) * (0.7 + 0.3 * lnoise(vec2(p.x * 1.4, 0.0), a, 0.3 * m));
  col = mix(col, mix(u_pal[1], u_pal[2], 0.4 * exp(-abs(p.x - sun.x))), mist * 0.6);
  // the reeds: three ranks, the far ones fainter in the mist, the near ones taller and out of focus
  vec3 rc = u_pal[4];
  for (int k = 0; k < 3; k++) {
    float f = float(k);
    vec2 q = p + tiltD(-0.3 + 0.6 * f);
    vec2 r = rank(q, a, m, f, den * (0.6 + 0.2 * f), 0.0015 * f * f);
    vec3 c = mix(rc, u_pal[1], (0.55 - 0.25 * f) * (1.0 - f / 3.0));
    // the plumes are thin enough to glow where the sun is behind them
    vec3 pc = mix(c, u_pal[2], 0.2 + 0.5 * exp(-length(q - sun) * 1.1));
    col = mix(col, pc, sat(r.y * 1.3) * (0.8 - 0.1 * f));
    col = mix(col, c, r.x);
  }
  return outLab(col);
}

// Squall: a rain squall passing far out over the sea at sunset. Under a long, dark shelf of cloud the rain hangs in grey
// veils that trail and lean with the wind; the low sun behind them turns their edges gold and lays a bright band along
// the horizon beneath, and the calm sea in front mirrors it all. The veils drift slowly along the horizon; their field
// repeats along it, so they travel exactly one period a loop.
// Palette: 0 the high sky, 1 the cloud's underside, 2 the rain, 3 the glow at the horizon, 4 the sea, 5 the sun.
// Options: x = motion (how much the veils sway), y = rain (light to heavy).
const float T = 75.0;

float veils(vec2 p, float a, float m) {
  float D = 6.0;
  float R = D / TAU;
  float x = p.x + 0.35 * (p.y + 0.2);
  float ph = TAU * x / D + a;
  vec3 q = vec3(R * cos(ph), R * sin(ph), p.y * 0.35);
  float v = gnoise(q * vec3(1.3, 1.3, 0.8) + vec3(0.0, 0.0, 0.2 * m * sin(a))) * 0.7 + gnoise(q * vec3(3.2, 3.2, 1.0) + 3.0) * 0.3;
  float streak = gnoise(vec3(R * cos(ph) * 30.0, R * sin(ph) * 30.0, p.y * 1.5)) * 0.5 + 0.5;
  return smoothstep(0.02, 0.35, v) * (0.7 + 0.3 * streak);
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.3, u_opt.x);
  float rn = mix(0.5, 1.3, u_opt.y);
  float yh = -0.3;
  vec2 sun = vec2(0.55, yh + 0.12) + u_sun + tiltD(-1.0);
  vec2 ps = p + tiltD(-0.5);
  // the sky: dark cloud shelf above, a clear band of glow beneath it
  float sb = 0.14 + 0.07 * gnoise(vec3(ps.x * 1.1, 0.0, 1.0)) + 0.03 * gnoise(vec3(ps.x * 4.0, 0.0, 2.0));
  float shelf = smoothstep(sb - 0.03, sb + 0.12, ps.y);
  vec3 sky = mix(u_pal[3], u_pal[0], smoothstep(yh, 0.4, ps.y));
  // the shelf: heavy cloud, darker as it rises, its body rolled and lumpy, drifting with the rain
  float D2 = 9.0;
  float ph2 = TAU * ps.x / D2 + a;
  vec3 cq = vec3(D2 / TAU * cos(ph2), D2 / TAU * sin(ph2), ps.y * 1.8) * 1.4;
  float body = fbm4(cq + vec3(0.0, 0.0, 2.0));
  vec3 cloud = setL(u_pal[1], u_pal[1].x * (1.15 - 0.35 * smoothstep(sb, 1.1, ps.y) + 0.35 * body));
  cloud = mix(cloud, u_pal[0], 0.25 * smoothstep(0.5, 1.2, ps.y));
  sky = mix(sky, cloud, shelf);
  float sd = length((p - sun) * vec2(0.7, 1.0));
  sky = mix(sky, u_pal[5], (smoothstep(0.055, 0.045, length(p - sun)) * 0.9 + exp(-sd * sd / 0.02) * 0.5 + exp(-sd / 0.5) * 0.25) * (1.0 - shelf * 0.8));
  // the cloud's underside: soft mammatus-like swellings lit from below by the sun
  float cu = gnoise(vec3(ps * vec2(2.2, 4.0), 3.0));
  sky = mix(sky, u_pal[3], shelf * smoothstep(0.55, 0.15, ps.y) * sat(cu * 0.8 + 0.3) * 0.35 * exp(-abs(ps.x - sun.x) * 0.8));
  // the rain veils, hanging from the shelf to the sea
  float vh = smoothstep(yh - 0.01, yh + 0.08, ps.y) * smoothstep(sb + 0.1, sb - 0.05, ps.y);
  float v = veils(ps, a, m) * vh * rn;
  vec3 rc = mix(u_pal[2], u_pal[3], exp(-abs(ps.x - sun.x) * 1.4) * 0.6);
  sky = mix(sky, rc, sat(v * 0.8));
  // the shelf's lower edge catches the sun
  sky = mix(sky, u_pal[3], exp(-pow((ps.y - sb) / 0.04, 2.0)) * 0.45 * exp(-abs(ps.x - sun.x) * 0.9));
  // the sea mirrors the sky
  float dz = max(yh - p.y, 0.0);
  vec2 rp = vec2(p.x + 0.01 * lnoise(vec2(p.x * 3.0, dz * 40.0), a, 0.4 * m), 2.0 * yh - p.y);
  vec2 rs = rp + tiltD(-0.5);
  float rsb = 0.14 + 0.07 * gnoise(vec3(rs.x * 1.1, 0.0, 1.0)) + 0.03 * gnoise(vec3(rs.x * 4.0, 0.0, 2.0));
  float rshelf = smoothstep(rsb - 0.03, rsb + 0.12, rs.y);
  vec3 refl = mix(u_pal[3], u_pal[0], smoothstep(yh, 0.4, rs.y));
  refl = mix(refl, u_pal[1], rshelf);
  float rsd = length((rp - sun) * vec2(0.7, 1.0));
  refl = mix(refl, u_pal[5], exp(-rsd * rsd / 0.03) * 0.7);
  float rv = veils(rs, a, m) * smoothstep(yh - 0.01, yh + 0.08, rs.y) * smoothstep(rsb + 0.1, rsb - 0.05, rs.y) * rn;
  refl = mix(refl, rc, sat(rv * 0.6));
  vec3 sea = mix(refl, u_pal[4], 0.15 + 0.55 * smoothstep(0.0, 0.7, dz));
  vec3 col = mix(sea, sky, smoothstep(-edgePx(), edgePx(), p.y - yh));
  return outLab(col);
}

// Glowtide: a beach at dusk when the water is full of bioluminescent plankton, seen from low on the sand. Each wave that
// breaks lights up from within along its crest, a soft blue-green that glows through the water rather than on it; the
// whitewater behind it glows in a lace of foam, and the wave runs up the wet sand as a thin luminous sheet and slides
// back. The wet sand is a rough mirror: it holds the evening sky and a smeared reflection of every glowing crest.
// Three waves of a set come in one after another and the set repeats exactly.
// Palette: 0 the high sky, 1 the dusk at the horizon, 2 the sea, 3 the glow, 4 the sand, 5 the glow's bright core.
// Options: x = motion (how far the waves run up), y = glow (faint to bright).
const float T = 30.0;

vec3 skyAt(float h) {
  return mix(u_pal[1], u_pal[0], pow(sat(h / 0.85), 0.55));
}

// the glow at a point (X across, Z away) on the water; det = 1 adds the foam's lace
float glowAt(float X, float Z, float a, float m, float wl, float det) {
  float g = 0.0;
  for (int i = 0; i < 3; i++) {
    float f = float(i);
    float ph = fract(a / TAU + f / 3.0);
    float env = smoothstep(0.04, 0.2, ph) * (1.0 - smoothstep(0.78, 1.0, ph));
    // the front: comes in from far out, slows as it reaches the beach, runs up the sand and slides back
    float wob = (0.08 + 0.04 * Z) * gnoise(vec3(X * 0.6, f * 4.0, 1.0)) + 0.04 * sin(X * 1.6 + f * 2.0);
    float zin = mix(6.0, wl, smoothstep(0.0, 0.62, ph));
    float run = (0.16 + 0.16 * m) * sin(3.14159265 * sat((ph - 0.5) / 0.5));
    float zf = zin - run + wob;
    float dZ = Z - zf;
    float w = 0.03 + 0.03 * Z;
    // the crest breaks along its length a stretch at a time
    float bn = gnoise(vec3(X * 0.7, f * 3.0, ph * 2.2)) * 0.7 + 0.3 * gnoise(vec3(X * 2.3, f * 5.0, ph * 3.0));
    float brk = smoothstep(-0.35, 0.25, bn + 1.2 * ph - 0.55);
    float crest = exp(-dZ * dZ / (w * w)) * brk;
    // the whitewater trailing seaward of the front, and the glow it leaves under the surface
    float trail = smoothstep(-w, w, dZ) * exp(-max(dZ, 0.0) / (0.35 + 0.5 * ph));
    float lace = 0.6;
    if (det > 0.5) {
      float fb = fbm3(vec3(X * 2.4, Z * 3.2 - ph * 2.0, f * 3.0 + ph));
      lace = smoothstep(-0.12, 0.28, fb) * (0.55 + 0.45 * smoothstep(0.1, 0.5, gnoise(vec3(X * 7.0, Z * 9.0, f + ph))));
      lace = mix(0.6, lace, exp(-Z * 0.25));
    }
        // the whitewater's glow comes and goes in patches, which follow the water, not the line of sight
    float brT = smoothstep(-0.3, 0.5, 0.5 * bn + gnoise(vec3(X * 0.8, Z * 2.2 - ph * 1.5, f * 2.0 + 7.0)) + 0.3 * ph);
    g += env * (crest * 1.4 + trail * brT * (0.1 + 0.9 * lace) * 0.45);
  }
  return g;
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.45, 1.25, u_opt.x);
  float gk = mix(0.5, 1.35, u_opt.y);
  float yh = 0.2;
  vec3 gl = lab2lin(u_pal[3]);
  vec3 gh = lab2lin(u_pal[5]);
  // the sky, a few faint stars high up in the dark
  vec3 sky = lab2lin(skyAt(p.y - yh));
  vec3 sh = hash33(vec3(floor(p * 160.0), 2.0));
  sky += vec3(0.6, 0.7, 0.8) * step(0.994, sh.x * 0.5 + 0.5) * smoothstep(0.3, 0.9, p.y) * u_dark * 0.25;
  // the ground in perspective: Z is the distance from us, X across
  float dz = max(yh - p.y, 1e-3);
  float Z = 1.0 / dz;
  float X = p.x * Z;
  float wl = 1.5 + 0.12 * gnoise(vec3(X * 0.3, 0.0, 3.0));
  // the line the waves reach on the sand, and the wet band below it
  float reach = wl - (0.16 + 0.16 * m) - 0.04;
  float onWater = smoothstep(wl - 0.05, wl + 0.12, Z);
  float wet = smoothstep(reach - 0.12, reach + 0.03, Z) * (1.0 - onWater);
  // the sea: dark water that mirrors the dusk more strongly toward the horizon
  float fres = 0.08 + 0.85 * pow(sat(1.0 - dz * 1.6), 4.0);
  float sw = lnoise(vec2(X * 0.5, Z * 1.2), a, 0.6) * 0.5 + 0.5;
  vec3 sea = mix(lab2lin(u_pal[2]), lab2lin(skyAt(dz * (0.8 + 0.4 * sw))), fres);
  // the sand: dark grain at our feet; where wet, a rough mirror of the sky streaked toward us
  float grain = (gnoise(vec3(X * 34.0, Z * 34.0, 1.0)) * 0.6 + gnoise(vec3(X * 9.0, Z * 9.0, 2.0)) * 0.4) * mix(0.5, 1.0, u_dark);
  vec3 dry = lab2lin(setL(u_pal[4], u_pal[4].x * (1.0 + 0.08 * grain)));
  float streak = gnoise(vec3(X * 9.0, Z * 1.5, 4.0)) * 0.5 + 0.5;
  vec3 mirror = lab2lin(skyAt(dz * (1.0 + 0.6 * streak)));
  vec3 sand = mix(dry, mix(dry * 0.7, mirror, 0.55 + 0.25 * streak), wet);
  vec3 lin = mix(sand, sea, onWater);
  // the glow: in the water and the thin sheets running over the sand
  float e = glowAt(X, Z, a, m, wl, 1.0) * smoothstep(reach - 0.15, reach + 0.15, Z);
  // its reflection in the wet sand: the glow a little farther out seen in the mirror, smeared and broken by the grain
  float refl = glowAt(X + 0.03 * (streak - 0.5), Z * 1.12 + 0.05 + 0.1 * streak, a, m, wl, 0.0) * wet * (0.3 + 0.7 * streak * streak);
  float E = (e + refl * 0.8) * gk;
  vec3 em = gl * E + gh * pow(sat(e * gk * 0.8), 3.0) * 0.6;
  // dark: emitted light added to the night; light: the glow laid over the pale dusk so it keeps its colour
  vec3 dk = lin + em * 0.7;
  vec3 lt = mix(lin, mix(gl, gh, sat(e * 0.5)), sat(E * 0.55));
  lin = mix(lt, dk, u_dark);
  // the faint glow of the whole bay lifts the near sand a little
  lin += gl * 0.02 * gk * (1.0 - onWater) * smoothstep(0.0, 1.0, 1.0 / (wl - Z + 1.0)) * u_dark;
  // haze on the horizon
  lin = mix(lin, lab2lin(u_pal[1]), exp(-dz * 30.0) * 0.55);
  lin = mix(lin, sky, smoothstep(-edgePx(), edgePx(), p.y - yh));
  return lin2srgb(shoulder(lin));
}

// Planish: a sheet of hand-hammered metal, every blow of the hammer leaving a shallow dish, so the surface is a field
// of small curved mirrors. Two soft studio lights glide slowly across it; each dish catches them at its own angle and
// throws back a little crescent of light, so the shine travels over the sheet in a shimmer. The metal's own colour
// deepens where it reflects the dark of the room.
// Palette: 0 the metal in shadow, 1 the metal, 2 the first light, 3 the second light, 4 the room's dark, 5 the brightest
// highlight.
// Options: x = motion (how far the lights glide), y = dishes (large to small).
const float T = 60.0;

// the sheet's height: each blow a shallow paraboloid dish; a smooth minimum over the nearby blows rounds the ridges
float sheet(vec2 q) {
  vec2 c0 = floor(q);
  float acc = 0.0;
  for (int j = 0; j < 3; j++) {
    for (int i = 0; i < 3; i++) {
      vec2 c = c0 + vec2(float(i) - 1.0, float(j) - 1.0);
      vec3 h = hash33(vec3(c, 7.0)) * 0.5 + 0.5;
      vec2 d = c + 0.5 + 0.42 * (h.xy - 0.5) * 2.0 - q;
      acc += exp(-dot(d, d) * (7.0 + 3.0 * h.z));
    }
  }
  return -log(acc + 1e-4) / 8.5;
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.3, u_opt.x);
  float S = mix(2.4, 4.2, u_opt.y);
  vec2 q = p * S;
  float e = 0.01;
  float h0 = sheet(q);
  vec2 slope = vec2(sheet(q + vec2(e, 0.0)) - h0, sheet(q + vec2(0.0, e)) - h0) / e * 0.55;
  slope += 0.02 * vec2(gnoise(vec3(p * 12.0, 1.0)), gnoise(vec3(p * 12.0, 2.0)));
  vec3 n = normalize(vec3(-slope, 1.0));
  // the reflected direction looks up into the studio: two soft lights and the dark between
  vec3 r = reflect(vec3(0.0, 0.0, -1.0), n);
  vec2 rv = r.xy / max(r.z, 0.2) * 1.2 + p * 0.75;
  vec2 l1 = vec2(-0.8 + 0.7 * m * sin(a), 0.5) + u_sun;
  vec2 l2 = vec2(1.0 + 0.6 * m * sin(a + 2.3), -0.35 + 0.2 * cos(a));
  float s1 = exp(-dot(rv - l1, rv - l1) / 0.6);
  float s2 = exp(-dot(rv - l2, rv - l2) / 0.45);
  float room = smoothstep(0.0, 1.0, s1 + s2);
  vec3 metal = mix(u_pal[0], u_pal[1], 0.5 + 0.5 * sat(dot(n.xy, normalize(vec2(-0.5, 0.8))) * 3.0));
  vec3 col = mix(mix(u_pal[4], metal, 0.65), metal, room * 0.6);
  col = mix(col, u_pal[2], sat(s1 * 1.2) * 0.75);
  col = mix(col, u_pal[3], sat(s2 * 1.2) * 0.7);
  col = mix(col, u_pal[5], pow(sat(s1 + s2), 6.0) * 0.45);
  return outLab(col);
}

// Mist: coloured mist lying in four layers at different depths. A slow camera orbit shifts each layer by an amount set
// by its depth, so the near veils slide across the far ones (parallax); the near veils are larger and softer, the far
// ones finer and paler, and the clouds themselves change shape only slowly. Calm, but never a flat gradient.
// Palette: 0 the far ground, 1 to 4 the layers from far to near, 5 a faint light from above.
// Options: x = motion (how far the camera drifts), y = depth (how far apart the layers sit).
// Perspective: layers (each layer is shifted by tiltD from far to near).
const float T = 90.0;

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.3, 1.4, u_opt.x);
  float dp = mix(0.35, 1.4, u_opt.y);
  vec2 cam = orbit(a, 0.22 * m) + vec2(0.0, 0.05 * m * sin(2.0 * a));
  vec3 col = mix(u_pal[0], setL(u_pal[0], u_pal[0].x * 1.06 + 0.01), smoothstep(-1.0, 1.0, p.y));
  col = mix(col, u_pal[5], 0.16 * smoothstep(0.1, 1.2, p.y - 0.2 * p.x));
  for (int i = 0; i < 4; i++) {
    float f = float(i);
    float z = 0.25 + 0.55 * f * dp;
    float sc = 1.25 - 0.22 * f;
    vec2 q = (p + cam * z + tiltD((f - 1.5) / 1.5)) * sc + vec2(f * 3.1, f * 1.7);
    float n = gnoise(vec3(q * 0.9, f * 2.0) + vec3(orbit(a + f, 0.08 * m), 0.06 * m * sin(a + f)))
            + 0.45 * gnoise(vec3(q * 1.9, f * 5.0 + 1.0) + vec3(orbit(-a, 0.06 * m), 0.0));
    float soft = 0.08 + 0.07 * f;
    float d = smoothstep(-0.12 - soft, 0.25 + soft, n + 0.1 * (p.y * (f - 1.5) * 0.3));
    float al = (0.42 + 0.12 * f) * d;
    vec3 lc = u_pal[1 + i];
    lc.x += 0.035 * smoothstep(0.25, 0.75, d) * (1.0 - smoothstep(0.75, 1.0, d));
    col = mix(col, lc, al);
    col.x -= 0.012 * smoothstep(0.2, 0.6, d) * (1.0 - smoothstep(0.6, 1.0, d)) * (f / 3.0);
  }
  return outLab(col);
}

// Daybreak: a quiet horizon at first light. The sky runs from a cool zenith to a warm band at the horizon, a low sun
// glows through haze and rests on still water below, and the colours drift very slightly warmer and back.
// Palette: 0 zenith, 1 upper sky, 2 horizon band, 3 water, 4 sun glow, 5 sun core.
// Options: x = motion (how far the sun drifts), y = glow.
const float T = 80.0;

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.3, 1.4, u_opt.x);
  float gl = mix(0.4, 1.4, u_opt.y);
  float y0 = -0.32 + 0.015 * sin(p.x * 0.9 + 1.0);
  vec2 sun = vec2(0.42 + 0.16 * m * sin(a), y0 + 0.13 + 0.05 * m * sin(a + 1.2)) + u_sun;
  float h = p.y - y0;
  vec3 sky = mix(u_pal[2], u_pal[1], smoothstep(0.0, 0.55, h));
  sky = mix(sky, u_pal[0], smoothstep(0.45, 1.4, h));
  float band = 0.008 * sin(h * 22.0 + 1.5 * sin(p.x * 1.1 + a)) * smoothstep(0.0, 0.2, h) * smoothstep(0.9, 0.3, h);
  sky.x += band;
  vec3 water = mix(setL(u_pal[3], u_pal[3].x + 0.03), u_pal[3], smoothstep(0.0, 0.6, -h));
  vec3 col = mix(water, sky, smoothstep(-u_px, u_px, h));
  col = mix(col, mix(u_pal[2], u_pal[3], 0.5), exp(-(h * h) / (u_px * u_px * 4.0 + 0.00002)) * 0.5);
  vec2 ds = p - sun;
  float g = exp(-dot(ds, ds) / 0.16) * 0.42 + exp(-dot(ds, ds) / 0.6) * 0.18;
  float core = exp(-dot(ds, ds) / 0.004);
  float rx = (p.x - sun.x) / 0.16;
  float ry = h / 0.45;
  float refl = exp(-rx * rx - ry * ry) * 0.3 * (0.85 + 0.15 * sin(-h * 60.0 + a * 2.0)) * smoothstep(u_px, -u_px, h);
  col = mix(col, u_pal[4], sat((g + refl) * gl));
  col = mix(col, u_pal[5], sat(core * 0.7 * gl));
  col = hueShift(col, 0.1 * sin(a));
  return outLab(col);
}

// Stillwater: the light of a pool thrown softly onto a pale wall: slow, wide, out-of-focus ripples of brightness over
// a two-colour wash, never sharp enough to pull the eye.
// Palette: 0 wall, 1 wall's second colour, 2 shade, 3 the rippled light, 4 warm edge of the light, 5 unused highlight.
// Options: x = motion (how strongly the water moves), y = shimmer (how bright the ripples are).
const float T = 80.0;

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.4, 1.3, u_opt.x);
  float sh = mix(0.35, 1.3, u_opt.y);
  vec2 x = p * 0.8 + 0.08 * m * vec2(lnoise(p * 0.6, a, 0.3), lnoise(p * 0.6 + 4.0, a, 0.3));
  float hxx = 0.0;
  float hyy = 0.0;
  float hxy = 0.0;
  for (int i = 0; i < 7; i++) {
    float f = float(i);
    float an = f * 2.39996 + 1.1;
    float kk = 15.0 + 3.5 * sin(f * 1.3);
    vec2 k = vec2(cos(an), sin(an)) * kk;
    float n = mod(f, 2.0) < 0.5 ? 1.0 : -1.0;
    float A = 0.26 / (kk * kk) * (0.65 + 0.35 * m);
    float s = -A * sin(dot(k, x) + n * a + f * 2.1);
    hxx += s * k.x * k.x;
    hyy += s * k.y * k.y;
    hxy += s * k.x * k.y;
  }
  float J = 1.0 + 1.25 * (hxx + hyy) + 1.6 * (hxx * hyy - hxy * hxy);
  float I = 1.9 / (abs(J) + 0.9) - 1.0;
  float lightArea = smoothstep(1.7, 0.1, length((p - vec2(0.35, 0.35)) * vec2(0.65, 1.0)));
  vec3 col = mix(u_pal[1], u_pal[0], smoothstep(-1.2, 1.2, p.y - 0.4 * p.x));
  col = mix(col, u_pal[2], 0.3 * smoothstep(0.6, 2.0, length(p * vec2(0.65, 1.0))));
  vec3 lc = mix(u_pal[4], u_pal[3], lightArea);
  col = mix(col, lc, sat(I * 0.75 * sh * lightArea + 0.16 * lightArea));
  return outLab(col);
}

// Linen: a woven cloth breathing in a faint draught. The weave is real: warp and weft threads passing over and under
// each other, each thread a little thicker or thinner along its length (the slubs that make linen linen), so the cloth
// carries fine streaks along both directions. The threads follow the folds, the folds rise and settle, and the light
// from the top left grazes the weave, showing it most on the lit slopes.
// Palette: 0 fold shadow, 1 cloth, 2 lit cloth, 3 the second tint, 4 sheen, 5 the light.
// Options: x = motion (how far the cloth lifts), y = weave (fine to coarse).
const float T = 72.0;

float cloth(vec2 q, float a, float m) {
  float u = q.x + 0.3 * sin(q.y * 0.9 + 0.5 * m * sin(a)) + 0.12 * m * sin(q.y * 1.7 - a + 0.5);
  return 0.5 * sin(u * 1.7 + 0.6 * sin(q.y * 0.7 + a)) + 0.22 * sin(u * 3.1 - q.y * 0.5 + 1.1 + 0.5 * m * sin(a + 2.0));
}

float h1(float x) { return hash33(vec3(x, 7.0, 3.0)).x * 0.5 + 0.5; }

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.3, 1.4, u_opt.x);
  float P = mix(0.0075, 0.018, u_opt.y);
  vec2 q = rot(p, -0.35);
  float e = 0.004;
  float h0 = cloth(q, a, m);
  vec2 gr = vec2(cloth(q + vec2(e, 0.0), a, m) - h0, cloth(q + vec2(0.0, e), a, m) - h0) / e;
  vec3 n = normalize(vec3(-gr * 0.42, 1.0));
  vec3 L = normalize(vec3(-0.4, 0.5, 0.77));
  float s = sat(dot(n, L) * 1.3 - 0.05);
  float sheen = pow(max(dot(n, normalize(L + vec3(0.0, 0.0, 1.0))), 0.0), 12.0);
  vec3 col = mix(u_pal[0], u_pal[1], smoothstep(0.45, 0.85, s));
  col = mix(col, u_pal[2], smoothstep(0.82, 1.0, s));
  col = mix(col, mix(col, u_pal[3], 0.75), smoothstep(-1.4, 1.4, p.x * 0.8 + p.y * 0.4 + 0.3 * sin(a)));

  // the weave, in cloth coordinates that ride on the folds
  vec2 w = rot(p, 0.12) + gr * 0.012;
  float wu = w.x / P + 0.18 * gnoise(vec3(w * 9.0, 4.0));
  float wv = w.y / P + 0.18 * gnoise(vec3(w * 9.0, 8.0));
  float cu = floor(wu);
  float cv = floor(wv);
  float fu = wu - cu - 0.5;
  float fv = wv - cv - 0.5;
  float warpTop = step(0.5, mod(cu + cv, 2.0));
  float slubU = 0.75 + 0.5 * h1(cu) + 0.35 * gnoise(vec3(cu * 0.37, wv * 0.045, 1.0));
  float slubV = 0.75 + 0.5 * h1(cv + 91.0) + 0.35 * gnoise(vec3(wu * 0.045, cv * 0.37, 2.0));
  float tu = cos(3.14159 * fu * 0.95);
  float tv = cos(3.14159 * fv * 0.95);
  float weave = mix(tv * slubV, tu * slubU, warpTop) * (0.55 + 0.45 * mix(abs(tu), abs(tv), warpTop));
  float gap = smoothstep(0.42, 0.5, max(abs(fu), abs(fv)));
  float fine = sat(P / u_px / 3.5 - 0.6);
  float grazing = 0.55 + 0.9 * sat(dot(gr, vec2(0.6, -0.55)) * 0.6 + 0.4);
  col.x += (0.022 * (weave - 0.55) - 0.006 * gap) * fine * grazing;

  // the slubs at the scale a tile can show: fine streaks along both thread directions
  float st = gnoise(vec3(w.x * 46.0, w.y * 2.2, 3.0)) + gnoise(vec3(w.x * 2.2, w.y * 46.0, 5.0));
  st += 0.6 * (gnoise(vec3(w.x * 110.0, w.y * 4.0, 6.0)) + gnoise(vec3(w.x * 4.0, w.y * 110.0, 7.0))) * sat(0.02 / u_px / 3.0 - 0.5);
  col.x += 0.012 * st * (0.6 + 0.4 * s);
  col = mix(col, u_pal[4], sheen * 0.28);
  col = mix(col, u_pal[5], 0.1 * smoothstep(1.6, 0.0, length(p - vec2(-0.9, 0.7))));
  return outLab(col);
}

// Fields: three soft fields of colour floating on a ground, after the colour-field painters: feathered, slightly uneven
// edges, a glow from within, and colours and edges that breathe so slowly the change is only noticed afterwards.
// Palette: 0 ground, 1 upper field, 2 middle band, 3 lower field, 4 inner glow, 5 unused highlight.
// Options: x = motion (how much the fields breathe), y = edges (crisp to feathered).
const float T = 90.0;

float field(vec2 p, vec2 c, vec2 hs, float soft, float a, float k, float m) {
  vec2 q = abs(p - c) - hs;
  float d = length(max(q, vec2(0.0))) + min(max(q.x, q.y), 0.0) - 0.05;
  d += 0.022 * lnoise(p * 2.3 + k * 7.0, a, 0.25 * m) + 0.01 * lnoise(p * 6.0 + k * 3.0, a, 0.2 * m);
  return d;
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.3, 1.4, u_opt.x);
  float soft = mix(0.025, 0.12, u_opt.y);
  vec3 col = mix(u_pal[0], setL(u_pal[0], u_pal[0].x * 0.94), smoothstep(-1.0, 1.0, -p.y));
  float b = 0.02 * m;
  float d1 = field(p, vec2(0.0, 0.47 + b * sin(a)), vec2(1.22, 0.3 + b * sin(a + 1.0)), soft, a, 1.0, m);
  float d2 = field(p, vec2(0.0, -0.06), vec2(1.22, 0.09 + 0.6 * b * sin(a + 2.5)), soft, a, 2.0, m);
  float d3 = field(p, vec2(0.0, -0.56 - b * sin(a + 1.7)), vec2(1.22, 0.27 + b * sin(a + 3.0)), soft, a, 3.0, m);
  vec3 c1 = hueShift(u_pal[1], 0.07 * m * sin(a));
  vec3 c2 = hueShift(u_pal[2], 0.07 * m * sin(a + 2.0));
  vec3 c3 = hueShift(u_pal[3], 0.07 * m * sin(a + 4.0));
  c1 = mix(c1, u_pal[4], 0.22 * smoothstep(0.0, -0.3, d1));
  c3 = mix(c3, u_pal[4], 0.18 * smoothstep(0.0, -0.28, d3));
  col = mix(col, c1, smoothstep(soft, -soft, d1));
  col = mix(col, c2, smoothstep(soft, -soft, d2));
  col = mix(col, c3, smoothstep(soft, -soft, d3));
  return outLab(col);
}

// Lumen: a shaft of sunlight sweeping slowly across a quiet wall, as the sun moves past a window. Inside the shaft,
// the light that passed through a glass on the sill lies in a soft caustic, a gentle net of brighter light that wavers;
// a cool pool answers from the far corner. Low in contrast, slow, and never a plain gradient.
// Palette: 0 wall, 1 wall low, 2 the sunlight, 3 the cool pool, 4 the caustic light, 5 unused highlight.
// Options: x = motion (how far the shaft sweeps), y = glow.
const float T = 70.0;

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.3, 1.4, u_opt.x);
  float gl = mix(0.45, 1.4, u_opt.y);
  vec3 col = mix(u_pal[1], u_pal[0], smoothstep(-1.2, 1.0, p.y));
  // the shaft: a slanted band from the top left whose position swings slowly across the wall
  vec2 dir = normalize(vec2(0.62, -0.78));
  vec2 nrm = vec2(-dir.y, dir.x);
  float pos = -0.25 + 0.55 * m * sin(a) + 0.08 * m * sin(2.0 * a + 1.0) + u_sun.x;
  float across = dot(p, nrm) - pos;
  float along = dot(p, dir);
  float wid = 0.72 + 0.08 * sin(a + 1.3);
  float shaft = smoothstep(wid, wid * 0.2, abs(across)) * (0.55 + 0.45 * smoothstep(2.2, -0.6, along));
  // the caustic, in the shaft's own coordinates, from a softly moving surface
  vec2 x = vec2(across * 2.3, along * 1.5) + 0.06 * vec2(lnoise(p * 0.7, a, 0.3), lnoise(p * 0.7 + 3.0, a, 0.3));
  float hxx = 0.0;
  float hyy = 0.0;
  float hxy = 0.0;
  for (int i = 0; i < 5; i++) {
    float f = float(i);
    float an = f * 2.39996 + 0.7;
    float kk = 11.0 + 2.5 * sin(f * 1.9);
    vec2 k = vec2(cos(an), sin(an)) * kk;
    float s = -0.26 / (kk * kk) * sin(dot(k, x) + (mod(f, 2.0) < 0.5 ? 1.0 : -1.0) * (1.0 + floor(f / 2.0)) * a + f * 1.7);
    hxx += s * k.x * k.x;
    hyy += s * k.y * k.y;
    hxy += s * k.x * k.y;
  }
  float J = 1.0 + 1.5 * (hxx + hyy) + 2.0 * (hxx * hyy - hxy * hxy);
  float caus = sat(1.45 / (abs(J) + 0.45) - 1.0) * smoothstep(wid * 1.05, wid * 0.15, abs(across)) * (0.6 + 0.4 * smoothstep(2.0, -0.4, along));
  vec3 sun = hueShift(u_pal[2], 0.1 * sin(a + 0.5));
  col = mix(col, sun, sat(shaft * 0.68 * gl));
  col = mix(col, u_pal[4], sat(caus * 0.3 * gl));
  vec2 d2 = rot(p - vec2(1.05 + 0.12 * m * cos(a + 2.0), -0.72), 0.4) / vec2(1.0, 0.65);
  col = mix(col, u_pal[3], sat(exp(-dot(d2, d2)) * 0.55 * gl));
  return outLab(col);
}

// Drift: hills standing in morning fog, one ridge behind another. Each ridge is a soft silhouette that pales toward its
// foot where the fog pools; the far ridges are nearly sky, the near one carries the most colour, and the fog rises and
// settles so the ridges seem to come and go.
// Palette: 0 sky, 1 sky low, 2 far ridge, 3 middle ridge, 4 near ridge, 5 the light behind.
// Options: x = motion (how much the fog rises and settles), y = density (how thick the fog lies).
const float T = 84.0;

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.3, 1.4, u_opt.x);
  float den = mix(0.45, 1.35, u_opt.y);
  vec3 sky = mix(u_pal[1], u_pal[0], smoothstep(-0.6, 1.0, p.y));
  vec2 ls = p - vec2(0.75, 0.42);
  sky = mix(sky, u_pal[5], 0.4 * exp(-dot(ls, ls) / 0.5));
  vec3 col = sky;
  for (int i = 0; i < 4; i++) {
    float f = float(i);
    float fk = f / 3.0;
    vec2 pp = p + tiltD(fk * 2.0 - 1.0);
    float sc = 0.7 + 0.35 * f;
    float yk = 0.32 - 0.36 * f;
    float edge = yk + (0.12 + 0.03 * f) * (0.6 * sin(pp.x * sc + f * 2.1) + 0.4 * sin(pp.x * sc * 2.3 + f * 0.7))
               + 0.035 * m * lnoise(vec2(pp.x * 0.9 + f * 3.0, f), a, 0.4);
    float soft = 0.012 + 0.03 * (1.0 - fk);
    float body = smoothstep(soft, -soft, pp.y - edge);
    vec3 rc = mix(u_pal[2], u_pal[3], sat(fk * 1.5));
    rc = mix(rc, u_pal[4], sat(fk * 1.5 - 0.5));
    rc = mix(sky, rc, 0.45 + 0.55 * fk);
    float fog = smoothstep(0.0, 0.42, edge - pp.y) * (0.55 + 0.25 * sin(a + f * 1.9)) * den;
    fog *= 0.75 + 0.25 * lnoise(vec2(pp.x * 1.3 + f * 5.0, pp.y * 2.0), a, 0.3 * m);
    rc = mix(rc, mix(sky, u_pal[5], 0.25), sat(fog * (0.75 - 0.25 * fk)));
    col = mix(col, rc, body);
  }
  return outLab(col);
}

// Halo: one wide, soft ring of light resting off-centre, its colour turning slowly round it, the inside faintly lit by
// it. Out of focus throughout, so it reads as light, not as a shape.
// Palette: 0 ground, 1 to 3 the ring's colours round the circle, 4 the light inside, 5 unused highlight.
// Options: x = motion (how much the ring breathes), y = width.
const float T = 90.0;

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.3, 1.4, u_opt.x);
  float wd = mix(0.22, 0.5, u_opt.y);
  vec2 c = vec2(0.55, -0.12) + orbit(a, 0.03 * m);
  vec2 d = p - c;
  float r = length(d);
  float R = 0.95 + 0.04 * m * sin(a * 2.0);
  float ang = atan(d.y, d.x) + a;
  vec3 acc = vec3(0.0);
  float ws = 0.0;
  for (int i = 0; i < 3; i++) {
    float w = pow(0.5 + 0.5 * cos(ang - float(i) * 2.0943951), 2.0);
    acc += u_pal[i + 1] * w;
    ws += w;
  }
  vec3 rc = acc / ws;
  float rr = (r - R) / wd;
  float ring = exp(-rr * rr);
  vec3 col = mix(u_pal[0], setL(u_pal[0], u_pal[0].x * 0.95), smoothstep(0.0, 2.0, length(p + vec2(0.8, 0.5))));
  col = mix(col, mix(u_pal[4], rc, 0.3), 0.4 * exp(-(r * r) / 0.6));
  col = mix(col, rc, ring * 0.75);
  return outLab(col);
}

// Alabaster: a thin slab of translucent stone with a light behind it that breathes, a quicker swell and a long fall.
// The stone is banded the way onyx and alabaster are, with a few fine veins; where the light is strong the bands glow
// through and the veins show, where it is weak the stone is calm and nearly even. The stone never moves; only the
// light behind it does, so the picture stays still while it breathes. Under Perspective the slab and the light part.
// Palette: 0 the stone where little light passes, 1 the stone's body, 2 the light through it, 3 the veins, 4 the glow's
// core, 5 the second, cooler light.
// Options: x = motion (how far the light drifts and how deep it breathes), y = veins (faint to clear).
const float T = 80.0;

// one breath: a cosine whose phase is bent, so the swell is quicker than the fall; 0 at rest .. 1 full
float breath(float ph) { return 0.5 - 0.5 * cos(ph + 0.45 * sin(ph)); }

// a mix that travels round the hue circle instead of across it, so a warm light over a cool stone passes through rose,
// never through grey or brown
vec3 mixh(vec3 a, vec3 b, float k) {
  float ca = length(a.yz);
  float cb = length(b.yz);
  float ha = atan(a.z, a.y + 1e-6);
  float dh = atan(b.z, b.y + 1e-6) - ha;
  dh -= TAU * floor(dh / TAU + 0.5);
  float h = ha + dh * k;
  float c = mix(ca, cb, k);
  // near-opposite hues have no shortest way round: there it falls back to the straight mix, so nothing ever jumps
  return mix(vec3(mix(a.x, b.x, k), c * cos(h), c * sin(h)), mix(a, b, k), smoothstep(2.3, 2.9, abs(dh)));
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.3, 1.4, u_opt.x);
  float vk = mix(0.3, 1.3, u_opt.y);
  // the slab: banded layers folded by a slow warp, and veins where the warped field crosses one level
  vec2 s = rot(p + tiltD(1.0), 0.42) * 0.85;
  vec2 w = vec2(fbm3(vec3(s * 0.65, 1.0)), fbm3(vec3(s * 0.65 + 5.2, 2.0)));
  float v = fbm4(vec3(s * 1.25 + w * 1.7, 3.0));
  float ph = s.y + 0.95 * w.y + 0.7 * v;
  float band = 0.5 + 0.5 * sin(ph * 8.0);
  float band2 = 0.5 + 0.5 * sin(ph * 19.0 + 1.3 * w.x);
  float vein = 1.0 - smoothstep(0.0, 0.03 + 0.02 * u_focus, abs(v + 0.06 - 0.12 * w.x));
  float tr = sat(0.56 + 0.22 * (band - 0.5) + 0.1 * (band2 - 0.5) + 0.55 * v);
  // the lights behind it
  vec2 q = p + tiltD(-1.0);
  float b = breath(5.0 * a) * mix(0.55, 1.0, sat(u_opt.x * 1.5));
  vec2 c1 = vec2(-0.38, -0.18) + orbit(a, 0.12 * m) + vec2(0.04 * m * sin(2.0 * a + 1.0), 0.0);
  vec2 d1 = (q - c1) * vec2(0.8, 1.0);
  float I = exp(-dot(d1, d1) / (0.75 + 0.3 * b)) * (0.48 + 0.52 * b);
  vec2 d2 = q - vec2(1.2, 0.7) - orbit(-a, 0.05 * m);
  float I2 = exp(-dot(d2, d2) / 0.6) * (0.6 - 0.2 * b);
  float g = I * (0.45 + 0.75 * tr);
  float g2 = I2 * (0.4 + 0.7 * tr);
  vec3 col = mix(u_pal[0], u_pal[1], tr);
  col = mixh(col, u_pal[5], sat(g2 * 0.75));
  col = mixh(col, u_pal[2], sat(g * mix(1.4, 1.1, u_dark)));
  col = mix(col, u_pal[4], 0.55 * smoothstep(0.45, 1.0, g));
  col = mix(col, u_pal[3], sat(vein * mix(0.25, 0.4, u_dark) * vk * (0.35 + 0.65 * sat(I + I2))));
  col.x += 0.012 * (band2 - 0.5) * vk * (0.3 + I);
  return outLab(col);
}

// Grove: tall trunks standing in morning fog, rank behind rank. The far ranks are almost fog, the near ones carry the
// most colour, and soft shafts of light lean down through the gaps from a sun behind the trees. The fog drifts between
// the ranks and thickens near the ground, so the trunks seem to come and go. The middle of the window stays open fog:
// the nearest trunks keep to the sides. Each rank is its own Perspective layer.
// Palette: 0 fog high, 1 fog low (in dark packs a warm mist under a moonlit blue), 2 far trunks, 3 near trunks, 4 the light,
// 5 the light's core.
// Options: x = motion (how much the fog drifts and the shafts waver), y = density (thin to thick fog).
const float T = 84.0;

float h1(float x) { return hash33(vec3(x, 3.1, 7.7)).x * 0.5 + 0.5; }

// one rank of trunks: x = the cover 0..1 at q, y = where across the trunk q lies (-1 shade side .. 1 sun side), for trunks
// dens per unit of width, wa..wb wide, their edges soft
vec2 rank(vec2 q, float dens, float wa, float wb, float soft, float seed, float open, float there0) {
  float x = q.x * dens + seed;
  float c0 = floor(x);
  float cov = 0.0;
  float side = 0.0;
  for (int i = 0; i < 3; i++) {
    float c = c0 + float(i) - 1.0;
    float there = step(there0, h1(c * 1.31 + seed));
    float cx = c + 0.18 + 0.64 * h1(c * 2.17 + seed * 1.9);
    float wd = mix(wa, wb, h1(c * 3.71 + seed * 0.7)) * (1.0 - 0.06 * q.y);
    float lean = (h1(c * 5.3 + seed) - 0.5) * 0.05 * q.y + 0.01 * sin(q.y * 1.7 + c);
    float dx = (x - cx) / dens - lean;
    float keep = mix(1.0, smoothstep(0.42, 0.95, abs(cx / dens - seed / dens)), open);
    float cv = there * keep * smoothstep(wd + soft, wd - soft, abs(dx));
    if (cv > cov) { cov = cv; side = clamp(dx / wd, -1.0, 1.0); }
  }
  return vec2(cov, side);
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.3, 1.4, u_opt.x);
  float den = mix(0.5, 1.35, u_opt.y);
  // the fog itself, lit from a sun high behind the trees
  vec2 sun = vec2(0.55, 1.35) + u_sun;
  vec2 ds = p - sun;
  float glow = exp(-dot(ds, ds) / 1.6);
  vec3 fog = mix(u_pal[1], u_pal[0], smoothstep(-0.9, 0.9, p.y + 0.15 * lnoise(p * 0.5 + 4.0, a, 0.3 * m)));
  fog = mix(fog, u_pal[4], 0.45 * glow);
  // shafts of light leaning down from the sun, wavering slowly
  float ang = atan(ds.x, -ds.y);
  float sh = lnoise(vec2(ang * 4.0, 1.0), a, 0.3 * m) * 0.7 + lnoise(vec2(ang * 8.5, 4.0), a, 0.25 * m) * 0.3;
  float shaft = smoothstep(0.0, 0.7, sh) * smoothstep(3.6, 0.6, length(ds)) * (0.6 + 0.4 * glow);
  // the fog pools brighter near the ground
  fog = mix(fog, mix(u_pal[4], u_pal[1], 0.5), 0.16 * smoothstep(-0.2, -1.1, p.y));
  vec3 col = fog;
  for (int i = 0; i < 4; i++) {
    float f = float(i);
    float fk = f / 3.0;
    vec2 q = p + tiltD(mix(-1.0, 1.0, fk));
    float dens = mix(1.9, 0.7, fk);
    vec2 rk = rank(q, dens, mix(0.014, 0.06, fk), mix(0.024, 0.1, fk), mix(0.01, 0.018, fk) + 0.004 * u_focus, 17.0 + f * 9.3, fk * fk, mix(0.5, 0.32, fk));
    // the fog in front of this rank: thicker for the far ranks and near the ground, lying in banks that drift
    float bank = lnoise(vec2(q.x * 0.4 + f * 2.7, q.y * 1.6 - f), a, 0.55 * m);
    float fogA = sat((mix(0.78, 0.14, fk) + 0.3 * smoothstep(0.2, -1.0, q.y) + 0.5 * bank) * den);
    vec3 tc = mix(u_pal[2], u_pal[3], fk);
    tc.x += 0.025 * rk.y * (1.0 - fogA);
    tc = mix(tc, mix(fog, u_pal[4], 0.3 * shaft), fogA);
    col = mix(col, tc, rk.x);
    // the light in the fog between this rank and the next
    col = mix(col, u_pal[4], sat(shaft * mix(0.1, 0.16, u_dark) * den * (1.0 - fk * 0.6)));
  }
  col = mix(col, u_pal[5], 0.18 * glow * glow);
  return outLab(col);
}

// Clay: one soft, rounded form in matte clay, like a smooth river stone, floating a little above a seamless studio
// sweep. A large soft key light from the upper left models it, the sweep's own colour bounces back into its lower
// edge, and its shadow on the floor softens and widens as it rises and sharpens as it settles. It sways and rises
// very slowly, and its outline breathes a little, so it never looks like a still render. It sits right of centre.
// Palette: 0 the floor, 1 the wall of the sweep, 2 the form's shadow side, 3 the form's body, 4 the form's lit face,
// 5 the soft highlight.
// Options: x = motion (how far it rises and sways), y = softness of the light (crisp to soft).
const float T = 64.0;

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.3, 1.4, u_opt.x);
  float sf = u_opt.y;
  vec2 L2 = normalize(vec2(-0.55, 0.7) + u_sun);
  // the sweep: floor curving up into the wall, lit from the upper left
  vec2 pb = p + tiltD(-1.0);
  float horizon = -0.32;
  vec3 col = mix(u_pal[0], u_pal[1], smoothstep(horizon - 0.55, horizon + 0.45, pb.y));
  col.x += 0.035 * smoothstep(2.4, 0.0, length(pb - vec2(-1.1, 1.0) - u_sun)) - 0.025 * smoothstep(0.8, 2.6, length(pb - vec2(-0.4, 0.1)));
  // the form
  vec2 q = p + tiltD(1.0);
  float lift = 0.5 + 0.5 * sin(a);
  vec2 c = vec2(0.78 + 0.03 * m * sin(a + 1.3), -0.06 + 0.05 * m * (lift - 0.5));
  vec2 d = q - c;
  float sway = 0.32 + 0.16 * m * sin(a + 0.6);
  vec2 dr = rot(d, -sway);
  float ang = atan(dr.y, dr.x);
  float R = 0.36 * (1.0 + 0.15 * cos(2.0 * ang) + 0.035 * cos(3.0 * ang + 1.0) + 0.012 * m * sin(2.0 * ang + 2.0 * a));
  float r = length(d);
  float nr = r / R;
  float inside = smoothstep(1.0 + edgePx() / R * 1.2, 1.0 - edgePx() / R * 1.2, nr);
  // the shadow on the floor first, so the form covers it
  float fy = horizon - 0.3;
  vec2 sp = (q - vec2(c.x + 0.16 - 0.1 * L2.x, fy)) / vec2(0.42 + 0.08 * lift * m, 0.068 + 0.02 * lift * m);
  float shadow = exp(-dot(sp, sp) * mix(1.6, 0.9, sf)) * (0.75 - 0.25 * lift * m / 1.4);
  float contact = exp(-dot(sp, sp) * 4.0) * 0.35 * (1.0 - 0.5 * lift);
  col = mix(col, vec3(col.x * 0.8, mix(col.yz, u_pal[2].yz, 0.3)), sat(shadow * 0.55 + contact));
  // the form's surface: a flattened dome, so the top is broad and the edge turns away
  float z = sqrt(max(1.0 - min(nr, 1.0) * min(nr, 1.0), 0.0));
  vec3 n = normalize(vec3(d / R, z * 1.5 + 0.05));
  vec3 L = normalize(vec3(L2 * 0.85, 0.75));
  float wrap = mix(0.25, 0.6, sf);
  float dif = sat((dot(n, L) + wrap) / (1.0 + wrap));
  vec3 fc = mix(u_pal[2], u_pal[3], smoothstep(0.05, 0.6, dif));
  fc = mix(fc, u_pal[4], smoothstep(0.55, 1.0, dif));
  float spec = pow(max(dot(n, normalize(L + vec3(0.0, 0.0, 1.0))), 0.0), mix(26.0, 9.0, sf));
  fc = mix(fc, u_pal[5], spec * 0.22);
  // the floor's colour bouncing into the lower edge, and a little occlusion where it turns away
  float bounce = pow(1.0 - z, 2.0) * sat(-n.y * 1.4 + 0.2);
  fc = mix(fc, mix(u_pal[0], u_pal[3], 0.4), bounce * 0.4);
  fc.x -= 0.03 * pow(1.0 - z, 3.0);
  col = mix(col, fc, inside);
  return outLab(col);
}

// Droplet: still water seen from above, holding the reflection of a soft sky and a pale window of light. Now and then
// a single drop falls, first on one side, then on the other, and its rings spread slowly outward, bending the
// reflection as they pass, and fade long before the next drop. Between the drops the water barely stirs.
// Palette: 0 the water's depth, 1 the reflected sky far, 2 the reflected sky near, 3 the reflected window of light,
// 4 the bright edge of a ring, 5 the window's core.
// Options: x = motion (how strongly the water stirs), y = rings (few and faint to many and clear).
const float T = 60.0;

// the rings of one drop: returns the slope of the water along the radius; age 0..1 runs once per loop
vec2 drop(vec2 q, vec2 c, float age, float rk) {
  vec2 d = q - c;
  float r = length(d) + 1e-4;
  float front = 0.06 + 1.55 * age;
  float x = r - front;
  float wid = 0.08 + 0.36 * age;
  float env = exp(-(x * x) / (wid * wid)) * smoothstep(0.0, 0.04, age) * pow(1.0 - age, 1.4);
  float kk = mix(42.0, 22.0, sqrt(age)) * mix(0.85, 1.15, rk);
  float s = env * cos(x * kk) / sqrt(r + 0.25) * smoothstep(front + 0.02, front - 0.4, r - 0.3 * wid);
  return d / r * s;
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.3, 1.4, u_opt.x);
  float rk = u_opt.y;
  // the slope of the surface: the two drops, half a loop apart, and a faint stir
  float age1 = fract(a / TAU + 0.12);
  float age2 = fract(a / TAU + 0.62);
  vec2 g = drop(p, vec2(-0.78, 0.26), age1, rk) + drop(p, vec2(0.86, -0.38), age2, rk);
  g *= mix(0.012, 0.03, rk);
  g += 0.006 * m * vec2(lnoise(p * 1.4, a, 0.3), lnoise(p * 1.4 + 7.0, a, 0.3));
  // the reflection, displaced by the slope: a soft sky with a few high clouds, still, as the water is
  vec2 rp = p + g * 8.0;
  vec3 col = mix(u_pal[2], u_pal[1], smoothstep(-1.3, 1.2, rp.y - 0.35 * rp.x));
  vec2 sp = rp - vec2(-0.6, 0.55) - u_sun;
  float sunny = exp(-dot(sp, sp) / 0.9);
  col = mix(col, u_pal[3], 0.45 * sunny);
  float cl = fbm3(vec3(rp * vec2(0.8, 1.5) + vec2(0.3, 0.0), 3.0)) + 0.25 * lnoise(rp * 0.6, a, 0.12);
  float cloud = smoothstep(0.02, 0.45, cl);
  col = mix(col, mix(u_pal[3], u_pal[5], sunny), cloud * (0.35 + 0.3 * sunny));
  // the water's own depth darkens the reflection toward the lower left, and the rings catch light on their crests
  col = mix(col, u_pal[0], 0.28 * smoothstep(0.6, 2.4, length(p - vec2(0.4, 0.6))));
  vec2 ld = normalize(vec2(-0.3, 1.0));
  float crest = sat(dot(g, ld) * 110.0);
  col = mix(col, u_pal[4], crest * 0.45);
  col.x -= sat(-dot(g, ld) * 110.0) * 0.035;
  return outLab(col);
}

// Cirrus: looking up into the sky just after dawn. Thin, high cirrus lies across it in long combed streaks, lit from a
// sun still below the lower left, and their light turns slowly from rose to gold and back, as the colour of a real
// dawn shifts. A lower veil, softer and nearer, drifts across the high one.
// Palette: 0 the sky overhead, 1 the sky toward the sun, 2 the clouds' shaded side, 3 the clouds' first light (rose),
// 4 their second light (gold), 5 the glow round the hidden sun.
// Options: x = motion (how much the clouds drift and comb), y = cover (a few streaks to a full veil).
const float T = 90.0;

vec3 mixh(vec3 a, vec3 b, float k) {
  float ca = length(a.yz);
  float cb = length(b.yz);
  float ha = atan(a.z, a.y + 1e-6);
  float dh = atan(b.z, b.y + 1e-6) - ha;
  dh -= TAU * floor(dh / TAU + 0.5);
  float h = ha + dh * k;
  float c = mix(ca, cb, k);
  // near-opposite hues have no shortest way round: there it falls back to the straight mix, so nothing ever jumps
  return mix(vec3(mix(a.x, b.x, k), c * cos(h), c * sin(h)), mix(a, b, k), smoothstep(2.3, 2.9, abs(dh)));
}

// one layer of streaks: long along x, combed fine across y, the fibres bent by a slow warp
float streaks(vec2 q, float a, float m, float seed, float cov) {
  float w = lnoise(q * vec2(0.5, 1.2) + seed, a, 0.22 * m);
  vec2 s = vec2(q.x * 0.55, q.y * 2.6 + 0.5 * w + 0.12 * sin(q.x * 1.3 + seed));
  float body = lnoise(s + vec2(seed, 0.0), a, 0.28 * m);
  float fib = gnoise(vec3(s.x * 2.2, s.y * 9.0, seed + 0.4 * w));
  float d = body + 0.32 * fib + mix(-0.28, 0.12, cov);
  return smoothstep(-0.02, 0.45, d) * (0.75 + 0.25 * fib);
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.3, 1.4, u_opt.x);
  float cov = u_opt.y;
  vec2 sun = vec2(-1.75, -1.25) + u_sun;
  vec2 ds = p - sun;
  float near = exp(-dot(ds, ds) / 3.2);
  // the dawn moves through its colours once and back over the loop
  float k = 0.5 - 0.5 * cos(a);
  vec3 sky = mix(u_pal[1], u_pal[0], smoothstep(0.6, 3.2, length(ds)));
  sky = mix(sky, u_pal[5], 0.4 * near * (0.8 + 0.2 * k));
  vec3 lit = mixh(u_pal[3], u_pal[4], k);
  // the high layer, combed at a slant, and a nearer, softer veil
  vec2 q1 = rot(p + tiltD(-1.0), 0.32) * 1.1;
  float c1 = streaks(q1, a, m, 0.0, cov);
  vec2 q2 = rot(p + tiltD(1.0), 0.22) * 0.7 + vec2(3.0, 1.0);
  float c2 = streaks(q2, a + 1.7, m * 0.8, 11.0, cov * 0.7) * 0.6;
  float facing = sat(0.35 + 0.65 * near * 1.6 - 0.15 * max(p.y, 0.0));
  vec3 cc = mix(u_pal[2], lit, facing);
  vec3 col = mix(sky, cc, c1 * 0.62);
  col = mix(col, mix(u_pal[2], lit, 0.55 * facing + 0.2), c2 * 0.4);
  return outLab(col);
}

// Sheer: a sheer voile curtain drawn across a bright window, moving in a faint draught. It hangs still at the top and
// sways more toward the hem. Where the cloth turns edge-on in a fold the light passes through more of it, so the folds
// read as soft denser stripes; where two panels overlap the cloth is deeper still. The window's frame shows faintly
// through it, out of focus. Perspective parts the curtain from the window behind it.
// Palette: 0 the room beyond the window's light, 1 the cloth in shade, 2 the window light through the cloth, 3 the
// cloth's own colour where it is dense, 4 the window frame seen through, 5 the brightest light.
// Options: x = motion (how strongly the draught moves the cloth), y = folds (few to many).
const float T = 72.0;

// one panel: how much cloth the view crosses, low where it faces the window, high in the folds
float panel(vec2 q, float a, float m, float k, float seed) {
  float hang = smoothstep(1.15, -1.1, q.y);
  float sway = hang * m * (0.55 * sin(a + q.x * 0.8 + seed) + 0.25 * sin(2.0 * a - q.x * 1.3 + seed * 2.0));
  float ph = q.x * k + 1.1 * sin(q.x * 1.4 + seed) + 0.7 * sin(q.x * 0.55 + 2.0 * seed) + sway + 0.4 * hang * sin(q.x * 2.3 - a + seed);
  // where the cloth turns edge-on to us the light crosses much more of it: a fine denser line at each turn, the front
  // turns a little stronger than the back ones; between them the cloth faces us, slightly shaded as it rounds
  float s = sin(ph);
  float c = cos(ph);
  float line = exp(-s * s / (0.05 + 0.03 * u_focus));
  float soft = exp(-s * s / 0.4);
  return 0.2 + line * (0.55 + 0.25 * sign(c)) + 0.12 * soft + 0.14 * c;
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.3, 1.4, u_opt.x);
  float k = mix(4.0, 9.0, u_opt.y);
  // the window behind: a bright soft field with the shadow of its frame
  vec2 wq = p + tiltD(-1.0);
  vec2 lc = vec2(0.35, 0.3) + u_sun;
  float light = exp(-dot((wq - lc) * vec2(0.55, 0.75), (wq - lc) * vec2(0.55, 0.75)));
  float frame = max(gauss(wq.x - 1.22, 0.08), gauss(wq.y - 0.62, 0.07) * smoothstep(0.2, 0.9, wq.x));
  vec3 back = mix(u_pal[0], u_pal[2], light);
  back = mix(back, u_pal[5], 0.4 * light * light);
  back = mix(back, u_pal[4], frame * mix(0.25, 0.14, u_dark) * (0.4 + 0.6 * light));
  // the cloth in front: two panels, the second overlapping the left part
  vec2 q = p + tiltD(1.0);
  float d1 = panel(q, a, m, k, 0.0);
  float d2 = panel(q * vec2(1.0, 1.0) + vec2(0.37, 0.0), a + 1.9, m * 0.85, k * 1.15, 3.7);
  float over = smoothstep(0.12, -0.35, q.x + 0.5 + 0.06 * sin(q.y * 1.7 + a));
  float dens = d1 + over * (0.35 + 0.8 * d2);
  // a faint thread grain along the hang
  float grain = gnoise(vec3(q.x * 140.0, q.y * 3.0, 1.0)) * sat(0.007 / u_px - 0.4);
  float veil = sat(0.2 + 0.5 * dens + 0.03 * grain);
  vec3 cloth = mix(u_pal[1], u_pal[3], sat(dens * 0.8));
  cloth = mix(cloth, u_pal[2], 0.35 * light);
  vec3 col = mix(back, cloth, veil);
  // light caught in the cloth where it faces the window
  col = mix(col, u_pal[5], 0.12 * light * (1.0 - sat(dens)));
  return outLab(col);
}

// Limewash: late sun on a limewashed wall. A glass of water stands on the sill just out of frame, and all it leaves on
// the wall is light: a soft pool tinted by the glass and, inside it, the bright heart-shaped caustic that water in a
// glass focuses, its cusp brightest, trembling as the water settles. No object, only light on plaster. The limewash is
// cloudy and brushed, the way the real finish is; the sun moves a little, so the patch leans and the light breathes.
// Palette: 0 the wall in shade, 1 the wall in sun, 2 the tinted pool of light, 3 the caustic's core, 4 the limewash's
// cloud, 5 the warm edge of the sunlight.
// Options: x = motion (how much the water trembles and the sun moves), y = caustic (soft to bright).
const float T = 76.0;

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.3, 1.4, u_opt.x);
  float ck = mix(0.45, 1.3, u_opt.y);
  // the limewash: cloudy patches and broad crossing brush strokes, fixed on the wall
  float cloud = fbm3(vec3(p * 1.3, 1.0));
  float brush = gnoise(vec3(rot(p, 0.7) * vec2(1.1, 4.5), 2.0)) + gnoise(vec3(rot(p, -0.5) * vec2(1.3, 5.0), 3.0));
  float lime = cloud + 0.22 * brush;
  // the spot of sun from a window to the right, its edge soft
  vec2 sd = vec2(0.3, -0.12) + u_sun;
  float lean = 0.06 * m * sin(a + 1.0);
  vec2 sq = rot(p - sd, 0.32 + lean);
  float spot = smoothstep(0.32, -0.05, max(abs(sq.x - 0.25) - 1.25, abs(sq.y) - 1.7));
  vec3 col = mix(u_pal[0], u_pal[1], spot * (0.9 + 0.1 * sin(a + 0.4)));
  col = mix(col, u_pal[5], 0.35 * spot * smoothstep(-0.3, 0.3, max(abs(sq.x - 0.25) - 1.25, abs(sq.y) - 1.7) + 0.25));
  col = mix(col, u_pal[4], 0.22 * smoothstep(-0.3, 0.5, lime));
  col.x += 0.028 * lime;
  // the light the glass throws: an oblique pool, its cusp toward the glass in the lower right, opening up the wall
  vec2 cusp = vec2(1.1, -0.72) + 0.012 * m * vec2(sin(2.0 * a + 0.3), cos(3.0 * a));
  vec2 ax = normalize(vec2(-0.78 - lean * 1.5, 0.62));
  vec2 dq = p - cusp;
  vec2 q = vec2(dot(dq, ax), dot(dq, vec2(-ax.y, ax.x)) * 1.35);
  float r = length(q);
  float th = atan(q.y, q.x);
  // the caustic: the near part of a cardioid whose cusp sits at the origin, brightest at the cusp and fading along its
  // arms, with the light it gathers lying soft inside; the water's trembling bends it a little
  float A = 0.3 + 0.01 * m * sin(3.0 * a + 1.0);
  float wob = 0.014 * m * lnoise(vec2(cos(th), sin(th)) * 1.5, a, 0.45);
  float rc = A * (1.0 + cos(th)) + wob;
  float w1 = 0.016 + 0.05 * r + 0.008 * u_focus;
  float d1 = r - rc;
  // only the half nearest the cusp gathers enough light to show: an open crescent, brightest at the cusp
  float arms = smoothstep(0.9, 2.2, abs(th)) * exp(-r / (1.2 * A));
  float line = exp(-d1 * d1 / (w1 * w1)) * arms;
  // the water disperses a little: just outside the line the light is tinted, just inside it is whiter
  float d1o = d1 - 1.4 * w1;
  float fringe = exp(-d1o * d1o / (w1 * w1 * 1.5)) * arms;
  float fill = smoothstep(0.02, -0.1, d1) * arms * 0.3;
  float cuspGlow = exp(-r * r / 0.006) * 0.55;
  float caus = line + fill + cuspGlow;
  // the tinted pool the glass throws round it, and the glass's faint grey shade beyond
  vec2 pc = (q - vec2(A * 0.9, 0.0)) * vec2(1.0, 1.25);
  float pool = exp(-dot(pc, pc) / 0.14);
  float shadeRing = sat(exp(-dot(pc, pc) / 0.4) - pool);
  col = mix(col, vec3(col.x * mix(0.9, 0.93, u_dark), mix(col.yz, u_pal[2].yz, 0.3)), sat(shadeRing) * 0.35 * spot);
  col = mix(col, u_pal[2], sat(pool * 0.45 + fringe * 0.45 * ck) * spot);
  col = mix(col, u_pal[3], sat(caus * 0.9 * ck) * spot);
  return outLab(col);
}

// Veil: an aurora seen through high haze. The curtains are there, their foot along a slow wave, their colour turning
// from the foot to the top, but the haze in front softens them to washes of light; where the haze thickens it takes
// their colour and glows, where it thins the curtains show clearer. A few faint stars wait behind it all.
// Palette: 0 the sky high, 1 the sky low, 2 the aurora's foot, 3 the aurora's crown, 4 the haze, 5 the stars.
// Options: x = motion (how much the curtains sway and the haze drifts), y = haze (thin to thick).
const float T = 90.0;

// one curtain: its light at q, a foot that waves, a soft fall above it, and a slow grain of rays
vec2 curtain(vec2 q, float a, float m, float base, float seed) {
  float foot = base + 0.16 * sin(q.x * 0.85 + seed + 0.5 * m * sin(a + seed)) + 0.11 * lnoise(vec2(q.x * 0.9, seed), a, 0.35 * m) + 0.04 * lnoise(vec2(q.x * 2.4, seed + 7.0), a, 0.3 * m);
  float h = q.y - foot;
  float rays = 0.65 + 0.35 * lnoise(vec2(q.x * 3.2 + 0.4 * q.y, seed + 3.0), a, 0.3 * m);
  float lum = smoothstep(-0.13, 0.05, h) * exp(-max(h, 0.0) / 0.55) * rays;
  return vec2(lum, sat(h / 0.6));
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.3, 1.4, u_opt.x);
  float hz = mix(0.35, 1.2, u_opt.y);
  vec2 qf = p + tiltD(-1.0);
  vec3 col = mix(u_pal[1], u_pal[0], smoothstep(-1.0, 1.0, p.y));
  // the stars, faint and behind everything
  vec2 sc = qf * 46.0;
  vec2 cid = floor(sc);
  vec3 sh = hash33(vec3(cid, 5.0));
  float star = step(0.82, sh.z) * smoothstep(0.12, 0.0, length(sc - cid - 0.5 - 0.35 * sh.xy)) * (0.5 + 0.5 * sh.x);
  // two curtains: a far one high and faint, a nearer one lower and brighter
  vec2 c1 = curtain(qf, a, m, 0.18, 1.0);
  vec2 c2 = curtain(p, a + 2.1, m, -0.22, 4.0);
  float lum = c1.x * 0.55 + c2.x;
  float up = mix(c1.y, c2.y, c2.x / (c1.x * 0.55 + c2.x + 1e-4));
  vec3 ac = mix(u_pal[2], u_pal[3], smoothstep(0.05, 0.75, up));
  // the haze in front, drifting: it hides the stars, softens the curtains and glows with their light
  vec2 qn = p + tiltD(1.0);
  float hn = lnoise(qn * vec2(0.5, 2.0) + 2.0, a, 0.3 * m) * 0.65 + gnoise(vec3(qn * vec2(1.4, 4.0), 1.0)) * 0.35;
  float haze = smoothstep(-0.12, 0.5, hn) * hz;
  col = mix(col, u_pal[5], star * u_dark * (1.0 - sat(haze * 1.4)) * 0.7);
  // seen through the haze the curtains soften; the haze itself scatters their light and glows with it
  float seen = lum * (1.0 - 0.5 * sat(haze));
  col = mix(col, ac, sat(seen * 0.75));
  float glowLum = c1.x * 0.55 + c2.x * 0.8 + 0.25 * curtain(qn * 0.8, a, m, -0.1, 4.0).x;
  vec3 hc = mix(u_pal[4], ac, sat(glowLum * 1.1));
  col = mix(col, hc, sat(haze * 0.7) * (0.5 + 0.5 * sat(glowLum + 0.15)));
  return outLab(col);
}

// Glimmer: the lights of an evening seen far out of focus, through a lens wide open. Each light is a soft disc with
// the faint bright rim real bokeh has; near the edges of the frame the lens clips them into cat's eyes, as real lenses
// do. They lie at a few depths, the near ones larger and softer, gathered low and to the sides, and they drift and
// brighten and dim very slowly, as if the camera breathed. The middle stays nearly clear.
// Palette: 0 the sky high, 1 the evening low, 2 the first lights, 3 the second lights, 4 the warm lights, 5 the haze.
// Options: x = motion (how far the lights drift), y = lights (few to many).
const float T = 90.0;

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.3, 1.4, u_opt.x);
  float many = u_opt.y;
  vec3 col = mix(u_pal[1], u_pal[0], smoothstep(-1.1, 1.0, p.y));
  col = mix(col, u_pal[5], 0.3 * exp(-(p.y + 0.55) * (p.y + 0.55) / 0.35));
  for (int i = 0; i < 14; i++) {
    float f = float(i);
    vec3 h = hash33(vec3(f * 7.31 + 0.5, f * 3.17 + 2.3, 9.17));
    float z = 0.5 + 0.5 * h.x;
    float show = smoothstep(f - 0.5, f + 0.5, mix(7.0, 14.0, many));
    vec2 q = p + tiltD(mix(-1.0, 1.0, z));
    // spread across the width, gathered low; the middle is left nearly clear
    float yy = fract(f * 0.4142 + 0.3 + 0.2 * h.z);
    vec2 c = vec2(fract(f * 0.618034 + 0.11) * 3.6 - 1.8, -0.9 + 1.35 * yy * yy);
    float k = (h.y > 0.0) ? 1.0 : -1.0;
    c += orbit(k * a + f * 2.1, (0.04 + 0.05 * z) * m);
    float R = mix(0.08, 0.26, z * z);
    float soft = R * mix(0.1, 0.22, z) + 0.004 + 0.01 * u_focus;
    // the lens clips discs toward the frame's edge: the disc meets a second one shifted toward the centre
    vec2 d1 = q - c;
    vec2 d2 = q - c * (1.0 - 0.1 * R);
    float dd = max(length(d1), length(d2));
    float disc = smoothstep(R + soft, R - soft, dd);
    float rim = smoothstep(R * 0.55, R, dd) * disc;
    float shine = (0.62 + 0.38 * sin(a * (1.0 + floor(h.x * 1.99 + 1.0)) + f * 2.7)) * mix(0.85, 0.55, z);
    float side = 0.35 + 0.65 * smoothstep(0.25, 1.0, abs(c.x) * 0.75 + max(-c.y - 0.2, 0.0));
    vec3 lc = (h.y > 0.3) ? u_pal[4] : ((h.y > -0.35) ? u_pal[3] : u_pal[2]);
    float al = sat(disc * shine * side * (0.85 + 0.25 * rim)) * show;
    col = mix(col, lc, al);
    col.x += mix(0.02, 0.07, u_dark) * al;
  }
  return outLab(col);
}

// Shore: looking straight down at the edge of a calm sea. A thin sheet of water slides up the sand, slows, and slides
// back, again and again, its edge a fine lace of foam; the sand it leaves is wet and holds the sky like a mirror,
// and dries paler further up. The sea beyond deepens toward the top. Slow, quiet and real.
// Palette: 0 dry sand, 1 wet sand, 2 the sky held in the wet sand, 3 the thin water, 4 the foam, 5 the deeper sea.
// Options: x = motion (how far the water runs), y = foam (faint to clear).
const float T = 60.0;

// the reach of the water at x: a run up the sand and a slower slide back, four times a loop, each wave reaching a
// little further or less far than the last, the front oblique to the beach
float reach(float x, float a, float m) {
  float ph = 4.0 * a + 0.55 * x + 0.25 * sin(x * 1.3 + a);
  float run = 0.5 + 0.5 * sin(ph + 0.6 * sin(ph));
  run = run * run * (3.0 - 2.0 * run);
  float big = 0.72 + 0.28 * sin(a + 0.5 * x + 1.0);
  return run * big * (0.2 + 0.2 * m);
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.3, 1.4, u_opt.x);
  float fo = mix(0.3, 1.2, u_opt.y);
  vec2 q = rot(p, 0.12);
  // the sand: fine grain and faint ripple marks, fixed
  float grain = gnoise(vec3(q * 60.0, 1.0)) * sat(0.02 / u_px / 3.0 - 0.2);
  float ripple = gnoise(vec3(q.x * 2.0, q.y * 9.0 + 1.5 * gnoise(vec3(q * 1.2, 3.0)), 2.0));
  float line = 0.36 + 0.05 * sin(q.x * 1.3 + 1.0) + 0.03 * gnoise(vec3(q.x * 2.5, 0.0, 4.0));
  float edge = line - reach(q.x, a, m);
  float top = line - 0.48;
  // how wet the sand is: wet from the highest reach down, drying above it
  float wet = smoothstep(top - 0.25, top + 0.02, q.y);
  vec3 sand = mix(u_pal[0], u_pal[1], wet);
  sand.x += 0.012 * grain + 0.008 * ripple * (1.0 - wet * 0.6);
  // the wet sand holds the sky
  float mirror = wet * smoothstep(top - 0.05, line + 0.1, q.y);
  sand = mix(sand, u_pal[2], 0.6 * mirror * (0.7 + 0.3 * smoothstep(-1.0, 1.0, q.x)));
  // the water: thin at its edge, deeper toward the sea
  float depth = q.y - edge;
  float wa = smoothstep(-0.004 - 0.01 * u_focus, 0.01, depth);
  vec3 water = mix(u_pal[3], u_pal[5], smoothstep(0.0, 0.9, depth));
  water = mix(water, u_pal[2], 0.25 * smoothstep(0.6, 0.0, depth));
  vec3 col = mix(sand, mix(sand, water, 0.35 + 0.65 * smoothstep(0.0, 0.6, depth)), wa);
  // the foam: a bright line on the edge and lace just behind it
  float lace = smoothstep(0.15, 0.55, gnoise(vec3(q.x * 26.0, depth * 34.0, 5.0 + 0.3 * m * sin(a))) * 0.7 + gnoise(vec3(q.x * 9.0, depth * 9.0, 8.0)) * 0.5 + 0.1);
  float foam = gauss(depth - 0.005, 0.006 + 0.004 * u_focus) * 0.7 + lace * gauss(depth - 0.045, 0.04) * 0.4;
  col = mix(col, u_pal[4], sat(foam * fo) * 0.75);
  return outLab(col);
}

// Wisp: a single thread of smoke rising from something burning just below the frame, in still air. Near its source it
// is a fine, steady line; higher up slow waves travel along it, it widens, curls and frays, and finally thins away to
// nothing before the top. A side light catches one edge of it. It keeps to the left third; the rest is calm ground.
// Palette: 0 the ground low, 1 the ground high, 2 the smoke in shadow, 3 the smoke lit, 4 the side light, 5 the warm
// glow near the source.
// Options: x = motion (how much the smoke sways and curls), y = smoke (a thread to a plume).
const float T = 60.0;

// one strand: its density at p (x) and which side of it p lies on (y), rising from x0 with waves that travel up it
vec2 strand(vec2 p, float a, float m, float x0, float seed, float thick) {
  float h = p.y + 1.15;
  float hh = max(h, 0.0);
  float amp = (0.01 + 0.075 * pow(hh, 1.6)) * m;
  float xc = x0 + 0.05 * hh * sin(seed)
           + amp * sin(2.6 * hh - 3.0 * a + seed)
           + amp * 0.6 * sin(4.9 * hh - 5.0 * a + seed * 2.3)
           + 0.05 * pow(hh, 1.4) * lnoise(vec2(hh * 1.3, seed), a, 0.3 * m);
  // higher up the smoke frays: the coordinate is warped more and more
  vec2 wq = vec2(p.x, h);
  float fray = smoothstep(0.5, 1.9, hh);
  float wx = lnoise(wq * 3.2 + seed, a, 0.35) * 0.06 * fray * m + lnoise(wq * 7.0 + seed, a, 0.3) * 0.02 * fray;
  float wd = (0.006 + 0.05 * pow(hh, 1.35)) * thick;
  float dx = (p.x + wx - xc) / wd;
  float fade = smoothstep(0.0, 0.25, hh) * smoothstep(2.35, 1.0, hh);
  return vec2(exp(-dx * dx) * fade / (0.55 + 1.2 * hh * thick), clamp(dx, -1.0, 1.0));
}

// gradient noise whose lattice repeats every P cells along y (P a whole number): a texture can then slide up through
// it without end and come back to itself exactly, so the smoke truly rises, with no cross-fade and no wrap to hide
float pnoise(vec3 p, float P) {
  vec3 i = floor(p);
  vec3 f = p - i;
  vec3 u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
  float y0 = mod(i.y, P);
  float y1 = mod(i.y + 1.0, P);
  float n000 = dot(hash33(vec3(i.x, y0, i.z)), f);
  float n100 = dot(hash33(vec3(i.x + 1.0, y0, i.z)), f - vec3(1.0, 0.0, 0.0));
  float n010 = dot(hash33(vec3(i.x, y1, i.z)), f - vec3(0.0, 1.0, 0.0));
  float n110 = dot(hash33(vec3(i.x + 1.0, y1, i.z)), f - vec3(1.0, 1.0, 0.0));
  float n001 = dot(hash33(vec3(i.x, y0, i.z + 1.0)), f - vec3(0.0, 0.0, 1.0));
  float n101 = dot(hash33(vec3(i.x + 1.0, y0, i.z + 1.0)), f - vec3(1.0, 0.0, 1.0));
  float n011 = dot(hash33(vec3(i.x, y1, i.z + 1.0)), f - vec3(0.0, 1.0, 1.0));
  float n111 = dot(hash33(vec3(i.x + 1.0, y1, i.z + 1.0)), f - vec3(1.0, 1.0, 1.0));
  return 1.6 * mix(mix(mix(n000, n100, u.x), mix(n010, n110, u.x), u.y),
                   mix(mix(n001, n101, u.x), mix(n011, n111, u.x), u.y), u.z);
}

// the smoke higher up, where the thread has broken into a soft, curling plume. Its texture rises steadily: the noise
// coordinate slides down by one whole lattice period (4 cells, and 8 for the finer octave) twice a loop
float plume(vec2 p, float a, float m, float xc, float seed) {
  float h = p.y + 1.15;
  float W = 0.07 + 0.32 * max(h - 0.7, 0.0);
  float dx = (p.x - xc) / W;
  float env = exp(-dx * dx) * smoothstep(0.55, 1.1, h) * smoothstep(2.4, 1.3, h);
  float rise = 4.0 * fract(2.0 * a / TAU);
  vec2 wq = vec2(p.x * 3.0 + 0.6 * sin(h * 2.0 + p.x * 2.0), h * 1.6 - rise);
  // a slow drift of the third coordinate lets the sheets change shape as they climb; it is a closed loop too
  float z = seed + 0.35 * m * sin(a) ;
  float n = pnoise(vec3(wq, z + 0.25 * m * cos(a)), 4.0) + 0.5 * pnoise(vec3(wq * 2.0, z * 1.7 + 2.0), 8.0);
  // the smoke lies in thin curling sheets: the ridges of the noise, softened higher up
  float rid = 1.0 - abs(n);
  float sheets = pow(sat(rid), mix(5.0, 2.0, smoothstep(1.0, 2.2, h)));
  return env * (0.25 + 0.95 * sheets) / (0.5 + 0.6 * max(h - 0.7, 0.0)) * (0.7 + 0.3 * m / 1.35);
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.35, 1.35, u_opt.x);
  float th = mix(0.7, 1.6, u_opt.y);
  vec3 col = mix(u_pal[0], u_pal[1], smoothstep(-1.1, 1.0, p.y + 0.2 * p.x));
  vec2 sl = p - vec2(-1.6, 0.9) - u_sun;
  col = mix(col, u_pal[4], 0.3 * exp(-dot(sl, sl) / 2.2));
  col.x -= 0.02 * smoothstep(0.8, 2.2, length(p * vec2(0.6, 1.0) - vec2(0.3, -0.2)));
  vec2 sr = p - vec2(1.5, -0.6);
  col = mix(col, u_pal[5], 0.18 * exp(-dot(sr, sr) / 1.4));
  vec2 src = p - vec2(-0.72, -1.25);
  col = mix(col, u_pal[5], 0.16 * exp(-dot(src, src) / 0.12));
  vec2 r1 = strand(p, a, m, -0.72, 0.0, th);
  vec2 r2 = strand(p, a + 1.3, m * 1.1, -0.71, 2.4, th * 0.75);
  float d2 = r2.x * smoothstep(-0.3, 0.6, p.y) * 0.7;
  float hh = max(p.y + 1.15, 0.0);
  float xc = -0.72 + 0.08 * hh + 0.08 * m * hh * sin(1.6 * hh - a + 0.5);
  float d3 = plume(p, a, m, xc, 3.0) * th * 0.9;
  float d = r1.x + d2 + d3;
  float lit = 0.5 - 0.5 * mix(r1.y, r2.y, d2 / (r1.x + d2 + 1e-4));
  lit = mix(lit, sat(0.5 - 1.2 * (p.x - xc)), d3 / (d + 1e-4));
  vec3 sc = mix(u_pal[2], u_pal[3], lit);
  col = mix(col, sc, sat(d * 0.75));
  col = mix(col, u_pal[4], sat(d * lit * 0.2));
  return outLab(col);
}

// Apogee: the curve of a planet seen from high orbit, its night side below, and the thin shell of its atmosphere lit
// along the limb by a sun about to rise beyond it. The air glows brightest where the sun is near and fades round the
// curve; faint cloud lies on the dark side, turning slowly with the planet. The sun creeps along the limb and back.
// Palette: 0 space high, 1 space near the limb, 2 the night side, 3 the lit air (inner, warm), 4 the air's outer haze,
// 5 the sun at the limb.
// Options: x = motion (how far the sun travels along the limb), y = air (a thin line to a deep glow).
const float T = 90.0;

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.3, 1.4, u_opt.x);
  float air = mix(0.6, 1.5, u_opt.y);
  vec2 qs = p + tiltD(-1.0);
  vec3 col = mix(u_pal[1], u_pal[0], smoothstep(-0.7, 1.1, qs.y));
  // a few faint stars, dark theme only
  vec2 sc = qs * 38.0;
  vec2 cid = floor(sc);
  vec3 sh = hash33(vec3(cid, 2.0));
  float star = step(0.86, sh.z) * smoothstep(0.1, 0.0, length(sc - cid - 0.5 - 0.35 * sh.xy)) * (0.4 + 0.6 * sh.x);
  // the planet
  vec2 q = p + tiltD(1.0);
  vec2 C = vec2(0.25, -3.35);
  float Rp = 2.75;
  vec2 dc = q - C;
  float r = length(dc);
  float d = r - Rp;
  float ang = atan(dc.x, dc.y);
  // where the sun sits along the limb
  float sa = 0.36 + 0.14 * m * sin(a + 1.1) + 0.35 * u_sun.x;
  float near = gauss(ang - sa, 0.32);
  float wide = gauss(ang - sa, 0.9);
  col = mix(col, u_pal[5], star * u_dark * 0.6 * smoothstep(0.0, 0.3, d));
  // the air above the limb: a bright thin shell and a wide soft haze, both strongest toward the sun
  float shell = exp(-max(d, 0.0) / (0.025 * air)) * smoothstep(-0.012, 0.004, d);
  float haze = exp(-max(d, 0.0) / (0.2 * air)) * smoothstep(-0.03, 0.01, d);
  col = mix(col, u_pal[4], sat(haze * (0.25 + 0.55 * wide) * (0.85 + 0.15 * sin(a + 1.0))));
  // the night side, with faint cloud turning
  vec2 pc = vec2(ang * 3.0, d * 6.0);
  float cl = lnoise(pc * vec2(1.2, 2.5), a, 0.25 * m) * 0.6 + gnoise(vec3(pc * vec2(3.0, 6.0), 4.0)) * 0.4;
  vec3 ground = u_pal[2];
  ground.x += 0.03 * smoothstep(-0.1, 0.5, cl) * (0.4 + 0.6 * wide);
  ground = mix(ground, u_pal[4], 0.22 * exp(d / 0.12) * (0.3 + 0.7 * wide));
  float body = smoothstep(edgePx() * 0.7, -edgePx() * 0.7, d);
  col = mix(col, ground, body);
  col = mix(col, u_pal[3], sat(shell * (0.18 + 0.82 * near) * 0.9));
  // the sun itself, just behind the limb: a small glow and a faint flare along the shell
  vec2 sp = C + Rp * vec2(sin(sa), cos(sa));
  vec2 dsun = q - sp;
  float sun = exp(-dot(dsun, dsun) / 0.004) * 0.7 + exp(-dot(dsun, dsun) / 0.06) * 0.25;
  col = mix(col, u_pal[5], sat(sun * (0.6 + 0.4 * smoothstep(-0.02, 0.02, d))));
  return outLab(col);
}

// Komorebi: sunlight through the leaves of a tree outside, falling on a quiet wall through a window. The leaves throw
// their shadows into the patch of sun, the far ones soft and the near ones clearer, and they sway and turn a little
// as a breeze moves the branches. Outside the patch the wall rests in cool shade.
// Palette: 0 the wall in shade, 1 the shade's second colour, 2 the sun on the wall, 3 the sun's warm core, 4 the
// patch's soft edge, 5 the green light the leaves give back.
// Options: x = motion (how much the breeze moves the leaves), y = leaves (a few to many).
const float T = 60.0;

// one layer of leaves: cells of size 1/sc, each holding one leaf (or none) that sways on its own whole-number rhythm;
// returns how much of the sun they block at p
float leaves(vec2 p, float sc, float a, float m, float many, float seed, float soft) {
  vec2 q = p * sc;
  vec2 c0 = floor(q);
  float sh = 0.0;
  for (int i = 0; i < 9; i++) {
    vec2 c = c0 + vec2(mod(float(i), 3.0) - 1.0, floor(float(i) / 3.0) - 1.0);
    vec3 h = hash33(vec3(c, seed));
    vec3 g = hash33(vec3(c + 17.0, seed + 3.0));
    float there = smoothstep(0.0, 0.25, g.x * 0.5 + 0.5 - 0.25 - 0.35 * many);
    float n = 1.0 + floor((g.y * 0.5 + 0.5) * 2.99);
    float ang = 0.95 + 0.55 * h.z + 0.12 * m * sin(n * a + g.z * 6.28);
    vec2 sw = 0.07 * m * vec2(sin(n * a + h.x * 6.28), cos(n * a + h.y * 6.28));
    vec2 d = rot(q - c - 0.5 - 0.3 * h.xy - sw, ang);
    float L = 0.55 + 0.25 * (g.z * 0.5 + 0.5);
    float u = d.x / L;
    float e = max(abs(u) - 1.0, abs(d.y) - 0.24 * L * (1.0 - u * u));
    sh = max(sh, there * smoothstep(soft, -soft, e));
  }
  return sh;
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.3, 1.4, u_opt.x);
  float many = u_opt.y;
  // the wall in shade, with a faint green light given back by the leaves
  vec3 col = mix(u_pal[1], u_pal[0], smoothstep(-1.2, 1.0, p.y - 0.3 * p.x));
  col = mix(col, u_pal[5], 0.14 * smoothstep(-0.4, 0.6, lnoise(p * 0.7 + 3.0, a, 0.15 * m)));
  // the patch of sun from a window, slanting across the wall
  vec2 sd = rot(p - vec2(0.35, 0.1) - u_sun, -0.35);
  float spot = smoothstep(0.35, -0.2, max(abs(sd.x) - 1.15, abs(sd.y) - 0.72));
  // the leaves of a tree outside throw their shadows into it, the far ones soft, the near ones clearer; where the
  // leaves crowd, toward the upper right, the shadow is deepest
  float crowd = smoothstep(-0.3, 1.5, p.x + p.y * 0.8 + 0.7 * lnoise(p * 0.7 + 9.0, a, 0.1 * m));
  float s1 = leaves(p + tiltD(-1.0), 2.2, a, m * 0.8, many, 1.0, 0.12 + 0.05 * u_focus) * (0.4 + 0.6 * crowd);
  float s2 = leaves(p + tiltD(1.0), 3.4, a + 0.7, m, many * 0.8, 5.0, 0.08 + 0.04 * u_focus) * crowd;
  float lit = spot * (1.0 - 0.45 * s1) * (1.0 - 0.6 * s2);
  vec3 sun = mix(u_pal[2], u_pal[3], smoothstep(0.6, 1.0, lit));
  col = mix(col, u_pal[4], 0.3 * spot);
  col = mix(col, sun, sat(lit * mix(0.85, 0.72, u_dark)));
  return outLab(col);
}

// Prairie: a field of tall grass running to a low horizon under a soft sky, seen a little out of focus. Gusts of wind
// cross it one after another, and where they pass the grass bends and shows its paler side, so broad waves of light
// roll slowly over the field toward the far edge. The horizon hazes into the sky; a low sun warms one side.
// Palette: 0 the sky high, 1 the sky at the horizon, 2 the far field in haze, 3 the field near, 4 the bent grass's
// pale side, 5 the low sun.
// Options: x = motion (how strong the gusts are), y = grass (smooth to fine).
const float T = 60.0;

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.3, 1.4, u_opt.x);
  float gr = u_opt.y;
  float hor = 0.38 + 0.025 * sin(p.x * 1.1 + 0.4) + 0.012 * sin(p.x * 2.9 + 2.0);
  vec2 sun = vec2(1.15, 0.52) + u_sun;
  vec2 ds = (p - sun) * vec2(0.7, 1.4);
  float glow = exp(-dot(ds, ds) / 0.5);
  vec2 qs = p + tiltD(-1.0);
  vec3 sky = mix(u_pal[1], u_pal[0], smoothstep(hor - 0.05, 1.1, qs.y));
  sky = mix(sky, u_pal[5], 0.45 * glow);
  // the field in its own ground plane: depth grows toward the horizon
  vec2 q = p + tiltD(1.0);
  float below = hor - q.y;
  float z = 1.0 / max(below + 0.06, 0.05);
  vec2 g = vec2(q.x * z, z);
  // the grass: the heads mottle the field in its own plane, finer toward the horizon and faded where they would be
  // finer than a pixel; near the bottom, out-of-focus blades stand upright
  float fine = sat(0.06 / (u_px * z * z) - 0.4);
  float st = gnoise(vec3(g.x * mix(1.4, 3.0, gr), g.y * mix(2.0, 4.0, gr), 1.0)) * 0.65 + gnoise(vec3(g.x * mix(3.0, 6.5, gr), g.y * mix(4.5, 9.0, gr), 2.0)) * 0.35 * fine;
  // the gusts: waves of bending that travel across the field, their fronts curved by slow noise
  float w1 = sin(g.x * 0.55 + g.y * 1.3 - 3.0 * a + 0.8 * lnoise(g * vec2(0.25, 0.4), a, 0.3));
  float w2 = sin(g.x * 0.9 - g.y * 0.7 - 2.0 * a + 1.7 + 0.6 * lnoise(g * vec2(0.3, 0.3) + 5.0, a, 0.3));
  float bend = smoothstep(0.2, 1.0, w1) * 0.65 + smoothstep(0.4, 1.0, w2) * 0.35;
  bend *= mix(0.5, 1.0, sat(m / 1.4)) * sat(1.4 - 1.5 * z * z * u_px);
  float haze = smoothstep(0.55, 0.0, below);
  vec3 field = mix(u_pal[3], u_pal[2], haze);
  field = mix(field, u_pal[4], bend * 0.75 * (1.0 - 0.5 * haze));
  field.x += 0.035 * st * sat(0.2 / (u_px * z * z * 4.0)) * (1.0 - haze) * (0.6 + 0.4 * bend);
  float nearB = smoothstep(-0.35, -1.0, q.y);
  float blades = gnoise(vec3(q.x * mix(7.0, 14.0, gr) + 0.25 * sin(q.y * 2.0 + q.x) + 0.04 * bend, q.y * 0.9, 3.0));
  field = mix(field, mix(u_pal[3], u_pal[4], 0.5 + 0.5 * blades), nearB * 0.35 * smoothstep(-0.1, 0.5, abs(blades)));
  field = mix(field, u_pal[5], 0.2 * glow * (1.0 - smoothstep(0.0, 0.8, below)));
  float edge = smoothstep(-0.01 - 0.004 * u_focus, 0.02, below);
  vec3 col = mix(sky, field, edge);
  return outLab(col);
}

// Fathom: looking up from a few metres under a calm sea. The whole sky is squeezed into one round window overhead (the
// window real divers see, set by the angle at which water bends light), its rim brightest where the horizon is
// pressed together and trembling with the small waves above. Outside it the surface is a mirror of the deep. Soft
// shafts of light lean down from the window and fade into blue.
// Palette: 0 the deep, 1 the water near the surface, 2 the sky in the window, 3 the bright rim, 4 the shafts of light,
// 5 the sun in the window.
// Options: x = motion (how much the surface trembles and the shafts sway), y = clarity (murky to clear).
const float T = 64.0;

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.3, 1.4, u_opt.x);
  float cl = mix(0.5, 1.3, u_opt.y);
  vec2 W = vec2(-0.55, 1.18);
  // the deep: darker away from the window
  vec2 qd = p + tiltD(-1.0);
  float dist = length((qd - W) * vec2(0.8, 1.0));
  vec3 col = mix(u_pal[1], u_pal[0], smoothstep(0.4, 2.6, dist));
  // the shafts, fanning down from the window and swaying
  vec2 dw = p - W;
  float ang = atan(dw.x, -dw.y);
  float sh = lnoise(vec2(ang * 6.0, 1.0), a, 0.32 * m) * 0.6 + lnoise(vec2(ang * 13.0, 3.0), a, 0.28 * m) * 0.4;
  float shaft = smoothstep(0.05, 0.6, sh) * smoothstep(2.8, 0.7, length(dw)) * smoothstep(0.55, 0.95, length(dw));
  col = mix(col, u_pal[4], sat(shaft * 0.32 * cl));
  // the window: its edge rippled by the small waves, the sky squeezed inside it
  vec2 qw = p + tiltD(1.0);
  vec2 dq = (qw - W) * vec2(1.0, 1.12);
  float r = length(dq);
  float wa = atan(dq.y, dq.x);
  vec2 cw = vec2(cos(wa), sin(wa));
  float rip = 0.024 * m * lnoise(cw * 2.2, a, 0.4) + 0.009 * (0.5 + 0.5 * m) * lnoise(cw * 7.0 + 3.0, a, 0.5);
  float R = 0.88 + rip;
  float ed = r - R;
  float inside = smoothstep(0.03 + 0.01 * u_focus, -0.025 - 0.01 * u_focus, ed);
  float u = sat(r / R);
  vec3 sky = mix(u_pal[2], u_pal[3], smoothstep(0.55, 1.0, u));
  vec2 sn = dq - vec2(0.32, -0.2) - u_sun;
  sky = mix(sky, u_pal[5], 0.65 * exp(-dot(sn, sn) / 0.05));
  // the sky trembles too: a faint net of brighter light over it
  float tw = lnoise(dq * 5.0, a, 0.35 * m);
  sky.x += 0.02 * tw;
  col = mix(col, sky, inside * 0.92);
  // the bright rim, and the darker ring just outside it where the surface turns to a mirror
  col = mix(col, u_pal[3], 0.4 * exp(-(ed * ed) / 0.0016));
  col.x -= 0.012 * exp(-((ed - 0.07) * (ed - 0.07)) / 0.006);
  return outLab(col);
}

// Anodized: a sheet of spun, anodized aluminium, its brushing in fine circles round a centre far off the lower left.
// Light on circular brushing gathers into a broad radial streak, the way it does on a machined lid; as the light moves
// slowly the streak swings round the centre and the fine circles shimmer inside it. The colour is the metal's own dye.
// Palette: 0 the metal in shade, 1 the metal's body, 2 the lit metal, 3 the streak of light, 4 the second tint the
// curve of the sheet catches, 5 the brightest specular.
// Options: x = motion (how far the light swings), y = brushing (fine to coarse).
const float T = 72.0;

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.3, 1.4, u_opt.x);
  float br = u_opt.y;
  vec2 S = vec2(-2.1, -1.55);
  vec2 d = p - S;
  float r = length(d);
  float ang = atan(d.y, d.x);
  // the brushing: circles of slightly different depth, band-limited so they never alias at small sizes
  float f1 = mix(110.0, 45.0, br);
  float f2 = mix(260.0, 120.0, br);
  float k1 = sat(0.5 / (f1 * u_px) - 0.6);
  float k2 = sat(0.5 / (f2 * u_px) - 0.6);
  float bru = gnoise(vec3(r * f1, ang * 1.4, 1.0)) * 0.6 * k1 + gnoise(vec3(r * f2, ang * 2.5, 2.0)) * 0.4 * k2
            + 0.3 * gnoise(vec3(r * 7.0, ang * 1.2, 3.0)) + 0.45 * gnoise(vec3(r * 24.0, ang * 0.9, 4.0)) * sat(0.5 / (24.0 * u_px) - 0.6);
  // the streak: where the brushing's tangent faces the light, the radial line toward the light's direction
  float la = 0.6 + 0.15 * m * sin(a + 1.1) + 0.04 * m * sin(2.0 * a + 1.0) + 0.3 * u_sun.x;
  float off = ang - la;
  float streak = gauss(off, 0.11 + 0.02 * sin(a + 0.5)) * 0.65 + gauss(off, 0.32) * 0.4;
  streak *= smoothstep(0.9, 2.2, r) * smoothstep(5.6, 3.0, r);
  // the sheet bends gently, so one side catches a second, cooler tint
  vec3 col = mix(u_pal[0], u_pal[1], smoothstep(-1.2, 1.2, p.y + 0.4 * p.x));
  col = mix(col, u_pal[4], 0.3 * smoothstep(0.2, 1.6, p.x - 0.6 * p.y));
  col = mix(col, u_pal[2], 0.45 * gauss(off, 0.5));
  col.x += 0.008 * bru + 0.006 * sin(r * 15.0 + 0.6 * gnoise(vec3(r * 2.0, ang, 5.0)));
  col = mix(col, u_pal[3], sat(streak * (0.88 + 0.25 * bru)) * 0.7);
  col = mix(col, u_pal[5], sat(pow(streak, 3.0) * (0.7 + 0.6 * bru)) * 0.3);
  return outLab(col);
}
